INSERT INTO culture_data.culture_palaces_clubs VALUES ('Коротовский Дом культуры', 'Череповецкий район', 'Europe/Moscow', 'ул Ленина,д 12', NULL, 'обл Вологодская,р-н Череповецкий,д Коротово,ул Ленина,д 12', '{"type": "Point", "coordinates": [37.473545, 58.95674]}', '<p><span>Работа Коротовского Дома культуры направлена на создание единого культурного пространства, обеспечивающего оптимальные условия для развития культуры поселения, удовлетворение потребностей населения в культурных ценностях и способствует формированию культурного самосознания граждан на территории поселения. Коротовский ДК – территория творчества, уникальная многофункциональная площадка, активно работающая по направлениям: театрально-концертная, досуговая, выставочная и спортивная деятельность. В ДК действует 18 клубных формирований: два вокальных ансамбля, кукольный театр, спортиные, художественные и танцевальные кружкию.</span></p>', 'http://uloma.ru', 'korotovosko@mail.ru', '[{"value": "78202661279", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/5fa3d34dff27e866d0528ba4e0b2bfb4.jpg", "title": "SEynPquZd80.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МУК «Коротовское СКО»', 'Череповецкий район', 'Europe/Moscow', 'ул Ленина,д 12', NULL, 'обл Вологодская,р-н Череповецкий,д Коротово,ул Ленина,д 12', NULL, 3523014500, 'mincult', 'Череповецкий район', 'Europe/Moscow', NULL, 20391, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 206, "name": "Народное творчество", "sysName": "narodnoe-tvorchestvo"}, {"id": 214, "name": "Любительские театры", "sysName": "lyubitelskie-teatry"}, {"id": 254, "name": "Изобразительное искусство", "sysName": "izobrazitelnoe-iskusstvo"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 34899, '[{"url":"https://www.culture.ru/institutes/35969/korotovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/19147pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2018-05-14 13:37:40+03', '2023-03-28 14:38:50+03', '0101000020E61000009817601F9DBC42403563D174767A4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Ягановский сельский дом культуры', 'Череповецкий район', 'Europe/Moscow', 'ул Набережная,д 28', NULL, 'обл Вологодская,р-н Череповецкий,с Яганово,ул Набережная,д 28', '{"type": "Point", "coordinates": [38.133232, 59.334764]}', '<p>Муниципальное учреждение культуры «Ягановское социально –культурное объединение» функционирует с 9 декабря 2005 года.</p><p> </p><p>На базе «Ягановское СКО» организованы кружки самодеятельного народного творчества и клубы по интересам, проходят мастер классы по народной культуре и декоративно –прикладному искусству.</p><p>Ежегодно проходят мероприятия приуроченные к календарным праздникам: День Победы, День защитника Отечества, Международный женский День 8 Марта, День пожилых людей, Новый год, Рождество и др. Так же проходят массовые праздники и фестивали: День села, Масленица, районный фестиваль сапов.</p><p>В данным момент активно ведется работа по созданию краеведческого музея.</p><p>Воспитанники клубных формирований принимают участие в районных и областных мероприятиях.</p>', 'http://yagan-sko.kulturu.ru', 'dk865@mail.ru', '[{"value": "79212369151", "comment": ""}, {"value": "79212369151", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/f3eed370dcddf9780e745ad97ad7c264.jpg", "title": "kdk2187.jpg"}', '[{"url": "https://all.culture.ru/uploads/59f7ab4362196264fabff703374ff9e9.jpg", "title": "xBeKEeqWuWk.jpg"}, {"url": "https://all.culture.ru/uploads/0b0b700d7029430bcd4f24a9b992feb7.jpg", "title": "fXBZ1wHTj54.jpg"}, {"url": "https://all.culture.ru/uploads/d341f6b29509e5f7b8ab0c1a92bc42ac.jpg", "title": "хор.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МУК «Ягановское социально-культурное объединение» Ягановского СП', 'Череповецкий район', 'Europe/Moscow', 'ул Набережная,д 28', NULL, 'обл Вологодская,р-н Череповецкий,с Яганово,ул Набережная,д 28', NULL, 3523014564, 'mincult', 'Череповецкий район', 'Europe/Moscow', '[{"network":"vk","name":"МУК «Ягановское СКО»","networkId":"216669361","updateDate":"2022-11-13T21:19:16Z","createDate":"2022-11-13T21:19:16Z","accountId":42777,"postingGroupId":36975}]', 20196, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', '[{"hosting":"vk","id":"<iframe src=\"//vk.com/video_ext.php?oid=218124625&id=456239021&hash=1d1411d6c1c0fbe3&hd=2\" width=\"853\" height=\"480\" frameborder=\"0\" allowfullscreen></iframe>"},{"hosting":"vk","id":"<iframe src=\"//vk.com/video_ext.php?oid=218124625&id=456239023&hash=ec1b415032c47d14&hd=2\" width=\"853\" height=\"480\" frameborder=\"0\" allowfullscreen></iframe>"},{"hosting":"vk","id":"<iframe src=\"//vk.com/video_ext.php?oid=218124625&id=171756866&hash=2acf509c4fb04b27&hd=2\" width=\"853\" height=\"480\" frameborder=\"0\" allowfullscreen></iframe>"}]', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 34422, '[{"url":"https://www.culture.ru/institutes/35721/yaganovskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/18822pl","serviceName":"Афиша7"},{"url":"http://afisha.sputnik.ru/places/Yaganovskiy-Dom-kulturi-328","serviceName":"sputnik"}]', NULL, NULL, NULL, NULL, '2018-04-11 13:34:31+03', '2023-03-28 10:03:50+03', '0101000020E6100000ED6305BF0D11434067F0F78BD9AA4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Нюксенский этнокультурный центр «Пожарище»', 'Нюксенский район', 'Europe/Moscow', 'д 25', 'авт. «Нюксеница – Пожарище» один раз в день', 'обл Вологодская,р-н Нюксенский,д Пожарище,д 25', '{"type": "Point", "coordinates": [44.07472171211021, 60.474300560123666]}', '<p>Этнокультурный центр является важным туристским объектом Вологодской области, как юридическое лицо создан в 2008 году. Возрождение созидательного народного мировоззрения, воссоздание праздников, гуляний, обрядов, предметов народного быта и искусства, приобщение к культурному наследию – важнейшие направления деятельности центра. </p><p>Восстановлением региональных традиций Уфтюги занимаются участники шести клубных формирований самодеятельного народного творчества и клубы по интересам «Народный архив» и «Лад». Все направления работы творческих формирований имеют культурно-познавательную значимость, призваны пробудить интерес к малой родине, к родовым корням. Кроме заслуженного коллектива народного творчества фольклорно-этнографического ансамбля «Уфтюжаночка» почетное звание «образцовый» имеет самодеятельный фольклорный театр. </p><p>В помещении экспозиционного зала работают сменные фольклорно-этнографические выставки, обеспечивающие доступ желающих к фондам. Организована уличная выставка исторических банеров «Сохраняя наследие», «Традиционный народный костюм Уфтюгско-Кокшенгского пограничья», «Праздничные головные платки: шелковики, репсовики, аглицкие», «Семейные реликвии», «Изготовлено по старинным образцам», «Этнографические куклы из фондов этнокультурного центра», «Куклы бабушки Поли», фотовыставка «Откроем мир забытых вещей и названий». </p>', 'https://рэц-пожарище.рф', 'centruftuga@mail.ru', '[{"value": "78174722160", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/4228c3761d19e65f21814d534834f2d7.jpg", "title": "80c4959b-bcdf-57a4-86ff-f2db2b0a2b1a.jpg"}', '[{"url": "https://all.culture.ru/uploads/ece9e358e3d6942d678a8e900604a51c.jpg", "title": "m0r6NBCCl70.jpg"}, {"url": "https://all.culture.ru/uploads/bae91f684e5e49191277683fb387102a.jpg", "title": "fta_j6o4DQQ.jpg"}, {"url": "https://all.culture.ru/uploads/cd6e888b6eb25551121256629434f9b1.jpg", "title": "yl8Z6m8Jjz0.jpg"}, {"url": "https://all.culture.ru/uploads/952813e6836a94ba2202bfb99f029e9c.jpg", "title": "kollektiv.jpg"}, {"url": "https://all.culture.ru/uploads/ecb63ae65ee85fdf3bc179a4046e2149.jpg", "title": "w_d5cc654d.jpg"}, {"url": "https://all.culture.ru/uploads/0e47b4a12873427eeeeed2f0edc15b0f.jpg", "title": "69vcchaowfu.jpg"}, {"url": "https://all.culture.ru/uploads/d9dc1fe472b4fe8a79b6962d55e4e76f.jpg", "title": "07.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУК и Т «НЭЦ Пожарище»', 'Нюксенский район', 'Europe/Moscow', '25 д', NULL, 'обл Вологодская,р-н Нюксенский,д Пожарище,25 д', NULL, 3515004040, 'mincult', 'Нюксенский район', 'Europe/Moscow', NULL, 36574, '[{"id": 24, "name": "История", "sysName": "istoriya"}, {"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 152, "name": "Этнография", "sysName": "etnografiya"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 83240, '[{"url":"https://afisha7.ru/nyuksenica/dvorcy-kultury-i-kluby/110596pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/96189/nyuksenskii-etnokulturnyi-centr-pozharishe","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2024-02-19 14:26:48+03', '2024-02-19 16:18:36+03', '0101000020E610000041E8267B90094640521A79E1B53C4E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Никольский сельский дом культуры', 'Кадуйский район', 'Europe/Moscow', 'ул Городская,д 4', NULL, 'обл Вологодская,р-н Кадуйский,с Никольское,ул Городская,д 4', '{"type": "Point", "coordinates": [37.179123, 59.355228]}', '<p><span>Никольский сельский дом культуры создан в августе 1968 года для организации досуга и приобщения жителей сельского поселения к творчеству, культурному развитию и самообразованию, любительскому искусству и ремеслам. </span></p> <p><span>В учреждении работают любительские творческие коллективы, кружки, студии и другие клубные формирования. У детей пользуется популярностью клуб «МАСТЕР.ок», клуб «Веселая горница», клуб «Карусель». Для юношества создан клуб «Сверстники» и КВН. Взрослое население с удовольствием посещает клуб «Огонек», клуб «Дом», мини-театр «Миниатюра». </span></p><p><span>Большое внимание сотрудники Дома культуры уделяют развитию коллективов художественной самодеятельности. Ансамбль ветеранов «Вдохновение», народный ансамбль лирической песни «Зоренька», детский ансамбль танца «Веселинка», детский ансамбль «Задоринки» не раз становились лауреатами районных и межмуниципальных конкурсов. </span></p> <p><span></span><span></span><span>На базе Никольского сельского клуба ежегодно проходит М</span>ежмуниципальный фестиваль-конкурс художественной самодеятельности среди сельских учреждений культуры «Мое село – моя Россия». <span>Работники Дома культуры оказывают консультативную, методическую и организационно-творческую помощь в подготовке и проведении культурно-досуговых мероприятий.</span></p>', NULL, 'mkuk.ndk@yandex.ru', '[{"value": "78174234168"}]', '{"url": "https://all.culture.ru/uploads/61c68358b70e7e900c49f8e02f88a1fe.jpg", "title": "1.jpg"}', '[{"url": "https://all.culture.ru/uploads/92ad729e179a09756e8b84928ec4bf8d.jpg", "title": "3d72ecb6a073b0910534501f34f2cd1d.jpg"}, {"url": "https://all.culture.ru/uploads/05e70906b5f8e91f51e8492696e67ea3.jpg", "title": "WWrV3IueZ8s.jpg"}, {"url": "https://all.culture.ru/uploads/ae35a4a2c574525652f27a0dfabdba21.jpg", "title": "e1ba62ecd02faaa69f13ca0143260311.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУ «Кадуйский ЦКР»', 'Вологодская область', 'Europe/Moscow', 'ул Строителей,д 2', NULL, 'обл Вологодская,рп Кадуй,ул Строителей,д 2', NULL, 3510010837, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"ok","name":"Культура. Кадуй","networkId":"61103236120724","updateDate":"2024-02-16T11:35:59Z","createDate":"2024-02-16T11:35:59Z","accountId":49941,"postingGroupId":44748}]', 36609, '[{"id": 25, "name": "Классическое искусство", "sysName": "klassicheskoe-iskusstvo"}, {"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, NULL, '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "15:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 83231, '[{"url":"https://www.culture.ru/institutes/96178/nikolskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kaduy/dvorcy-kultury-i-kluby/110613pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2024-02-19 08:18:13+03', '2024-02-20 09:20:26+03', '0101000020E61000000F7BA180ED964240CE4F711C78AD4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Новолукинский дом культуры', 'Бабаевский район', 'Europe/Moscow', 'д 13', NULL, 'обл Вологодская,р-н Бабаевский,д Новое Лукино,д 13', '{"type": "Point", "coordinates": [36.123153, 59.883205]}', '<p><span>Новолукинский<span> </span>дом культуры – это центр культуры и досуга населения<span> </span>д. Новое-Лукино и близлежащих деревень.<span> </span>На территории д. Новое-Лукино находятся библиотека, колхоз, почта, ФАП. </span>Здание было построено в 1964 году. Зрительный зал рассчитан на 100 мест.</p> <p><span>Заведующий филиалом –<span> </span>Елена Евгеньевна Ершова.</span></p> <p><span><span> </span>Штат учреждения составляет 2 человека:<span> </span>заведующий<span> </span>и художественный руководитель. Оба специалиста имеют профессиональное образование в культуре.<span> </span></span></p> <p><span>Осуществляют деятельность 10 клубных формирований, в которых занимаются 111 человек от 7 лет до 75 лет:<span> </span></span></p> <ol><li><span>Вокальная группа «Лукиночка».</span><span></span></li><li><span>Театральный кружок «Лицедеи».</span><span></span></li><li><span>Кружок «Сольное пение».</span><span></span></li><li><span>Клуб молодой бабушки «Золотое сердечко».</span><span></span></li><li><span>Вокальная группа «РетроТЛ».</span><span></span></li><li><span>Кружок «Наши руки не для скуки».</span><span></span></li><li><span>Клуб ветеранов «Старинные напевы».</span><span></span></li><li><span>Клуб игрового дня «Гном».</span><span></span></li><li><span>Интеллектуальный клуб «ЧГК».</span><span></span></li><li><span>Клуб «Бильярд».</span></li></ol> <p><span>Участниками клубных формирований также являются работники различных сфер деятельности: торговые работники, врачи, бухгалтера, мастера лесной промышленности, школьники.</span></p> <p><span>Творческие коллективы принимают активное участие во всех поселенческих мероприятиях, ярмарках и фестивалях. Осуществляют выездные концерты в отдаленные деревни, дома ветеранов. Проводят выездные праздники малых деревень.</span><span><span> </span></span></p> <p><span> </span></p> <p style="text-align:justify"><span></span></p>', NULL, NULL, NULL, '{"url": "https://all.culture.ru/uploads/c6dafe03536327fa3864dbc73b8fa998.jpg", "title": "Н Лукино.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МАУК «Бабаевский центр культурного развития»', 'Бабаевский район', 'Europe/Moscow', 'пл Привокзальная,1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,пл Привокзальная,1', NULL, 3501008870, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Володинский Дом культуры","networkId":"158838778","updateDate":"2018-10-12T11:09:38Z","createDate":"2018-10-12T11:09:38Z","accountId":22721,"postingGroupId":20087},{"network":"vk","name":"Кдц Бабаево","networkId":"275144982","isPersonal":true,"updateDate":"2018-10-12T11:09:46Z","createDate":"2018-10-12T11:09:46Z","accountId":22721,"postingGroupId":20088},{"network":"vk","name":"МБУК \"Бабаевский центр культурного развития\"","networkId":"23582611","updateDate":"2018-10-12T11:09:31Z","createDate":"2018-10-12T11:09:31Z","accountId":22721,"postingGroupId":20086}]', 20369, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 74997, '[{"url":"https://www.culture.ru/institutes/87970/novolukinskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/92106pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=c4dce4b5-cc76-45fe-918c-f8853b4a457d&shareType=venue","serviceName":"ФанТам"}]', 74997, NULL, NULL, NULL, '2023-01-17 11:51:00+03', '2025-03-06 15:42:20+03', '0101000020E6100000C0B33D7AC30F4240F35487DC0CF14D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Новостаринский дом культуры', 'Бабаевский район', 'Europe/Moscow', 'д 66', NULL, 'обл Вологодская,р-н Бабаевский,д Новая Старина,д 66', '{"type": "Point", "coordinates": [35.985432, 59.992839]}', '<p><span><span> </span>Новостаринский дом культуры с 2016 года </span> располагается в одном здании с библиотекой, медпунктом и администрацией бывшего Борисовского поселения.</p> <p><span>В учреждении осуществляют творческую деятельность 5 клубных формирований, в которых занимаются 58 человек от 8 до 75 лет:<span> </span></span></p> <ul><li><span>вокальная группа «Бабье лето»;</span></li><li><span>театральный кружок «Маски-шоу»;</span></li><li><span>детский клуб «ВсеЗнайка»;</span></li><li><span>клуб ветеранов «Завалинка»;</span></li><li><span>молодежный клуб «Диско».</span></li></ul> <p><span> </span></p> <p><span>Творческие коллективы Новостаринского дома культуры принимают активное участие во всех поселенческих мероприятиях, районных ярмарках и фестивалях, осуществляют выездные концерты в соседние деревни. <span> </span></span></p> <p><span><span> </span></span><span></span></p>', NULL, NULL, NULL, '{"url": "https://all.culture.ru/uploads/b8fe881d1b5aa3b8579226ddec60fe70.jpg", "title": "НСтарина.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МАУК «Бабаевский центр культурного развития»', 'Бабаевский район', 'Europe/Moscow', 'пл Привокзальная,1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,пл Привокзальная,1', NULL, 3501008870, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Володинский Дом культуры","networkId":"158838778","updateDate":"2018-10-12T11:09:38Z","createDate":"2018-10-12T11:09:38Z","accountId":22721,"postingGroupId":20087},{"network":"vk","name":"Кдц Бабаево","networkId":"275144982","isPersonal":true,"updateDate":"2018-10-12T11:09:46Z","createDate":"2018-10-12T11:09:46Z","accountId":22721,"postingGroupId":20088},{"network":"vk","name":"МБУК \"Бабаевский центр культурного развития\"","networkId":"23582611","updateDate":"2018-10-12T11:09:31Z","createDate":"2018-10-12T11:09:31Z","accountId":22721,"postingGroupId":20086}]', 20369, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 74994, '[{"url":"https://www.culture.ru/institutes/87967/novostarinskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/90568pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=b0a443bb-4e88-42e2-8e8d-b28735f6e3c5&shareType=venue","serviceName":"ФанТам"}]', 74994, NULL, NULL, NULL, '2023-01-17 11:41:11+03', '2025-03-06 16:08:38+03', '0101000020E61000004837C2A222FE4140BF982D5915FF4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Пожарский дом культуры', 'Бабаевский район', 'Europe/Moscow', 'ул Школьная,д 2', NULL, 'обл Вологодская,р-н Бабаевский,д Пожара,ул Школьная,д 2', '{"type": "Point", "coordinates": [36.099824, 59.956615]}', '<p>Пожарский дом культуры – это центр культуры и досуга населения бывшего сельского поселения Пожарское. На территории бывшего поселения Пожарское находятся детский сад, начальная школа, колхоз «ПК Пожарское», почта, ФАП, магазины. Здание было построено в 1970 году. Зрительный зал рассчитан на 100 мест.<br /></p> <p>Заведующий филиалом – Татьяна Викторовна Матвеева.</p> <p>С 2016 года, в связи с объединением и оптимизацией поселений, штат Пожарского дома культуры составляет 2 человека: заведующий и культорганизатор по совместительству. Оба специалиста имеют профессиональное образование в культуре. </p> <p>Осуществляют деятельность 9 клубных формирований, в которых занимаются 108 человек от 6 лет до 70 лет: </p> <ol><li>Вокальная группа «Зоренька».</li><li>Театральный кружок «Задоринки».</li><li>Кружок «Сольное пение».</li><li>Клуб пенсионеров «Общение».</li><li>Интеллектуальный клуб «Гарри Поттер».</li><li>Клуб игрового общения для молодежи.</li><li>Клуб «Веселая продленка».</li><li>Кружок «Очумелые ручки».</li><li>Клуб семейные встречи «25+».</li></ol> <p>Участниками клубных формирований также являются работники различных сфер деятельности: торговые работники, врачи, бухгалтера, мастера лесной промышленности, школьники.</p> <p>Творческие коллективы принимают активное участие во всех поселенческих мероприятиях, ярмарках и фестивалях. Осуществляют выездные концерты в отдаленные деревни, дома ветеранов. Проводят выездные праздники малых деревень.</p> <p>В 2022 году дом культуры принял участие в программе губернатора области «Сельский дом культуры». Проведен капитальный ремонт на 3 356 430 рублей.</p>', NULL, NULL, NULL, '{"url": "https://all.culture.ru/uploads/b5fd9e987ba5de0408b6a6b385c4b44b.jpg", "title": "пожара.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МАУК «Бабаевский центр культурного развития»', 'Бабаевский район', 'Europe/Moscow', 'пл Привокзальная,1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,пл Привокзальная,1', NULL, 3501008870, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Володинский Дом культуры","networkId":"158838778","updateDate":"2018-10-12T11:09:38Z","createDate":"2018-10-12T11:09:38Z","accountId":22721,"postingGroupId":20087},{"network":"vk","name":"Кдц Бабаево","networkId":"275144982","isPersonal":true,"updateDate":"2018-10-12T11:09:46Z","createDate":"2018-10-12T11:09:46Z","accountId":22721,"postingGroupId":20088},{"network":"vk","name":"МБУК \"Бабаевский центр культурного развития\"","networkId":"23582611","updateDate":"2018-10-12T11:09:31Z","createDate":"2018-10-12T11:09:31Z","accountId":22721,"postingGroupId":20086}]', 20369, '[{"id": 26, "name": "Современное искусство", "sysName": "sovremennoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 74989, '[{"url":"https://www.culture.ru/institutes/87976/pozharskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/92105pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=39a914ff-3c7c-4da6-93d1-f86b2c0163af&shareType=venue","serviceName":"ФанТам"}]', 74989, NULL, NULL, NULL, '2023-01-17 11:20:13+03', '2025-03-06 16:02:16+03', '0101000020E61000008EAD6708C70C424078EE3D5C72FA4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Борисовский дом культуры', 'Бабаевский район', 'Europe/Moscow', 'ул Комсомольская,д 2', NULL, 'обл Вологодская,р-н Бабаевский,с Борисово-Судское,ул Комсомольская,д 2', '{"type": "Point", "coordinates": [36.003767, 59.907031]}', '<p>В Борисовском доме культуры работают 3 специалиста: художественный руководитель, балетмейстер, специалист по жанрам творчества. Их них двое – с профессиональным образованием в культуре.</p> <p><span>В учреждении ведут деятельность 20 клубных формирований <span>разной направленности</span>: <span>танцевальные, вокальные, театральные, клубы ветеранов и инвалидов, детские клубы, развлекательные</span>, <span>творческие. В них </span> занимаются 325 человек от 6 до 70 лет. </span><span></span></p> <p><span>Творческие формирования – лауреаты и дипломанты различных конкурсов и фестивалей районного, областного, межрегионального, российского, международного уровня. 3 коллектива имеют звание «Народный самодеятельный коллектив». </span></p>', NULL, NULL, NULL, '{"url": "https://all.culture.ru/uploads/15cb8120d3567c2ef70424317d6c98a6.jpg", "title": "борисово.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МАУК «Бабаевский центр культурного развития»', 'Бабаевский район', 'Europe/Moscow', 'пл Привокзальная,1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,пл Привокзальная,1', NULL, 3501008870, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Володинский Дом культуры","networkId":"158838778","updateDate":"2018-10-12T11:09:38Z","createDate":"2018-10-12T11:09:38Z","accountId":22721,"postingGroupId":20087},{"network":"vk","name":"Кдц Бабаево","networkId":"275144982","isPersonal":true,"updateDate":"2018-10-12T11:09:46Z","createDate":"2018-10-12T11:09:46Z","accountId":22721,"postingGroupId":20088},{"network":"vk","name":"МБУК \"Бабаевский центр культурного развития\"","networkId":"23582611","updateDate":"2018-10-12T11:09:31Z","createDate":"2018-10-12T11:09:31Z","accountId":22721,"postingGroupId":20086}]', 20369, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 74986, '[{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/90567pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/87968/borisovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=14b241bb-d5dd-417e-995f-47c0cf800abb&shareType=venue","serviceName":"ФанТам"}]', 74986, NULL, NULL, NULL, '2023-01-17 11:03:22+03', '2025-03-05 17:48:57+03', '0101000020E6100000EBE6E26F7B004240A6BA809719F44D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Пяжелский дом культуры', 'Бабаевский район', 'Europe/Moscow', 'ул Центральная,д 19', NULL, 'обл Вологодская,р-н Бабаевский,п Пяжелка,ул Центральная,д 19', '{"type": "Point", "coordinates": [35.756445227478004, 60.14889796028551]}', '<p> В 1970 году в Пяжелке открыл свои двери новый Дом культуры. Основным направлением работы является организация досуга населения. Крупные мероприятия проводятся на Новый год, Международный женский день, Масленицу, День Победы, День работника леса. Летом проходит Межрегиональный фестиваль вепсской культуры «Древо жизни». </p><p>Вокальная группа «Молодушки», вокальная группа группа «Северяночка», фольклорные коллективы «Кодирандейне» и «Оейне» радуют зрителей своими выступлениями. Ветеранский клуб «Нестареющие сердца» объединяет людей старшего поколения. Для детей работает клубное объединение «Лучик».</p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/0bdd6e978cf7ee4d2c1e4a9273449664.jpg", "title": "NxCfw3B0J8M.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МАУК «Бабаевский центр культурного развития»', 'Бабаевский район', 'Europe/Moscow', 'пл Привокзальная,1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,пл Привокзальная,1', NULL, 3501008870, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Володинский Дом культуры","networkId":"158838778","updateDate":"2018-10-12T11:09:38Z","createDate":"2018-10-12T11:09:38Z","accountId":22721,"postingGroupId":20087},{"network":"vk","name":"Кдц Бабаево","networkId":"275144982","isPersonal":true,"updateDate":"2018-10-12T11:09:46Z","createDate":"2018-10-12T11:09:46Z","accountId":22721,"postingGroupId":20088},{"network":"vk","name":"МБУК \"Бабаевский центр культурного развития\"","networkId":"23582611","updateDate":"2018-10-12T11:09:31Z","createDate":"2018-10-12T11:09:31Z","accountId":22721,"postingGroupId":20086}]', 20369, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 350, "name": "Народная культура", "sysName": "narodnaya-kultura"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 57449, '[{"url":"https://www.culture.ru/institutes/57200/pyazhelskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/61166pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=748c5424-7932-4508-9413-79d471c210c2&shareType=venue","serviceName":"ФанТам"}]', 57449, NULL, NULL, NULL, '2021-10-13 14:34:21+03', '2025-03-09 09:26:47+03', '0101000020E6100000DD9D7C32D3E0414006EF9E160F134E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Санинский дом культуры', 'Бабаевский район', 'Europe/Moscow', 'д 39', NULL, 'обл Вологодская,р-н Бабаевский,д Тимохино,д 39', '{"type": "Point", "coordinates": [36.061860694542936, 59.60244762716435]}', '<p>Санинский дом культуры открылся 1967 году. На его базе существуют:</p><ol><li> Хор «Селяночка». В 2018 году отмечал юбилей – 5 лет. В составе хора 13 женщин и 2 мужчины. Баянисты – В. В. Бронзов и В. М. Напальков. Коллектив участвует в различных фестивалях, конкурсах, праздничных мероприятиях. Имеет множество дипломов, сертификатов, свидетельств об участии: «Травник», «Древо жизни», «Битва хоров».</li><li> Вокальная группа «Маков цвет». Состоит из 6 человек: Г. А. Шабанова, Н. И. Петянина, Н. А. Шабанова, В. А. Хорева, Т. В. Беляева.</li><li>Вокальная группа «Белые росы». Состоит из 5 человек: Т. И. Яковлева, Н. Н. Семакова, О. В. Васильева, Т. Н. Узикова, И. А. Шарашова.</li></ol><p> Коллективы участвуют на праздничных концертах, поселенческих и районных мероприятиях.</p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/4543f412067034e7b5fe170cf33b71fd.jpeg", "title": "JFQUgH-3ls.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МАУК «Бабаевский центр культурного развития»', 'Бабаевский район', 'Europe/Moscow', 'пл Привокзальная,1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,пл Привокзальная,1', NULL, 3501008870, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Володинский Дом культуры","networkId":"158838778","updateDate":"2018-10-12T11:09:38Z","createDate":"2018-10-12T11:09:38Z","accountId":22721,"postingGroupId":20087},{"network":"vk","name":"Кдц Бабаево","networkId":"275144982","isPersonal":true,"updateDate":"2018-10-12T11:09:46Z","createDate":"2018-10-12T11:09:46Z","accountId":22721,"postingGroupId":20088},{"network":"vk","name":"МБУК \"Бабаевский центр культурного развития\"","networkId":"23582611","updateDate":"2018-10-12T11:09:31Z","createDate":"2018-10-12T11:09:31Z","accountId":22721,"postingGroupId":20086}]', 20369, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 57448, '[{"url":"https://www.culture.ru/institutes/57197/saninskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/61165pl","serviceName":"Афиша7"}]', 57448, NULL, NULL, NULL, '2021-10-13 14:23:41+03', '2025-03-06 16:30:26+03', '0101000020E610000021FC1D0DEB074240A21CFC001DCD4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Биряковский дом культуры', 'Сокольский район', 'Europe/Moscow', 'ул Н.Рубцова,д 6', NULL, 'обл Вологодская,р-н Сокольский,с Биряково,ул Н.Рубцова,д 6', '{"type": "Point", "coordinates": [41.48703625039993, 59.58304798606954]}', '<p>Биряковский дом культуры начал работу в 2003 году, а в 2018 году вошел в состав Центра народной культуры и художественных ремесел «Сокольский». </p><p>Приоритетными направлениями деятельности являются сохранение традиционной народной культуры на основе местного фольклорного материала; работа с пожилыми людьми, ветеранами труда и Великой Отечественной войны, тружениками тыла; работа с детьми, молодыми семьями.</p><p> Проводятся календарные праздники, выпускные, вечера отдыха, концертные программы, торжественные и юбилейные вечера, ярмарки. На базе учреждения работают 14 клубных формирований, из них 1 – на платной основе. Клубные формирования посещают 250 участников. </p> ', NULL, 'kultura.biryakovo@mail.ru', '[{"value": "78173346150"}]', '{"url": "https://all.culture.ru/uploads/dd947d791e308063399a318cce2caab1.jpg", "title": "биряк.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'БУК СМО ЦНКИХР «Сокольский»', 'Сокольский район', 'Europe/Moscow', 'ул Советская,д 16', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,ул Советская,д 16', NULL, 3527011797, 'mincult', 'Сокольский район', 'Europe/Moscow', NULL, 15137, NULL, NULL, NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77652, '[{"url":"https://afisha7.ru/sokol/dvorcy-kultury-i-kluby/96871pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/90508/biryakovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=e4a6bf75-bb1b-4bb5-b429-0e38f6301efb&shareType=venue","serviceName":"ФанТам"}]', 77652, NULL, NULL, NULL, '2023-03-13 11:44:45+03', '2025-05-15 16:05:17+03', '0101000020E610000093B72F3457BE44406B150051A1CA4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Чучковский дом культуры', 'Сокольский район', 'Europe/Moscow', 'ул Центральная,д 3а', NULL, 'обл Вологодская,р-н Сокольский,д Чучково,ул Центральная,д 3а', '{"type": "Point", "coordinates": [41.236435, 59.598761]}', '<p style="text-align:justify"><span> </span></p><p style="text-align:justify"><span> </span></p><p>Чучковский Дом культуры начал свою работу в 1971 году, а с 2018 года он вошел в состав филиалов БУК СМО «Центр народной культуры и художественных ремесел «Сокольский». Сейчас он является местом комфортного досуга, общения и творческой самореализации жителей. Деятельность учреждения <span><span> </span></span>направлена на организацию культурно-массового досуга всех категорий населения, проживающих на территории сельского поселения Чучковское, и прочно связана с жизненным укладом сельских жителей и народными традициями села, бережно хранимыми и передаваемыми из поколения в поколение. В Доме культуры ведется не только культурно-досуговая работа, но и организуются выставки, конкурсы и экскурсии, проводятся беседы по искусству, праздничные вечера. В дружеской атмосфере проходят различные праздники и концертные программы. </p><p>На базе учреждения работают 14 клубных формирований, из них 1 на платной основе. Клубные формирования посещают 235 участников. Для каждой возрастной группы создана авторская программа обучения. Количество участников кружка постоянно увеличивается. </p> <p></p><p style="text-align:justify"><span></span></p>', NULL, 'dk.huhkovo@yandex.ru', '[{"value": "78817334512"}]', '{"url": "https://all.culture.ru/uploads/70c55372f8283661b8430ff5142790a3.jpg", "title": "чуч.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'БУК СМО ЦНКИХР «Сокольский»', 'Сокольский район', 'Europe/Moscow', 'ул Советская,д 16', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,ул Советская,д 16', NULL, 3527011797, 'mincult', 'Сокольский район', 'Europe/Moscow', NULL, 15137, NULL, NULL, NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77650, '[{"url":"https://www.culture.ru/institutes/90505/chuchkovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/sokol/dvorcy-kultury-i-kluby/97199pl","serviceName":"Афиша7"}]', 77650, NULL, NULL, NULL, '2023-03-13 11:35:46+03', '2025-05-15 16:05:18+03', '0101000020E61000009C508880439E4440658F5033A4CC4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Двиницкий дом культуры', 'Сокольский район', 'Europe/Moscow', 'ул Первомайская,д 5а', NULL, 'обл Вологодская,р-н Сокольский,д Чекшино,ул Первомайская,д 5а', '{"type": "Point", "coordinates": [40.553527, 59.655158]}', '<p>Двиницкий дом культуры начал свою работу в 1960 году, а в 2018 году вошел в состав Центра народной культуры и художественных ремесел «Сокольский». Приоритетным направлением деятельности является работа с пожилыми людьми, ветеранами труда и Великой Отечественной войны, тружениками тыла, работа с детьми, молодыми семьями. </p><p>Специалисты Дома культуры проводят календарные праздники, выпускные, вечера отдыха, концертные программы, торжественные и юбилейные вечера, ярмарки. На базе учреждения работают 14 клубных формирований, из них 1 – на платной основе. Клубные формирования посещают 250 участников. </p> ', NULL, 'dvinclub@mail.ru', '[{"value": "78173343144"}]', '{"url": "https://all.culture.ru/uploads/ac6a83a97cdaf20c3e343c8d72058f95.jpg", "title": "двин.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'БУК СМО ЦНКИХР «Сокольский»', 'Сокольский район', 'Europe/Moscow', 'ул Советская,д 16', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,ул Советская,д 16', NULL, 3527011797, 'mincult', 'Сокольский район', 'Europe/Moscow', NULL, 15137, NULL, NULL, NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77647, '[{"url":"https://www.culture.ru/institutes/90510/dvinickii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/sokol/dvorcy-kultury-i-kluby/96870pl","serviceName":"Афиша7"}]', 77647, NULL, NULL, NULL, '2023-03-13 11:28:23+03', '2025-05-15 16:05:15+03', '0101000020E6100000FC3905F9D94644403CDBA337DCD34D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Пудегский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Центральная,д 12', NULL, 'обл Вологодская,р-н Вологодский,п Уткино,ул Центральная,д 12', '{"type": "Point", "coordinates": [39.414351119049044, 59.1418519314694]}', '<p><span>В 1960-х<span> </span>гг.<span> </span>в п. Уткино было открыто первое деревянное здание клуба на 95 мест. Впоследствии его переименовали в Пудегский дом культуры. В начале 70-х гг. здесь проходили съемки художественного фильма режиссера П. Тодоровского<span> </span>«Своя земля», который вышел в кинопрокат в 1973 г. </span></p><p><span>В 1987 г.<span> </span>было построено<span> </span>новое<span> </span>кирпичное<span> </span>здание Дома культуры общей площадью 1 112,2 кв. м<span> </span>со зрительным залом на 200 мест, которое могло вместить всех желающих посетить<span> </span>мероприятия, концерты и вечера отдыха. После объединения в 2012 г. сельских территорий Пудегский ДК стал филиалом МБУК «Старосельский ДК». </span></p> <p><span>При Пудегском доме культуры работают 24 клубных формирования, из них 11 – для детей и 13 – </span><span>для взрослого населения.</span><span></span></p> <p><span>Наиболее популярные клубные формирования:</span><span></span></p> <ol><li><span>Клуб молодой семьи «Азбука счастья» – постоянный участник областного форума клубов молодой семьи «Погода в доме», сотрудничает с Центром молодежной политики Вологодской области «Содружество», участвует в районных акциях и конкурсах.</span></li><li><span>Секция единоборств – спортсмены ежегодно становятся призерами турниров по борьбе в ФЦ «Пластилин» г. Вологды,<span> </span>в соревнованиях по джиу-джитсу на Кубке г. Вологды, в Чемпионате Вологодской области по джиу-джитсу.</span></li><li><span>Школа рисования и развития «Акварель» – участник и призер всероссийских онлайн-конкурсов рисунков, участник акции «Рисуем Победу».</span></li><li><span>Студия «Веселые нотки» – участник и призер<span> </span>районного конкурса детского творчества «Утренняя звезда».</span></li><li><span>Ансамбль «Русская песня» и солисты ДК – участники и призеры вокального конкурса «Снеговея», конкурса молодежного творчества «Арт-тайм», районных онлайн-конкурсов<span> </span>«Песни нашей Победы» и др.</span></li><li><span>Ансамбль «Русская частушка» – участник и призер<span> </span>онлайн-конкурса «Улома поющая», фестиваля творчества ветеранов,<span> </span>призер онлайн-конкурса «Песни нашей Победы», лауреаты третьей степени Всероссийского конкурса «Забота. Творчество. Долголетие» и др.</span></li></ol> <p><span> </span></p> <p><span>Ведется работа с разнообразными группами населения: со школьниками, с учащимися коррекционных классов, дошкольных групп, с подростками и молодежью, с людьми пенсионного возраста и ветеранами, с молодыми семьями, </span><span>c</span><span> </span><span>женскими коллективами и другими группами. Дом культуры<span> </span>поддерживает дружеские отношения с Первомайской средней школой, Пудегской библиотекой, женсоветом и Советом ветеранов п. Уткино.</span></p> <p><span> </span></p>', NULL, NULL, '[{"value": "78172775797"}]', '{"url": "https://all.culture.ru/uploads/69543409c50dfe6468ab55b9379fb01a.jpg", "title": "M0m-omgYeY0.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение «Старосельский дом культуры»', 'Вологодский район', 'Europe/Moscow', 'д 12', NULL, 'обл Вологодская,р-н Вологодский,д Стризнево,д 12', NULL, 3507303248, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14112, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78232, '[{"url":"https://www.culture.ru/institutes/91149/pudegskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=2a0e46fe-a6d3-4672-8692-fcb081d58578&shareType=venue","serviceName":"ФанТам"}]', 78232, NULL, NULL, NULL, '2023-03-27 13:38:15+03', '2025-07-10 15:10:00+03', '0101000020E610000036B01C7509B543408B443F3428924D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Талицкий сельский дом культуры', 'Кирилловский район', 'Europe/Moscow', 'ул Чучина,д 12', NULL, 'обл Вологодская,р-н Кирилловский,с Талицы,ул Чучина,д 12', '{"type": "Point", "coordinates": [38.803843, 59.645873]}', '<p>Здесь работают творческие люди. Проводятся всевозможные мероприятия: концерты, викторины, конкурсные программы, театрализованные представления, спортивные игры. Ведется работа с детьми, молодежью и людьми пожилого возраста. <br /></p><p>В Доме культуры создано 21 клубное формирование различных жанровых направлений. Работают кружки народного прикладного творчества, клубы по интересам, кружки художественной самодеятельности: сольное пение, танцевальный, театральный, художественное слово. Кружки посещают не только взрослые, но и дети. Театральный кружок – активный участник и постоянный призер районных фестивалей и конкурсов. Вокальные формирования принимают участие и в межрайонных, и в областных фестивалях и конкурсах. <br /></p>', NULL, NULL, NULL, '{"url": "https://all.culture.ru/uploads/b43bee73c5236864765bd745a1297b91.jpg", "title": "тАЛИЦЫ ЗАЛ.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'АУК КМР «ЦКР»', 'Кирилловский район', 'Europe/Moscow', 'ул Гагарина,д 98', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,ул Гагарина,д 98', NULL, 3511006791, 'mincult', 'Кирилловский район', 'Europe/Moscow', '[{"network":"vk","name":"Центр культурного развития","networkId":"17831631","updateDate":"2018-05-29T07:22:36Z","createDate":"2018-05-29T07:22:36Z","accountId":21387,"postingGroupId":18946}]', 20401, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "19:00:00", "from": "11:00:00"}', '{"to": "19:00:00", "from": "11:00:00"}', '{"to": "19:00:00", "from": "11:00:00"}', '{"to": "19:00:00", "from": "11:00:00"}', '{"to": "19:00:00", "from": "11:00:00"}', '{"to": "19:00:00", "from": "11:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78226, '[{"url":"https://www.culture.ru/institutes/91108/talickii-selskii-dom-kultury","serviceName":"Культура.рф"}]', 78226, NULL, NULL, NULL, '2023-03-27 12:15:52+03', '2025-07-10 12:28:42+03', '0101000020E61000002C0FD253E4664340492F6AF7ABD24D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Нефедовский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Центральная,д 25', NULL, 'обл Вологодская,р-н Вологодский,д Нефедово,ул Центральная,д 25', '{"type": "Point", "coordinates": [39.070346, 59.763892]}', '<p><span>Здание<span> </span>Нефедовского филиала построено в 1914 году.</span></p><p><span> </span><span>Сейчас в филиале работают десять клубных формирований для детей и взрослых по различным направлениям деятельности: спортивно-оздоровительное, вокальное, познавательное, игровое, изобразительного искусства, клуб любителей гармони «Гармошечка», клуб «Ветеран». Ветераны</span><span> занимаются скандинавской ходьбой, посещают спортивно-оздоровительный клуб «ЗОЖ». Участники вокального ансамбля «Надежда» и клуба любителей гармони «Гармошечка» выступают на музыкальных вечерах, концертах. </span></p><p><span>Ко всем праздничным и памятным датам проводятся концерты. Дети с удовольствием посещают игровые программы, дискотеки. Для всех категорий населения проводятся различные развлекательные и тематические мероприятия, выставки, конкурсы, соревнования, викторины. Самыми любимыми у зрителей являются: День деревни Нефедово, Масленица, новогоднее театрализованное представление, День пожилого человека.</span></p>', NULL, NULL, '[{"value": "78172774553"}]', '{"url": "https://all.culture.ru/uploads/fd8029325fcc1ed09a3233662289e77e.jpg", "title": "wR8v3MoVTUo.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Новленский Дом культуры»', 'Вологодский район', 'Europe/Moscow', 'ул Советская,д 30', NULL, 'обл Вологодская,р-н Вологодский,с Новленское,ул Советская,д 30', NULL, 3507303368, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14125, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78200, '[{"url":"https://www.culture.ru/institutes/91131/nefedovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=69e7a660-27d1-4bd0-8f0e-a82cf46ef1d2&shareType=venue","serviceName":"ФанТам"}]', 78200, NULL, NULL, NULL, '2023-03-24 15:00:41+03', '2025-07-11 14:17:52+03', '0101000020E6100000C4B304190189434088D68A36C7E14D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Новленский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Советская,д 30', NULL, 'обл Вологодская,р-н Вологодский,с Новленское,ул Советская,д 30', '{"type": "Point", "coordinates": [39.33251, 59.619666]}', '<p><span>Новленский дом культуры образован в 1932 году. </span></p><p><span></span><span>На базе Дома культуры работают <span>детские и взрослые </span>клубные формирования различного направления: </span><span>вокальные, танцевальные, театральные, а также семейный клуб, клуб здоровья, клубы «Ветеран» и «Оформитель», детская творческая мастерская.<span> Коллективы клубных формирований принимают активное участие в межпоселенческих, районных, областных, всероссийских конкурсах и фестивалях. </span></span></p><p><span>Традиционными и любимыми зрителями стали такие массовые мероприятия, как народный праздник «Заговенье», фестиваль художественного творчества «Поклонимся великим тем годам», фестиваль гармонистов, баянистов и частушечников «Играй и пой, Вологодская гармонь!», фестиваль-конкурс детского и юношеского творчества «Радуга талантов», фестиваль самодеятельного художественного<span> </span>творчества среди людей<span> </span>«золотого» возраста «Завалинка», концертно-театрализованная программа «Дети войны» и многие другие.</span></p> <p><span> </span></p> <p style="text-align:justify"><span></span></p><p style="text-align:justify"><span></span><span></span></p> <p><span> </span></p>', NULL, 'novlendk@mail.ru', '[{"value": "77182776296", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/fe7f478533f15f58d10dd97eb6044666.jpg", "title": "O7MtjNaAoJ8 (1).jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Новленский Дом культуры»', 'Вологодский район', 'Europe/Moscow', 'ул Советская,д 30', NULL, 'обл Вологодская,р-н Вологодский,с Новленское,ул Советская,д 30', NULL, 3507303368, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14125, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 59, "name": "Ансамбли", "sysName": "ansambli"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78196, '[{"url":"https://www.culture.ru/institutes/90997/novlenskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=0f7ee6d8-1813-4d69-9e49-59276ffbdd56&shareType=venue","serviceName":"ФанТам"}]', 78196, NULL, NULL, NULL, '2023-03-24 14:27:15+03', '2025-07-11 14:57:39+03', '0101000020E6100000E6CB0BB08FAA4340B9382A3751CF4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('МБУК Климушинский Дом культуры', 'Верховажский район', 'Europe/Moscow', 'ул Спортивная,д 31', NULL, 'обл Вологодская,р-н Верховажский,д Климушино,ул Спортивная,д 31', '{"type": "Point", "coordinates": [42.10543, 60.81257]}', '  <p>КЛИМУШИНСКИЙ ДОМ КУЛЬТУРЫ-</p><p>Это одноэтажное здание . совмещенное с Физкультурно оздоровительным</p><p>комплексом. Введено в эксплуатацию в 1999 году. В 2018 году произошло</p><p>объединение домов культуры . К Климушинскому дому культуры присоединились</p><p>Терменгский дом культуры, Сидоро-Слободской клуб, Житнохинский клуб,</p><p>который является летней площадкой.</p><p>Здесь работают ветеранские, молодёжные и детские клубные формирования.</p><p>В течении творческого сезона проходят концерты, конкурсы, танцевальные</p><p>вечера,народные гулянья, праздники деревень. Совместно с Физкультурно</p><p>оздоровительным комплексом организуются спортивные состязания. Также</p><p>много мероприятий проводится совместно с библиотекой .Организована работа</p><p>с домами культуры других поселений и соседнего региона и др.</p><p>Приглашаем в наш дом культуры - место, где можно не только отдохнуть,</p><p>но и найти себе занятие по душе.</p><p>МЫ ВСЕГДА РАДЫ ВИДЕТЬ ВАС!</p>  ', NULL, 'dkklimushino@yandex.ru', '[]', '{"url": "https://all.culture.ru/uploads/99c9da5eecaad9d7a536797fc364a0cb.jpeg", "title": "hMYY9WzsxaI.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Климушинский Дом культуры»', 'Верховажский район', 'Europe/Moscow', 'ул Спортивная,д 31', NULL, 'обл Вологодская,р-н Верховажский,д Климушино,ул Спортивная,д 31', NULL, 3505004147, 'mincult', 'Верховажский район', 'Europe/Moscow', NULL, 20451, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 59, "name": "Ансамбли", "sysName": "ansambli"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 61611, '[{"url":"https://www.culture.ru/institutes/62382/mbuk-klimushinskii-dom-kultury","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2022-02-10 14:32:56+03', '2022-02-13 13:03:11+03', '0101000020E61000003602F1BA7E0D4540F9DA334B02684E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Заборский дом культуры', 'Тарногский район', 'Europe/Moscow', 'ул Красная,д 12', NULL, 'обл Вологодская,р-н Тарногский,с Красное,ул Красная,д 12', '{"type": "Point", "coordinates": [43.22915, 60.510904]}', '<p><span><span><span>Заборский дом культуры </span><span> является</span><span> ведущим сельским</span><span> учреждением культуры для проведения</span><span><span> районных мероприятий. Свою деятельность он начал в 1970 году. <span>В 2019 году учреждение стало участником регионального проекта «Сельский дом культуры», здание было обновлено.</span></span></span></span></span></p><p><span><span><span><span></span><span> </span><span>На сегодняшний день в</span></span><span><span> Доме культуры активно работает 18 клубных формирований</span><span>: это творческие коллективы, кружки и клубы по интересам. </span></span></span></span><span>Одним из приоритетных направлений работы является организация семейного досуга. Проводятся вечера отдыха, конкурсы, юбилеи, культурно-спортивные программы, беседы и концерты. На базе учреждения работают<span> </span>2 семейных клуба: «Два сердца», в котором супружеские пары могут отдохнуть от работы, семейных хлопот, пообщаться, и «Радуга» – клуб для детей и родителей.</span><br /></p>', NULL, 'dk.zaborie@yandex.ru', '[{"value": "78174831158"}]', '{"url": "https://all.culture.ru/uploads/bd9a2bef9f0ed54d73c1d05ff1092b47.jpeg", "title": "E0LX_liN-l0.jpg"}', '[{"url": "https://all.culture.ru/uploads/11bfe2047f0eac6d6c7767ddb0f70567.jpeg", "title": "zWW-zZmFhls.jpg"}, {"url": "https://all.culture.ru/uploads/7ec8549c993c68674f2843b8f09490ff.jpeg", "title": "2jDBKsC7SeU.jpg"}, {"url": "https://all.culture.ru/uploads/6334de6624d3e6e73d3b5ba989ac3432.jpeg", "title": "De2gUdgxTyM.jpg"}, {"url": "https://all.culture.ru/uploads/4b9d50582c3d690ae34935d0f092441c.jpeg", "title": "nlah2voUy_U.jpg"}]', NULL, 'Дворцы культуры и клубы', 'БУК «Тарногский центр культурного развития» Тарногского муниципального района Вологодской области', 'Тарногский район', 'Europe/Moscow', 'ул Советская,д 41', NULL, 'обл Вологодская,р-н Тарногский,с Тарногский Городок,ул Советская,д 41', NULL, 3517003557, 'mincult', 'Тарногский район', 'Europe/Moscow', NULL, 17497, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "17:12:00", "from": "10:00:00"}', '{"to": "17:12:00", "from": "10:00:00"}', '{"to": "17:12:00", "from": "10:00:00"}', '{"to": "17:12:00", "from": "10:00:00"}', '{"to": "17:12:00", "from": "10:00:00"}', NULL, '{"to": "17:12:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60173, '[{"url":"https://www.culture.ru/institutes/61311/zaborskii-dom-kultury","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2022-01-27 15:05:15+03', '2022-07-28 14:39:53+03', '0101000020E61000006FF085C9549D4540A2B2614D65414E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Дворец культуры подшипникового завода', 'Вологда', 'Europe/Moscow', 'ул Ленинградская,д 89', 'общественный транспорт до остановки «ДК ПЗ»', 'обл Вологодская,г Вологда,ул Ленинградская,д 89', '{"type": "Point", "coordinates": [39.838899, 59.203753]}', '<p> Дворец культуры подшипникового завода на протяжении многих лет является одной из крупнейших концертных площадок Вологды. Разнообразные концерты, новогодние утренники, представления, спектакли, семейные дни отдыха для жителей и гостей города собирают в стенах учреждения всех любителей прекрасного от мала до велика. </p><p>Дворец включает в себя концертный зал на 724 человека, где регулярно проходят театральные и цирковые представления, вечера самодеятельности, а также концерты российских и зарубежных артистов. Это одна из действующих культурных площадок, на которой проводится большое количество различных мероприятий, служащих для интересного проведения досуга в Вологде. Это культурный центр, на базе которого ведется работа с молодежью, создаются музыкальные коллективы, организуются различного плана выставки. </p>', 'https://dkpzvologda.ru', NULL, '[]', '{"url": "https://all.culture.ru/uploads/b939064443f69f58ce0464b57ea6225d.jpeg", "title": "0d4b833f208a4dd008d66a751d107b08.jpeg"}', NULL, NULL, 'Дворцы культуры и клубы', 'ИП Зайцев Олег Сергеевич', 'Вологда', 'Europe/Moscow', 'ул Поселковая,д 4', NULL, 'обл Вологодская,г Вологда,ул Поселковая,д 4', NULL, 3, 'commercial', 'Вологда', 'Europe/Moscow', NULL, 28961, '[{"id": 25, "name": "Классическое искусство", "sysName": "klassicheskoe-iskusstvo"}, {"id": 26, "name": "Современное искусство", "sysName": "sovremennoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 70285, '[{"url":"https://www.culture.ru/institutes/83461/dvorec-kultury-podshipnikovogo-zavoda","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/81376pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-08-01 09:00:29+03', '2022-11-22 16:27:56+03', '0101000020E6100000D4D2DC0A61EB43401FBB0B94149A4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Рослятинский сельский дом культуры', 'Бабушкинский район', 'Europe/Moscow', 'ул Советская,д 17', '.', 'обл Вологодская,р-н Бабушкинский,с Рослятино,ул Советская,д 17', '{"type": "Point", "coordinates": [44.22083482740022, 59.762874629977546]}', '<p>Дом культуры основан в июле 1975 года. Здание находится в центре инфраструктуры села, имеет два этажа. Большой зрительный зал вмещает в себя 200 посадочных мест, для проведения праздничных мероприятий, игровых программ, встреч и дискотек в здании имеется два зала на первом и втором этаже. Деятельностю Учреждения является предоставления услуг в области организации досуга населения. Приобщения жителей поселения к творчеству, культурному развитию, самообразованию, любительскому искусству. Основными видами деятельности являются создание и организация работы кружков, любительских объединений, клубов по интересам различной направленности. Подготовка и проведение тематических вечеров, создание информационной базы собственных сценарных наработок.</p><p>На базе Рослятинского сельского филиала работают клубные формирования различной направленности для всех слоев населения.</p><p> </p><p>Работники учреждения участвуют в выездных мероприятиях в менее населенные и отдаленные населенные пункты Бабушкинского муниципального района.</p><p>В 2019 году был выполнен ремонт по программе губернатора «Сельский дом культуры», в рамках национального проекта «Культура».</p><p>В течение творческого сезона в Рослятинском Доме культуры проходят тематические представления, концерты, конкурсы, спектакли, театрализованные представления, народные гуляния, фестивали самодеятельного творчества, танцевальные вечера и др.</p><p>Дом культуры – место, где можно не только отдохнуть, но и найти занятие по душе!</p> <p></p>', NULL, 'katyamanoilova23@gmail.com', '[{"value": "79814376058", "comment": "Заведующий"}, {"value": "78174531198", "comment": "Методический кабинет"}]', '{"url": "https://all.culture.ru/uploads/a03033808338c0688d14c560c619c871.jpg", "title": "0RSxxv0sloU.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Районный Дом культуры»', 'Бабушкинский район', 'Europe/Moscow', 'ул. Бабушкина,63', NULL, 'обл Вологодская,р-н Бабушкинский,с им Бабушкина,ул. Бабушкина,63', NULL, 3502005590, 'mincult', 'Бабушкинский район', 'Europe/Moscow', NULL, 26248, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 72261, '[{"url":"https://afisha7.ru/imeni-babushkina/dvorcy-kultury-i-kluby/87112pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/85392/roslyatinskii-selskii-dom-kultury","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2022-11-09 19:31:00+03', '2022-11-29 15:55:06+03', '0101000020E610000039C0CC50441C4640D05939E0A5E14D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Культурно-спортивный центр «Пригородный»', 'Сокольский район', 'Europe/Moscow', 'д 14', NULL, 'обл Вологодская,р-н Сокольский,д Литега,д 14', '{"type": "Point", "coordinates": [40.220243, 59.426611]}', '<p><span>Культурно-спортивный центр «Пригородный» был образован 23 февраля 1979 г. Это кирпичное двухэтажное здание со зрительным залом на 200 посадочных мест и малым<span> </span>залом на 40 мест. Также в здании есть современный тренажерный зал, бильярдный зал, игровая комната для самых маленьких посетителей, в вестибюле оборудована зона отдыха с зимним садом и игровой<span> </span>площадкой. </span></p><p><span></span><span> «Пригородный» является центром<span> </span>спортивной и культурно-досуговой деятельности, где население<span> </span>может не только <span> </span>реализовать свои творческие способности, но и активно заниматься <span> </span>спортом. Здесь в 24 клубных формированиях занимаются </span><span> 512 человек. </span><span>Приоритетные направления деятельности: </span><span>спортивное, </span><span>экологическое, </span><span>патриотическое, </span><span>театральное. </span><span>Особой популярностью пользуются клубы «Фитнес», «Скандинавская ходьба», «Бодифлекс». </span></p> <p><span> </span></p> <p><span> </span></p> <p><span> </span></p>', NULL, 'DKSoldek@gmail.com', '[{"value": "78173352220"}]', '{"url": "https://all.culture.ru/uploads/342b64ddb0206ba45607a6cdf708d71a.jpg", "title": "0073.jpg"}', '[{"url": "https://all.culture.ru/uploads/b1d0d88924fdd9af0982d63a26949aa8.jpg", "title": "1tM3zQKE4Rs.jpg"}, {"url": "https://all.culture.ru/uploads/cda6163048c0f32535ad1b2928afc85f.jpg", "title": "lerAHbTD8rc.jpg"}, {"url": "https://all.culture.ru/uploads/308a7ccf5ac60ec054016e056d0ff102.jpg", "title": "WS-ShEDpQDc.jpg"}, {"url": "https://all.culture.ru/uploads/2bfd22b549e4816a339e553e4b526b10.jpg", "title": "YPf1vi7NJTY.jpg"}, {"url": "https://all.culture.ru/uploads/37e89f2441dbc88101ea27e83b714a1b.jpg", "title": "K97qJvD8L1g.jpg"}, {"url": "https://all.culture.ru/uploads/7624c6a3c9f20cfa60f07bdd7869d8f2.jpg", "title": "jJKWUbqh77g.jpg"}, {"url": "https://all.culture.ru/uploads/fa085dd5ec7a4d46025288570320b161.jpg", "title": "PyAU4xT81Dg.jpg"}]', NULL, 'Дворцы культуры и клубы', 'БУК СМО ДК «Солдек»', 'Сокольский район', 'Europe/Moscow', 'ул Мусинского,д 4', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,ул Мусинского,д 4', NULL, 3527020720, 'mincult', 'Сокольский район', 'Europe/Moscow', '[{"network":"vk","name":"Бук-Смр-Дворец-Культуры Солдек","networkId":"563318189","isPersonal":true,"updateDate":"2019-12-04T06:07:33Z","createDate":"2019-12-04T06:07:33Z","accountId":28111,"postingGroupId":25499}]', 16971, '[{"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 64121, '[{"url":"https://www.culture.ru/institutes/63347/kulturno-sportivnyi-centr-prigorodnyi","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/sokol/dvorcy-kultury-i-kluby/66883pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-02-25 09:01:46+03', '2023-03-05 10:18:13+03', '0101000020E6100000231631EC301C4440938E72309BB64D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Шухободский дом культуры', 'Череповецкий район', 'Europe/Moscow', 'ул Центральная,д 6', 'маршрутный автобус «Череповец – Шухободь»', 'обл Вологодская,р-н Череповецкий,с Шухободь,ул Центральная,д 6', '{"type": "Point", "coordinates": [37.711580644180266, 59.229101261710646]}', '<p style="margin-left:0px">Шухободский дом культуры располагается в отдельном одноэтажном здании 1968 года постройки, площадь – 492,1 кв. м. В Доме культуры работают 27 клубных формирований, проводятся концерты, выставки рукоделия, фотовыставки, мероприятия для детей и молодежи, для ветеранов. </p><p style="margin-left:0px">Ансамбль ветеранов «Шухободские родники» – постоянный участник<span> </span>районного фестиваля творчества ветеранов «Родники российских деревень». Женский вокальный ансамбль «Девчата», которым руководит Гусаров Сергей Фролович, был создан в 2010 году. Он является участником всех мероприятий Дома культуры, победителем многих областных и всероссийских конкурсов. Танцевальный коллектив «Позитиff» был создан в 2012 году художественным руководителем Гладиной Галиной Николаевной. Коллектив принимал<span> </span>участие в районном конкурсе чирлидеров, не раз занимал первое место. И сейчас любое мероприятие, проходящее в Доме культуры, невозможно представить без этого <span> </span>коллектива.</p> <p><span> </span></p><p></p><p></p><p></p><p></p><p></p><p><span> </span></p>', 'https://abakan-sko.kulturu.ru', 'skoabakanovo@ya.ru', '[{"value": "79211330110", "comment": ""}, {"value": "78202660479", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/aff8a4347792315ef6e5b3ee80cd6edd.jpeg", "title": "eAvW0Hk0Jx0.jpg"}', '[{"url": "https://all.culture.ru/uploads/f4c1f14ddea10e59d944a7cb83bd61ba.jpeg", "title": "9x4U-bJJFv8.jpg"}, {"url": "https://all.culture.ru/uploads/a72c5b98870739de175fb146eed9cf46.jpeg", "title": "96KFO8WjzLw.jpg"}, {"url": "https://all.culture.ru/uploads/8b4c61f96f96d58ec3bce3c92b7794e0.jpeg", "title": "g-SnAGwTvvE.jpg"}, {"url": "https://all.culture.ru/uploads/f61b156028293ddbd0e7871caf3939f3.jpeg", "title": "pte455_McmU.jpg"}, {"url": "https://all.culture.ru/uploads/50881277989de5c9339c82c095ea077b.jpeg", "title": "NkrqFVhVTqU.jpg"}, {"url": "https://all.culture.ru/uploads/5f9ab36b9a70577a3b583c8bbb89a9d9.jpeg", "title": "tB4LS70C8QE.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МУК «Абакановское социально-культурное объединение»', 'Череповецкий район', 'Europe/Moscow', 'Центральная,6', NULL, 'обл Вологодская,р-н Череповецкий,с.Шухободь,Центральная,6', NULL, 3523014596, 'mincult', 'Череповецкий район', 'Europe/Moscow', NULL, 20342, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', '[{"hosting":"vk","id":"<iframe src=\"https://vk.com/video_ext.php?oid=-29617130&id=456239178&hash=de53aa683d1542ab\" width=\"640\" height=\"360\"></iframe>"}]', NULL, '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "14:00:00", "from": "11:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 62941, '[{"url":"https://www.culture.ru/institutes/65286/shukhobodskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/68599pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-02-18 13:21:32+03', '2023-03-10 15:57:36+03', '0101000020E6100000459C151315DB42408142AD30539D4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Кувшиновский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Дачная,д 1', NULL, 'обл Вологодская,р-н Вологодский,п Кувшиново,ул Дачная,д 1', '{"type": "Point", "coordinates": [39.816469, 59.253559]}', '<p>Филиал Кувшиновский Дом культуры расположен в деревянном здании 1905 года постройки. На базе Дома культуры ведут свою деятельность 22 клубных формирования различных направлений: изобразительного искусства, вокального и инструментального направлений, спортивного и настольные игры, а также развивающие группы для дошкольного возраста. В Доме культуры создан оркестр русских народных инструментов под руководством заслуженного работника культуры Смирнова Николая Константиновича. Коллективу присвоено звание «Образцовый художественный коллектив». Созданы музейные комнаты: «Музей русских народных инструментов» и «Музей предметов народного быта».</p>', 'https://vk.link/club146491739', 'hydryk.kyvshinovskidk@yandex.ru', '[{"value": "78172552239"}]', '{"url": "https://all.culture.ru/uploads/d9c8c71fc86636589f9da0c2db2b9eb1.jpg", "title": "IMG-2cee38bd04936e51a26eb1ebf82c7fe2-V.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Семёнковское клубное объединение»', 'Вологодский район', 'Europe/Moscow', 'ул Первомайская,д 17', NULL, 'обл Вологодская,р-н Вологодский,п Семенково (Семенковское МО),ул Первомайская,д 17', NULL, 3507303470, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14048, NULL, NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "11:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 51316, '[{"url":"https://www.culture.ru/institutes/76826/kuvshinovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/75398pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2021-04-14 16:24:26+03', '2023-03-09 15:35:57+03', '0101000020E61000005299620E82E84340A14D0E9F74A04D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Дубровский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Центральная,д 8', NULL, 'обл Вологодская,р-н Вологодский,п Дубровское,ул Центральная,д 8', '{"type": "Point", "coordinates": [39.81112551324462, 59.34317846102337]}', '<p>Дом культуры – это центр развития творчества жителей поселка Дубровское. Ведет свою работу в направлении культурно – досуговой деятельности. На базе Дома культуры работают 20 клубных формирований различных направлений: хореографические, вокальные,театральные и декоративно-прикладные. Один из активных направлений – это вокальная студия для детей и взрослых под руководством Фатеевой Аси Дмитриевны. Ее талантливые участники украшают номерами не только концерты и мероприятия , проходящие в Доме культуры, но и активно выступают на других площадках, смотрах,фестивалях и конкурсах, занимая призовые места.</p>', 'https://vk.link/club89049469', 'zobenewa@yandex.ru', '[{"value": "78172778695", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/37fe38339c98a064b9a7fe5662e3d207.jpg", "title": "2VzLTrlYusk.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Семёнковское клубное объединение»', 'Вологодский район', 'Europe/Moscow', 'ул Первомайская,д 17', NULL, 'обл Вологодская,р-н Вологодский,п Семенково (Семенковское МО),ул Первомайская,д 17', NULL, 3507303470, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14048, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 51299, '[{"url":"https://www.culture.ru/institutes/76453/dubrovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/75397pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2021-04-14 15:24:11+03', '2023-03-10 09:17:47+03', '0101000020E61000001E2BF8F5D2E74340BC649545EDAB4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Дом культуры «Варницкий»', 'Тотемский район', 'Europe/Moscow', 'ул Воскресенская,д 7', NULL, 'обл Вологодская,р-н Тотемский,д Варницы,ул Воскресенская,д 7', '{"type": "Point", "coordinates": [42.750187, 59.985656]}', '<p>В 1988 году было сдано эксплуатацию здание Дома культуры совхоза «Тотемский». В настоящее время это филиал ЦРК «Тотьма».<br /></p><p>ДК «Варницкий» – это самая большая сцена на территории Тотемского муниципального округа (216 мест). В здании филиала занимаются 35 клубных формирований, из них 13 – платные. Занятия посещает 441 житель деревни, встречи клубов на платной основе – 156 человек.</p><p>Ежегодно в филиале проводится фестиваль для старшего поколения «Родники российских деревень», фестиваль хореографического искусства «Хрустальный башмачок», тематические вечера отдыха, концерты, дискотеки для молодежи и др.</p>', NULL, NULL, NULL, '{"url": "https://all.culture.ru/uploads/eff112805a509b4ffa995ab87fe2e8cc.jpg", "title": "_EOPOjcWZ6Y.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Центр развития культуры «Тотьма»', 'Тотемский район', 'Europe/Moscow', 'Вологодская,11', NULL, 'обл Вологодская,р-н Тотемский,д Варницы,Вологодская,11', NULL, 3518003616, 'mincult', 'Тотемский район', 'Europe/Moscow', NULL, 25908, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78973, '[{"url":"https://www.culture.ru/institutes/91823/dom-kultury-varnickii","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/totma/dvorcy-kultury-i-kluby/99445pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2023-04-12 21:05:16+03', '2023-04-13 12:35:39+03', '0101000020E61000003271AB2006604540978DCEF929FE4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Лукинский дом культуры', 'Чагодощенский район', 'Europe/Moscow', 'ул Мира,д 7', NULL, 'обл Вологодская,р-н Чагодощенский,д Анишино,ул Мира,д 7', '{"type": "Point", "coordinates": [35.31705904002335, 58.884974065512026]}', '<p><span>Здание Лукинского дома культуры было открыто в 1974 году. Первым директором стала Лидия Моисеевна Голубева. За время существования Дома культуры произошло много изменений. В 2017 году он был присоединен к </span><span>Белокрестскому социально-культурному объединению. В 2020 году по программе «Сельский дом культуры» проведен капитальный ремонт.</span></p><p><span>На базе Дома культуры работают кружки по интересам: декоративно-прикладного направления – «Сделай сам», «Вязание на спицах», «Вязание крючком»; творческого направления – «Театральный», «Художественная самодеятельность»; физкультурно-оздоровительного направления – «Группа здоровья». А также действуют клубы по интересам: «Хозяюшка» и молодежный клуб «Мечта». Проводятся концерты, культурно-массовые и просветительские мероприятия для детей и взрослых.</span> </p>', NULL, 'dk.lukinsky@yandex.ru', '[{"value": "78174131225", "comment": ""}, {"value": "78174131225", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/03bf45db3f79e0cedee6309383af359c.jpg", "title": "IMG-20230410-WA0002.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУ «Белокрестское СКО»', 'Чагодощенский район', 'Europe/Moscow', 'ул Кооперативная,д 23Б', NULL, 'обл Вологодская,р-н Чагодощенский,с Белые Кресты,ул Кооперативная,д 23Б', NULL, 3522003619, 'mincult', 'Чагодощенский район', 'Europe/Moscow', NULL, 17335, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 206, "name": "Народное творчество", "sysName": "narodnoe-tvorchestvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, NULL, '{"to": "18:40:00", "from": "15:00:00"}', '{"to": "18:40:00", "from": "15:00:00"}', '{"to": "18:40:00", "from": "15:00:00"}', '{"to": "18:40:00", "from": "15:00:00"}', NULL, '{"to": "18:40:00", "from": "15:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78773, '[{"url":"https://www.culture.ru/institutes/91629/lukinskii-dom-kultury","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-04-07 13:57:25+03', '2023-04-10 09:13:59+03', '0101000020E610000096E6FF6395A84140569786D446714D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Покровский культурно-досуговый центр', 'Чагодощенский район', 'Europe/Moscow', 'ул Молодежная,зд 100б', NULL, 'обл Вологодская,р-н Чагодощенский,с Покровское,ул Молодежная,зд 100б', '{"type": "Point", "coordinates": [35.577183691787724, 58.95449691207478]}', '<p><span>В 1994 году был создан Покровский культурно-досуговый центр. </span></p><p><span>Се</span><span>годня он является центром культурной жизни и общения для местных жителей. Это основная площадка для проведения организованного досуга, место встреч односельчан. Разнообразные конкурсы, концерты, массовые театрализованные праздники и представления, танцевальные вечера, народные гулянья – сегодня без них невозможно представить деятельность учреждения. </span><span></span><span>Работники культуры и члены творческих коллективов принимают участие в праздничных концертах, ярмарках, конкурсах и других мероприятиях, проводимых в районе, области и далеко за ее пределами.</span></p> <p><span>На базе КДЦ ведут работу хоровые, танцевальные, интеллектуальные клубные формирования:</span></p> <ul><li><span>музыкальный клуб;</span></li><li><span>молодежный клуб;</span></li><li><span>интеллектуальный клуб «Знатоки»;</span></li><li><span>клуб «Сударушки+»;</span></li><li><span>клуб семейных пар.</span></li></ul>', NULL, 'pokrovska.bibliotekasmironova@yandex.ru', '[{"value": "78174131225", "comment": ""}, {"value": "78174131225", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/2c8c272d72cb877cc563f3874bb9e1e4.jpg", "title": "1ea9f542-ace2-4289-bc18-b7f205f2603f.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУ «Белокрестское СКО»', 'Чагодощенский район', 'Europe/Moscow', 'ул Кооперативная,д 23Б', NULL, 'обл Вологодская,р-н Чагодощенский,с Белые Кресты,ул Кооперативная,д 23Б', NULL, 3522003619, 'mincult', 'Чагодощенский район', 'Europe/Moscow', NULL, 17335, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 206, "name": "Народное творчество", "sysName": "narodnoe-tvorchestvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, NULL, '{"to": "18:40:00", "from": "15:00:00"}', '{"to": "18:40:00", "from": "15:00:00"}', '{"to": "18:40:00", "from": "15:00:00"}', '{"to": "18:40:00", "from": "15:00:00"}', NULL, '{"to": "18:40:00", "from": "15:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78770, '[{"url":"https://www.culture.ru/institutes/91625/pokrovskii-kulturno-dosugovyi-centr","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-04-07 13:20:29+03', '2023-04-13 10:25:13+03', '0101000020E6100000A401BC27E1C9414041BF6EF42C7A4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Белокрестский дом культуры', 'Чагодощенский район', 'Europe/Moscow', 'ул Луговая,д 9', NULL, 'обл Вологодская,р-н Чагодощенский,с Белые Кресты,ул Луговая,д 9', '{"type": "Point", "coordinates": [35.24678890324826, 59.079291918750506]}', '<p><span>Помещения под Белокрестский дом культуры были выделены в 2019 г. </span></p><p><span>Сегодня <span> </span>Дом культуры является центром культурной жизни и общения для местных жителей. Это основная площадка для проведения организованного досуга, место встреч односельчан. Здесь можно интересно и увлекательно провести время всей семьей и воплотить в жизнь творческие задумки. Здесь проводятся разнообразные мероприятия – сегодня без них невозможно представить деятельность учреждения. </span><span>Работники культуры и члены творческих коллективов принимают участие в праздничных концертах, ярмарках, конкурсах и других мероприятиях, проводимых в районе и области.</span></p> <p><span>На базе Дома культуры действуют различные клубные формирования, среди них особенно известны:</span></p> <ol><li><span>Клуб «Селяночка».</span></li><li><span>Клуб «Почемучки».</span></li><li><span>Экологический клуб «Лесовичок».</span></li><li><span>Хоровой коллектив<span> </span>«Селяночка».</span></li><li><span>Танцевальный коллектив «Карабаночки».</span></li></ol>', NULL, 'mubk-skobk@yandex.ru', '[{"value": "78174131225"}, {"value": "78174131225"}]', '{"url": "https://all.culture.ru/uploads/eee8be4878e1b9bc54b5019a5f4d3db8.jpg", "title": "b647ed00-3b6d-4bdf-9975-2d4d9ae0ca94.jpg"}', '[{"url": "https://all.culture.ru/uploads/6d1d30e140b7c446f2a6f2d88005e294.jpg", "title": "FJ5zInoiIxE.jpg"}, {"url": "https://all.culture.ru/uploads/419a967e44a0a3b1815b4854806da869.jpg", "title": "8569eaff-47a1-4ce8-a139-cfedafd02f6e.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУ «Белокрестское СКО»', 'Чагодощенский район', 'Europe/Moscow', 'ул Кооперативная,д 23Б', NULL, 'обл Вологодская,р-н Чагодощенский,с Белые Кресты,ул Кооперативная,д 23Б', NULL, 3522003619, 'mincult', 'Чагодощенский район', 'Europe/Moscow', NULL, 17335, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 206, "name": "Народное творчество", "sysName": "narodnoe-tvorchestvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, NULL, '{"to": "17:40:00", "from": "14:00:00"}', '{"to": "17:40:00", "from": "14:00:00"}', '{"to": "17:40:00", "from": "14:00:00"}', '{"to": "17:40:00", "from": "14:00:00"}', NULL, '{"to": "17:40:00", "from": "14:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78726, '[{"url":"https://www.culture.ru/institutes/91594/belokrestskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/chagoda/dvorcy-kultury-i-kluby/98909pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2023-04-06 13:38:11+03', '2023-04-06 17:04:29+03', '0101000020E6100000C63B5EC7969F41406DEFD23C268A4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Мегринский дом культуры', 'Чагодощенский район', 'Europe/Moscow', 'ул Северная,д 6', NULL, 'обл Вологодская,р-н Чагодощенский,д Мегрино,ул Северная,д 6', '{"type": "Point", "coordinates": [35.588893239425644, 59.147417969022776]}', '<p><span>Здание Дома культуры было построено и введено в эксплуатацию в 1974 году.</span></p> <p><span> Дом культуры – центр общественной и культурной жизни людей в селе, место общения и развития творческих способностей земляков.</span><span><span></span></span></p> <p><span>Ведется р</span><span>абота с детьми и подростками, </span>с населением среднего, старшего и пожилого возраста, а также по таким направлениям, как:</p><ul><li> организация досуговой деятельности молодежи;</li><li><span>организация семейного досуга;</span><span></span></li><li><span>возрождение и сохранение народной культуры;</span></li><li><span>духовно-нравственное и патриотическое воспитание населения.</span></li></ul> <p><span>Работники культуры и коллективы художественной самодеятельности активно принимают участие в праздничных концертах, ярмарках, конкурсах, различных мероприятиях, проводимых в районе и области.</span></p> <p><span>На базе Дома культуры действуют такие клубные формирования, как:</span></p> <ol><li><span>Женский хор.</span></li><li><span>Детский вокальный кружок<span> </span>«ДоМиСолька».</span></li><li><span>Танцевальный коллектив «Вдохновение».</span></li><li><span>Интеллектуальный клуб «Эрудит».</span></li><li><span>Ветеранский клуб «Берегиня».</span></li><li><span>Клуб выходного дня.</span></li><li><span>Изостудия.</span></li></ol>', NULL, 'megrinodk@mail.ru', '[{"value": "78174131225", "comment": ""}, {"value": "78174131225", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/4bc4f079eda8627ead427fe212dc77c8.jpg", "title": "20211029_092431.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУ «Белокрестское СКО»', 'Чагодощенский район', 'Europe/Moscow', 'ул Кооперативная,д 23Б', NULL, 'обл Вологодская,р-н Чагодощенский,с Белые Кресты,ул Кооперативная,д 23Б', NULL, 3522003619, 'mincult', 'Чагодощенский район', 'Europe/Moscow', NULL, 17335, '[{"id": 26, "name": "Современное искусство", "sysName": "sovremennoe-iskusstvo"}, {"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 206, "name": "Народное творчество", "sysName": "narodnoe-tvorchestvo"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "21:00:00", "from": "09:00:00"}', '{"to": "21:00:00", "from": "09:00:00"}', '{"to": "21:00:00", "from": "09:00:00"}', '{"to": "21:00:00", "from": "09:00:00"}', NULL, '{"to": "21:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78723, '[{"url":"https://www.culture.ru/institutes/91591/megrinskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/chagoda/dvorcy-kultury-i-kluby/98908pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2023-04-06 12:49:16+03', '2023-04-06 16:13:31+03', '0101000020E610000096158ADA60CB4140D5E58D97DE924D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Избоищский дом культуры', 'Чагодощенский район', 'Europe/Moscow', 'ул Набережная,д 1', NULL, 'обл Вологодская,р-н Чагодощенский,д Избоищи,ул Набережная,д 1', '{"type": "Point", "coordinates": [35.28625590653255, 58.98399520017931]}', '<p><span>Работа дома культуры, как центра обеспечения организованного досуга населения, началась еще в 1923 году. За вековой период сменилось четыре места расположения учреждения. В настоящее время дом культуры находится в благоустроенном кирпичном двухэтажном здании, занимая часть площади первого этажа. </span></p> <p><span>Это место, где можно собраться жителям, разделяющим одни и те же интересы, где постоянно идет патриотическое воспитание детей и молодежи, где каждый желающий может развивать те или иные способности, где идет работа по сохранению культурных традиций. <span> </span>Деятельность учреждения имеет различные направления. Это концертные, тематические и конкурсные программы, массовые театрализованные гулянья, танцевальные вечера, профилактические беседы-презентации, интеллектуальные игры, спортивные мероприятия. Два творческих коллектива  имеют звание «Народный<span> </span>самодеятельный коллектив»: хор и вокальный ансамбль «Ретро».</span></p> <p><span>На базе учреждения действуют<span> </span>вокальные, хореографические, театральные коллективы, а также клубные формирования:</span></p> <ol> <li><span>Клуб ветеранов «Сударушка».</span></li> <li><span>Семейный клуб выходного дня.</span></li> <li><span>Интеллектуальный клуб «Что? Где? Когда?».</span></li> <li><span>Интеллектуальный детский клуб.</span></li> </ol>', NULL, 'dkizboishi@yandex.ru', '[{"value": "78174131225", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/8137657d6f1bb3b6b644b51ce2767214.jpg", "title": "Избоищский ДК фасад.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУ «Белокрестское СКО»', 'Чагодощенский район', 'Europe/Moscow', 'ул Кооперативная,д 23Б', NULL, 'обл Вологодская,р-н Чагодощенский,с Белые Кресты,ул Кооперативная,д 23Б', NULL, 3522003619, 'mincult', 'Чагодощенский район', 'Europe/Moscow', NULL, 17335, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, NULL, '{"to": "17:40:00", "from": "14:00:00"}', '{"to": "17:40:00", "from": "14:00:00"}', '{"to": "17:40:00", "from": "14:00:00"}', '{"to": "17:40:00", "from": "14:00:00"}', NULL, '{"to": "17:40:00", "from": "14:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78669, '[{"url":"https://www.culture.ru/institutes/91527/izboishskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/chagoda/dvorcy-kultury-i-kluby/98785pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2023-04-05 14:07:54+03', '2023-04-05 15:15:58+03', '0101000020E61000000D6C9608A4A441407618028EF37D4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Борисовский дом культуры', 'Чагодощенский район', 'Europe/Moscow', 'ул Октябрьская,д 29', NULL, 'обл Вологодская,р-н Чагодощенский,п Борисово,ул Октябрьская,д 29', '{"type": "Point", "coordinates": [35.377929, 59.102318]}', '<p><span>Борисовский дом культуры, здание которого было построено в 1966 г., сегодня является центром культурной жизни и общения для местных жителей. </span><span> </span><span>Это основная площадка для проведения организованного досуга, место встреч односельчан. </span><span>На базе учреждения проводятся концерты, культурно-массовые и просветительские мероприятия для детей и взрослых.</span></p> <p><span>Работник культуры и члены творческих коллективов активно принимают участие в праздничных концертах, ярмарках, конкурсах и других мероприятиях, проводимых в районе.</span></p> <p><span>Здесь действуют следующие клубные формирования:</span></p> <ol><li><span>Клуб любителей декоративно-прикладного творчества.</span><span></span></li><li><span>Детский танцевальный коллектив.</span><span></span></li><li><span>Изобразительная студия.</span><span></span></li><li><span>Детский вокальный коллектив.</span><span></span></li><li><span>Фитнес для детей.</span><span></span></li><li><span>Кружок по вокалу.</span><span></span></li><li><span>Театр малых форм.</span><span></span></li><li><span>Игротека – клуб любителей игр.</span><span></span></li><li><span>Клуб ветеранов.</span><span></span></li><li><span>Молодежный клуб общения.</span></li></ol>', NULL, 'mbuborisovskiidk@yandex.ru', '[{"value": "78174131225", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/def3f14224265ffc28ad3fc892b899e0.jpg", "title": "IMG_20221116_095935.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУ «Белокрестское СКО»', 'Чагодощенский район', 'Europe/Moscow', 'ул Кооперативная,д 23Б', NULL, 'обл Вологодская,р-н Чагодощенский,с Белые Кресты,ул Кооперативная,д 23Б', NULL, 3522003619, 'mincult', 'Чагодощенский район', 'Europe/Moscow', NULL, 17335, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, NULL, '{"to": "21:20:00", "from": "14:00:00"}', '{"to": "21:20:00", "from": "14:00:00"}', '{"to": "21:20:00", "from": "14:00:00"}', '{"to": "21:20:00", "from": "14:00:00"}', '{"to": "21:20:00", "from": "14:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78657, '[{"url":"https://www.culture.ru/institutes/91526/borisovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/chagoda/dvorcy-kultury-i-kluby/98779pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2023-04-05 12:08:06+03', '2023-04-05 15:03:35+03', '0101000020E6100000E19A3BFA5FB0414064E597C1188D4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Борисовский дом культуры', 'Вологодский район', 'Europe/Moscow', 'д 62', NULL, 'обл Вологодская,р-н Вологодский,д Новое,д 62', '{"type": "Point", "coordinates": [39.700577, 59.211534]}', '<p>Борисовский дом культуры открыл свои двери в ноябре 1979 г.</p><p>Для посетителей проводятся мероприятия различных форм: </p><ul><li>конкурсные, развлекательные, концертные программы;</li><li>викторины;</li><li>выставки;</li><li>вечера отдыха;</li><li> торжественные митинги и акции;</li><li> мероприятия ко Дню пожилого человека;</li><li>народные гулянья;</li><li> новогодние праздники для детей и взрослых;</li><li>дискотеки для детей и взрослых.<br /></li></ul><p>В Доме культуры работают клубные формирования: </p><ul><li>кружок по выжиганию;</li><li>«Умелые ручки»;</li><li>кружок по изготовлению мягкой игрушки;</li><li>танцевальный кружок;</li><li>«МукосОлька»;</li><li>группа здоровья;</li><li>кружок по вязанию;</li><li>кружок по бисероплетению;</li><li>клуб «Приходи, сказка»;</li><li>клуб любителей настольных игр;</li><li>клуб «Почемучка»;</li><li> клуб «Сударыня»;</li><li> клуб выходного дня.</li></ul>', NULL, NULL, '[{"value": "78172773256", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/c3ba5e129585b9e4ed2affbde8760bcd.png", "title": "FD6325D5-C36D-4C70-B835-83F56D3AF0E4.png"}', '[{"url": "https://all.culture.ru/uploads/40ce27b7f4e2684ea7f516283510be99.jpeg", "title": "08344E81-40BB-4FED-B4AC-A8FA1B9EC847.jpeg"}, {"url": "https://all.culture.ru/uploads/fa2182df1e637ed3dad4226ad3a86762.jpeg", "title": "D4985055-6026-46BA-B800-245C1AEA47E1.jpeg"}, {"url": "https://all.culture.ru/uploads/3651ca54f2180475df16c413a3a779dc.png", "title": "EC04B873-4A0B-4365-842B-235313BDA127.png"}]', NULL, 'Дворцы культуры и клубы', 'МБУК ВМО «Кубенское КДО»', 'Вологодский район', 'Europe/Moscow', 'ул Ленина,д 48', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Ленина,д 48', NULL, 3507303576, 'mincult', 'Вологодский район', 'Europe/Moscow', '[{"network":"vk","name":"МБУК ВМО\"Кубенское КДО\" филиал\"ОСТАХОВСКИЙ КЛУБ\"","networkId":"164012905","updateDate":"2023-04-04T14:37:50Z","createDate":"2023-04-04T14:37:50Z","accountId":46927,"postingGroupId":41496}]', 13691, '[{"id": 21, "name": "Выставочные залы", "sysName": "vystavochnye-zaly"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, NULL, '{"to": "19:00:00", "from": "13:00:00"}', '{"to": "19:00:00", "from": "13:00:00"}', '{"to": "19:00:00", "from": "13:00:00"}', '{"to": "19:00:00", "from": "13:00:00"}', '{"to": "14:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "12:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78628, '[{"url":"https://www.culture.ru/institutes/91494/borisovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/98760pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2023-04-04 22:52:13+03', '2023-04-05 20:25:17+03', '0101000020E610000037AAD381ACD94340FCFECD8B139B4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Шолоховский клуб', 'Вологодский район', 'Europe/Moscow', 'ул Школьная,стр 2', NULL, 'обл Вологодская,р-н Вологодский,д Шолохово,ул Школьная,стр 2', '{"type": "Point", "coordinates": [39.439032, 59.55529]}', '<p> Здание Шолоховского клуба было построено в 1914 году. Сейчас в филиале работает 4 клубных формирования для детей и взрослых по различным направлениям деятельности: спортивно-оздоровительное, вокальное, познавательное, игровое, изобразительной деятельности, клуб «Аптечка здоровья», клуб «Ветеран». Ветераны занимаются скандинавской ходьбой, активно посещают мероприятия. Концерты проводятся ко всем праздничным и памятным датам. Дети любят игровые программы, дискотеки. В филиале для всех категорий населения проводятся различные развлекательные и тематические мероприятия, выставки, конкурсы, соревнования, викторины. Самыми любимыми у зрителей являются День деревни, Новый год и 8 Марта.</p>', NULL, NULL, '[{"value": "79115026593"}]', '{"url": "https://all.culture.ru/uploads/3c473f16ae91385707df31f33c9cb29e.jpg", "title": "a0C-pFftbCg.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Новленский Дом культуры»', 'Вологодский район', 'Europe/Moscow', 'ул Советская,д 30', NULL, 'обл Вологодская,р-н Вологодский,с Новленское,ул Советская,д 30', NULL, 3507303368, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14125, '[{"id": 28, "name": "Литература", "sysName": "literatura"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, NULL, '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78608, '[{"url":"https://www.culture.ru/institutes/91497/sholokhovskii-klub","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-04-04 14:51:11+03', '2023-04-05 12:18:08+03', '0101000020E6100000E0F2583332B84340DEE522BE13C74D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Дом культуры «Северные зори»', 'Вологодский район', 'Europe/Moscow', 'д 24', NULL, 'обл Вологодская,р-н Вологодский,д Фофанцево,д 24', '{"type": "Point", "coordinates": [39.994766, 59.32803]}', '<p>Дом культуры создан в декабре 1970 года. В настоящее время организует работу кружков и любительских объединений, проводит праздничные вечера и концерты, тематические программы, семейные праздники, спектакли и другие мероприятия.</p><p> На базе Дома культуры работают 24 кружка, в которых постоянно занимается более 300 человек. Участники вокальных, танцевальных и театральных коллективов неоднократно становились победителями всероссийских, региональных, районных фестивалей и конкурсов. Руководителями клубных формирований «Сударушка», «Колечко», «Ладушка», «Непоседы», «Бабушкино ремесло», «Грация» и других являются работники учреждения культуры.</p>', NULL, NULL, NULL, '{"url": "https://all.culture.ru/uploads/00f29276173175ef8b73fc85cb7770ac.jpg", "title": "IMG_20230405_145011.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК ДК «Северные Зори»', 'Вологодский район', 'Europe/Moscow', 'д 24', NULL, 'обл Вологодская,р-н Вологодский,д Фофанцево,д 24', NULL, 3507303304, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14069, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "20:15:00", "from": "09:00:00"}', '{"to": "20:30:00", "from": "09:00:00"}', '{"to": "20:00:00", "from": "09:00:00"}', '{"to": "20:30:00", "from": "09:00:00"}', '{"to": "22:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78590, '[{"url":"https://www.culture.ru/institutes/91461/dom-kultury-severnye-zori","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/98870pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2023-04-04 12:34:18+03', '2023-04-06 16:56:46+03', '0101000020E61000001C96067E54FF4340AE0D15E3FCA94D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Остаховский клуб', 'Вологодский район', 'Europe/Moscow', 'ул Центральная,д 4', NULL, 'обл Вологодская,р-н Вологодский,с Остахово,ул Центральная,д 4', '{"type": "Point", "coordinates": [39.50558, 59.378887]}', '<p>История клуба началась в 1953 году. Сегодня он является любимым местом культурного досуга и отдыха, общения и творческой самореализации жителей. </p><p>В Остаховском клубе ведут работу кружки для разных возрастных групп посетителей: танцевальный, «Веселые нотки», «ОчУмелые ручки», для людей старшего поколения – клуб «Ветеран». Молодежь занимается на тренажерах и играет в бильярд. Проводятся выставки, конкурсные программы, вечера отдыха, дискотеки для взрослых и детей.</p><p>Все коллективы принимают активное участие в праздниках, концертных программах и конкурсах клуба.</p><p>Самым массовым и любимым праздником жителей села является Масленица.</p>', NULL, 'khrustaleva9191@bk.ru', '[{"value": "79005588258"}, {"value": "79005588258"}]', '{"url": "https://all.culture.ru/uploads/b8e2a01cdcbcf3660f6aa3bc7edb5dee.jpg", "title": "здание дк.jpg"}', '[{"url": "https://all.culture.ru/uploads/1890dcf40ff0bfec9cd1ec99d890904b.jpg", "title": "масленица дети.jpg"}, {"url": "https://all.culture.ru/uploads/fe3886b8b9f25aca0e8beba9c5eb4572.jpg", "title": "новый год.jpg"}, {"url": "https://all.culture.ru/uploads/2295add708ac7a2cad6ef20a1f6889d2.jpg", "title": "околица.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУК ВМО «Кубенское КДО»', 'Вологодский район', 'Europe/Moscow', 'ул Ленина,д 48', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Ленина,д 48', NULL, 3507303576, 'mincult', 'Вологодский район', 'Europe/Moscow', '[{"network":"vk","name":"МБУК ВМО\"Кубенское КДО\" филиал\"ОСТАХОВСКИЙ КЛУБ\"","networkId":"164012905","updateDate":"2023-04-04T14:37:50Z","createDate":"2023-04-04T14:37:50Z","accountId":46927,"postingGroupId":41496}]', 13691, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, NULL, '{"to": "17:00:00", "from": "14:00:00"}', '{"to": "17:00:00", "from": "14:00:00"}', '{"to": "17:00:00", "from": "14:00:00"}', '{"to": "17:00:00", "from": "14:00:00"}', '{"to": "16:00:00", "from": "14:00:00"}', '{"to": "16:00:00", "from": "14:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78472, '[{"url":"https://www.culture.ru/institutes/91344/ostakhovskii-klub","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-03-31 19:26:45+03', '2023-04-03 17:58:58+03', '0101000020E61000007FC16ED8B6C0434095F0845E7FB04D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Дом культуры с. Кубенского', 'Вологодский район', 'Europe/Moscow', 'ул Ленина,д 48', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Ленина,д 48', '{"type": "Point", "coordinates": [39.669127, 59.434492]}', '<p>Дом культуры в селе Кубенском был основан в 30-х годах прошлого столетия в здании бывшего Дмитриевского храма. В 1978 году было пристроено основное здание Дома культуры площадью 1 241,9 кв. м. </p><p>Основное направление деятельности – организация досуга и приобщение людей к творчеству, культурному развитию и самообразованию, любительскому искусству, традиционной народной культуре. В Доме культуры работают 26 коллективов художественного творчества и любительских объединений. </p><p>Народный самодеятельный коллектив ансамбль русской песни «Кубяночка» создан в 2002 году, является лауреатом областных, всероссийских и международный конкурсов и фестивалей. Образцовый художественный коллектив хореографического направления работает в Доме культуры с 1994 года, в нем 7 возрастных групп, более 70 человек. Работают коллективы: киноклуб «В гостях у сказки», театр малых форм, детский эстрадный хор, вокальный ансамбль «Улыбка», коллектив солистов (взрослый и детский), клуб ритмики для взрослых. </p>', NULL, 'kubdk@mail.ru', '[{"value": "79517302388"}]', '{"url": "https://all.culture.ru/uploads/2d31728b81e5547979e2a7acc744c3b6.JPG", "title": "IMG_2272 - копия.JPG"}', '[{"url": "https://all.culture.ru/uploads/a79a84255ce0f09cef1ac4e9f3375878.jpg", "title": "JAF6OV6eqeg.jpg"}, {"url": "https://all.culture.ru/uploads/02d204c6633ca920fe517fd1f4e7a22e.jpg", "title": "X_vnSzFDUJE.jpg"}, {"url": "https://all.culture.ru/uploads/907b38a4b1cdf40c6bb13f24b03fd1cf.JPG", "title": "IMG_0711.JPG"}]', NULL, 'Дворцы культуры и клубы', 'МБУК ВМО «Кубенское КДО»', 'Вологодский район', 'Europe/Moscow', 'ул Ленина,д 48', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Ленина,д 48', NULL, 3507303576, 'mincult', 'Вологодский район', 'Europe/Moscow', '[{"network":"vk","name":"МБУК ВМО\"Кубенское КДО\" филиал\"ОСТАХОВСКИЙ КЛУБ\"","networkId":"164012905","updateDate":"2023-04-04T14:37:50Z","createDate":"2023-04-04T14:37:50Z","accountId":46927,"postingGroupId":41496}]', 13691, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78457, '[{"url":"https://www.culture.ru/institutes/91302/dom-kultury-s-kubenskogo","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-03-31 13:22:29+03', '2023-03-31 13:51:46+03', '0101000020E610000070EF1AF4A5D54340D32F116F9DB74D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Погореловский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Центральная,д 1', NULL, 'обл Вологодская,р-н Вологодский,с Погорелово (Сосновское МО),ул Центральная,д 1', '{"type": "Point", "coordinates": [39.589455, 59.148535]}', '<p><span>Погореловский дом культуры был открыт 30 декабря 1972 года. Общая площадь здания – 319,1 кв. м, зрительный зал рассчитан на 100 мест. В зоне обслуживания проживает более 500 человек. </span><span>Коллектив Дома культуры активно сотрудничает со школой, детским садом, библиотекой и учреждением спорта. Дом культуры является центром развития и поддержки культурно-социальных инициатив населения, развития творческих способностей и организации активного отдыха. </span></p><p></p><p><span>На базе учреждения работают 18 клубных формирований разных направлений, для взрослых – 5, для детей – 13.<span> Общее количество</span> участников – 160 человек. Ведут активную деятельность кружки изобразительного искусства, декоративно-прикладного, вокального, хореографического и театрального творчества. </span></p><p><span>Для посетителей проводятся игровые и развлекательные программы, театрализованные представления и праздники, концерты, вечера отдыха. </span></p><p></p>', NULL, 'nick.anosov2016@yandex.ru', '[{"value": "79115212241"}, {"value": "78172775559", "comment": "Основной"}]', '{"url": "https://all.culture.ru/uploads/f2055655dacff07345e922b06a8295c2.jpg", "title": "4qreSw2atIU.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «КДО «Сосновское»', 'Вологодский район', 'Europe/Moscow', 'ул Молодежная,д 3', NULL, 'обл Вологодская,р-н Вологодский,п Сосновка,ул Молодежная,д 3', NULL, 3507313790, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 13824, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78438, '[{"url":"https://www.culture.ru/institutes/91313/pogorelovskii-dom-kultury","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-03-31 10:43:16+03', '2023-03-31 15:05:12+03', '0101000020E61000005ABBED4273CB4340DBA7E33103934D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Центр культурного развития с. Кубенского', 'Вологодский район', 'Europe/Moscow', 'ул Ленина,д 50', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Ленина,д 50', '{"type": "Point", "coordinates": [39.668821, 59.434885]}', '<p><span>Центр культурного развития открыт 1 января 2018 года. Он</span><span> создан для организации досуга и приобщения населения округа к творчеству, культурному развитию, самообразованию, традиционной народной культуре. </span><span>Работа учреждения высоко ценится органами местного самоуправления и неоднократно была отмечена благодарностями. </span></p><p><span>С 2018 года организовано и проведено более 150 крупных культурно-массовых мероприятий, основными из которых являются:</span><span></span></p><ul><li><span>фестиваль исторической реконструкции «Дворянских гнезд заветные аллеи» (июль 2018–2022 годов);</span></li><li><span>патриотический праздник «Открытое небо» (август 2018–2022 годов).</span></li></ul> <p><span>Реализуемый с 2018 года фестиваль исторической реконструкции «Дворянских гнезд заветные аллеи» стал ярким и узнаваемым проектом культурной жизни Вологодчины. В 2020 году он получил 3-е место в национальной премии «События России – 2020» в номинации «Культура. Военно-исторические и культурные реконструкции».</span></p>', NULL, 'cultura35@mail.ru', '[{"value": "79210559101", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/25930c63cf5c44baba7057928e204751.jpg", "title": "RZ9zSTVYa60.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры Вологодского муниципального района «Центр культурного развития»', 'Вологодский район', 'Europe/Moscow', 'ул Ленина,д 50', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Ленина,д 50', NULL, 3525221703, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 26358, '[{"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}]', NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78399, '[{"url":"https://www.culture.ru/institutes/91554/centr-kulturnogo-razvitiya-s-kubenskogo","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-03-30 14:48:06+03', '2023-04-06 08:55:46+03', '0101000020E610000063F030ED9BD54340AF42CA4FAAB74D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Майский дом культуры', 'Вологодский район', 'Europe/Moscow', 'д 14', NULL, 'обл Вологодская,р-н Вологодский,п Майский,д 14', '{"type": "Point", "coordinates": [39.745798, 59.25896]}', '<p><span><span> </span>История Дома культуры в п. Майском началась в 1976 году. </span></p><p><span></span><span>В 2019 году<span> </span>практически во всех помещениях здания был выполнен капитальный ремонт, и</span><span> сейчас Дом культуры <span> </span>является любимым местом комфортного досуга, общения и творческой самореализации жителей.</span></p> <p><span><span> </span>Здесь проводятся занятия кружков для всех возрастных групп населения. </span><span>В коллективе постоянно ведется не только учебная работа, но и организуются выставки, конкурсы и экскурсии, проводятся беседы по искусству, праздничные вечера. </span></p> <p><span><span> </span>С 2022 года в Майском доме культуры регулярно проходят интеллектуально-развлекательные игры, которые пользуются большой популярностью не только у местных жителей. В 2023 году Татьяна Владимировна Бойко организовала медиаклуб «Звезды «Севера ТВ», где ребят обучают журналистике, актерскому мастерству и<span> </span>премудростям монтажа.</span></p> <p><span><span> </span></span></p> <p><span><span> </span>В дружеской атмосфере проходят различные праздники и концертные программы. Самые массовые и горячо любимые мероприятия – День поселка, День меда, гулянья, посвященные Масленице, и др.</span></p> <p><span><span> </span></span></p>', NULL, 'Mayskiy.dk@bk.ru', '[{"value": "79814402316"}, {"value": "79110452263", "comment": "тел. директора"}]', '{"url": "https://all.culture.ru/uploads/126b664474d567e2a224ed56ec4859ab.jpg", "title": "про культура 1.jpg"}', '[{"url": "https://all.culture.ru/uploads/d116a036458d5a6b54b209ee477044a4.jpg", "title": "1.1.jpg"}, {"url": "https://all.culture.ru/uploads/166de680d6a35870465993cfec8428ac.jpg", "title": "1.2.jpg"}, {"url": "https://all.culture.ru/uploads/7be236dd82aa26218f0a19bfd832ef84.jpg", "title": "1.4.jpg"}, {"url": "https://all.culture.ru/uploads/075af3895d46ad11c19c88f66775fd79.jpg", "title": "1.31.jpg"}, {"url": "https://all.culture.ru/uploads/fb43e2eef0087e6017646ba417e97d54.jpg", "title": "1.2.jpg"}, {"url": "https://all.culture.ru/uploads/3f1637df6957b526bcf3b4a9126746b8.jpg", "title": "3.2.jpg"}, {"url": "https://all.culture.ru/uploads/3c67ef7315a8d670d7e381475b1cdb0b.jpg", "title": "2.18.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУК «Майский Дом культуры»', 'Вологодский район', 'Europe/Moscow', 'д 14', NULL, 'обл Вологодская,р-н Вологодский,п Майский,д 14', NULL, 3507303463, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14049, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78356, '[{"url":"https://www.culture.ru/institutes/91246/maiskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/98302pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2023-03-29 17:07:23+03', '2023-03-31 10:35:11+03', '0101000020E61000000BB6114F76DF4340707CED9925A14D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Дом культуры с. Куркино', 'Вологодский район', 'Europe/Moscow', 'ул Школьная,д 13', 'Маршрут № 403 «Вологда – Кубенское» (через Куркино)', 'обл Вологодская,р-н Вологодский,с Куркино,ул Школьная,д 13', '{"type": "Point", "coordinates": [39.6312240878709, 59.36243844587982]}', '<p>История Дома культуры в селе Куркино началась в 1977 году. Сейчас он является любимым местом комфортного досуга, общения и творческой самореализации жителей.</p><p>Здесь проводятся занятия кружков для всех возрастных групп: кружок декоративно-прикладного творчества «Модульное оригами», кружок вокала «Радуга», ветеранская организация. Для каждой возрастной группы создана авторская программа обучения. Количество участников кружка постоянно увеличивается.</p><p>В коллективе постоянно ведется не только учебная работа, но и организуются выставки, конкурсы и экскурсии, проводятся беседы по искусству, праздничные вечера. В дружеской атмосфере проходят различные праздники и концертные программы. Самым массовым и горячо любимым мероприятием с. Куркино является день проводов зимы и Масленица.</p>', 'https://vk.link/club117747732', 'irina.ordiyan@mail.ru', '[{"value": "79814402162"}, {"value": "79115335565"}]', '{"url": "https://all.culture.ru/uploads/38d5a6040704547decb006c4586ac368.jpg", "title": "--E8X3f9Egg.jpg"}', '[{"url": "https://all.culture.ru/uploads/7112f13aa7f6e9f2b2582c618afa4b3d.jpg", "title": "Куркино.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУК «Майский Дом культуры»', 'Вологодский район', 'Europe/Moscow', 'д 14', NULL, 'обл Вологодская,р-н Вологодский,п Майский,д 14', NULL, 3507303463, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14049, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 325, "name": "Творческий коллектив", "sysName": "tvorcheskiy-kollektiv"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 67870, '[{"url":"https://www.culture.ru/institutes/81290/dom-kultury-s-kurkino","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/82046pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-04-01 17:06:26+03', '2023-03-28 10:21:11+03', '0101000020E61000002DED6EF3CBD04340F6EE0B6264AE4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Дом культуры п. Заря', 'Вологодский район', 'Europe/Moscow', 'д 41', 'Маршрут № 412 «Вологда – Заря»', 'обл Вологодская,р-н Вологодский,п Заря,д 41', '{"type": "Point", "coordinates": [39.494467, 59.297682]}', '<p>История Дома культуры в поселке Заря началась в 2004 году. Сейчас он является местом комфортного досуга, общения и творческой самореализации жителей.</p><p>Здесь проводятся занятия кружков для всех возрастных групп: вокальный ансамбль «Новое поколение», студия раннего развития ребенка «Малыш и Карлсон», семейный клуб «Птица счастья». Для каждой возрастной группы создана авторская программа обучения. Количество участников кружка постоянно увеличивается.</p><p>В коллективе ведется не только учебная работа, но и организуются выставки, конкурсы и экскурсии, проводятся беседы по искусству, праздничные вечера. В дружеской атмосфере проходят различные праздники и концертные программы. Самым массовым и любимым мероприятием является празднование Дня поселка Заря. </p>', 'https://vk.link/dkzara', 'dk.zarya@bk.ru', '[{"value": "79814402257", "comment": ""}, {"value": "79005370635", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/8b4891f618bc74938f6a3310f43aed98.jpg", "title": "GqUHKT1RflM.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Майский Дом культуры»', 'Вологодский район', 'Europe/Moscow', 'д 14', NULL, 'обл Вологодская,р-н Вологодский,п Майский,д 14', NULL, 3507303463, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14049, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 59, "name": "Ансамбли", "sysName": "ansambli"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 322, "name": "Хор", "sysName": "hor"}, {"id": 325, "name": "Творческий коллектив", "sysName": "tvorcheskiy-kollektiv"}, {"id": 329, "name": "Ремесла и художественные промыслы", "sysName": "remesla-i-hudozhestvennye-promysly"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 67866, '[{"url":"https://www.culture.ru/institutes/81288/dom-kultury-p-zarya","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/82045pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-04-01 16:38:16+03', '2023-03-24 16:54:29+03', '0101000020E6100000C2F9D4B14ABF4340CF4D9B711AA64D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Малечкинский сельский дом культуры', 'Череповецкий район', 'Europe/Moscow', 'ул Победы,д 2а', NULL, 'обл Вологодская,р-н Череповецкий,п Малечкино,ул Победы,д 2а', '{"type": "Point", "coordinates": [37.86681, 59.213501]}', '<p>Малечкинский сельский дом культуры создан в 1960-х гг. Здесь работают 16 клубных формирований. Звания «народный» и «образцовый» присвоены самодеятельным коллективам: хор русской песни, танцевальный коллектив, вокальный ансамбль «Отрада», детский танцевальный коллектив «Малечкиночка». Также зрительской любовью пользуются детский вокальный коллектив «Мозаика», детский клуб кулачных бойцов «Буза», детский театральный коллектив «Рассвет», выступления солистов народного и эстрадного направления. </p><p> Основной задачей деятельности учреждения является организация досуга населения, сохранение и развитие народного творчества. Для жителей поселка проводятся мероприятия, соответствующие возрастным категориям участников. Для детей – утренники, игровые, развлекательные и познавательные программы. Для молодежи и людей среднего возраста – вечера отдыха, дискотеки, шоу-программы. Среди ветеранов большой популярностью пользуются программы клуба «Играй, гармонь!», «Посиделки», тематические программы к знаменательным датам. Жители Малечкино всех возрастов очень любят посещать концерты своих творческих коллективов, народные гуляния, театрализованные программы. </p>', 'http://mcko.vlg.muzkult.ru', 'dkmalehkino2011@yandex.ru', '[{"value": "78202695469", "comment": "факс"}, {"value": "79602922510", "comment": "Директор Петрова О.Е."}]', '{"url": "https://all.culture.ru/uploads/0129fdc608c604eec858af67165318a7.jpg", "title": "2cd2511ac647b4c694a982500d6b6887.jpg"}', '[{"url": "https://all.culture.ru/uploads/dca4d41f84b08233037d697ede6625cf.JPEG", "title": "IMG_0986.JPEG"}, {"url": "https://all.culture.ru/uploads/54bf8b63e2418126d0115dffdb9fbed1.JPG", "title": "IMG_4721.JPG"}, {"url": "https://all.culture.ru/uploads/e0af4feda802fdb9d6c887eb354baeef.jpg", "title": "20210418_164616.jpg"}, {"url": "https://all.culture.ru/uploads/25c2b0b02f564c332f2f7c2d99880b4f.JPG", "title": "C.JPG"}, {"url": "https://all.culture.ru/uploads/b3ad475f43cc0144e00dc4cf229e5855.jpg", "title": "20191025_123504.jpg"}, {"url": "https://all.culture.ru/uploads/ef2932ddbf85dd75db11018a9d7f6518.jpg", "title": "ЗАНАВЕС.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МУК «Малечкинское социально-культурное объединение»', 'Череповецкий район', 'Europe/Moscow', 'ул Победы,д 2а', NULL, 'обл Вологодская,р-н Череповецкий,п Малечкино,ул Победы,д 2а', NULL, 3523014518, 'mincult', 'Череповецкий район', 'Europe/Moscow', NULL, 20458, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 59, "name": "Ансамбли", "sysName": "ansambli"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 322, "name": "Хор", "sysName": "hor"}, {"id": 325, "name": "Творческий коллектив", "sysName": "tvorcheskiy-kollektiv"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, '{"to": "20:00:00", "from": "09:00:00"}', '{"to": "20:00:00", "from": "09:00:00"}', '{"to": "20:00:00", "from": "09:00:00"}', '{"to": "20:00:00", "from": "09:00:00"}', '{"to": "20:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 65856, '[{"url":"https://www.culture.ru/institutes/79005/malechkinskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/71916pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-03-21 18:05:26+03', '2023-03-27 17:44:23+03', '0101000020E610000042EC4CA1F3EE4240E7543200549B4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Ботовский сельский дом культуры', 'Череповецкий район', 'Europe/Moscow', 'ул Ленина,зд 20', NULL, 'обл Вологодская,р-н Череповецкий,д Ботово,ул Ленина,зд 20', '{"type": "Point", "coordinates": [37.966137, 59.258891]}', '<p><span>Ботовский сельский дом культуры<span> был построен в 1965 г. и представляет собой здание </span></span><span>площадью 407,9 кв. м со зрительным залом на 200 мест. В период выборов здесь располагается избирательный участок № 845. </span></p> <p><span>Зрительный зал используется<span> </span>как хореографический и как помещение для проведения молодежных дискотек, игровых программ.<span> </span></span></p> <p><span>Действуют творческие коллективы: народный хор<span> </span>русской песни «Цветенье», народный хореографический коллектив «Радуница», образцовый хореографический коллектив «Незабудка», образцовый художественный театральный коллектив «Хрустальный шар», работают кружки и клубы по интересам. </span><span>Самому младшему участнику творческого коллектива 4 года, а самым старшим – более 80 лет.</span></p> <p><span>Ансамбли Дома культуры принимают участие в районных, областных, международных, всероссийских конкурсах и фестивалях, а также выезжают с концертами в Череповец и другие города.</span></p> <p><span>Для населения проводятся театрализованные программы, народные праздники, экскурсии, мастер-классы, действует сувенирная лавка.</span><br /></p>', 'https://botovo-sko.kulturu.ru', 'botovo-sko@mail.ru', '[{"value": "78202668233"}]', '{"url": "https://all.culture.ru/uploads/6d9abe8ce0840616733447d15dede683.jpg", "title": "ДК снаружи.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Ботовское СКО»', 'Череповецкий район', 'Europe/Moscow', 'ул Ленина,20', NULL, 'обл Вологодская,р-н Череповецкий,д Ботово,ул Ленина,20', NULL, 3523014613, 'othergov', 'Череповецкий район', 'Europe/Moscow', '[{"network":"vk","name":"Мбук-Ботовское-Ско Дом-Культуры","networkId":"355402279","isPersonal":true,"updateDate":"2018-05-17T13:30:51Z","createDate":"2018-05-17T13:30:51Z","accountId":21271,"postingGroupId":18848}]', 20457, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 64581, '[{"url":"https://www.culture.ru/institutes/65848/botovskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/82437pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-02-28 16:54:28+03', '2023-03-28 10:10:22+03', '0101000020E6100000503A9160AAFB4240471D1D5723A14D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Семенковский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Первомайская,д 17', NULL, 'обл Вологодская,р-н Вологодский,с/п Семенковское,ул Первомайская,д 17', '{"type": "Point", "coordinates": [39.85766594260595, 59.28079246346145]}', '<p>Дом культуры поселка Семенково. Построен в 1967 году. Направление деятельности: культурно-досуговая. На базе ДК работают 15 клубных формирований различных направлений: хореографические, вокальные, художественные и спортивные. Одним из ярких представителей дома культуры является студия танца и акробатики «Вертикаль», в 2019 году ему присвоено звание «Образцовый художественный коллектив». Руководитель студии – Ефимова Татьяна Евгеньевна. Ведется работа с возрастным населением. Для них создан: совет женщин поселка Семенково и Совет ветеранов. Занятия клуба «Рукоделие» ждут всех желающих по понедельникам с 13.00. Также для людей старшего возраста проходят занятия по дыхательной гимнастике и скандинавской ходьбе.</p><p>В Семенковском дк работает вокальная студия, руководитель – Буданова Анна Борисовна. На базе дк работает изо-студия, которой руководит талантливый педегог – Маковеева Ольга Михайловна, а так же секция самбо, которую возглавляет мастер боевых искусств. </p><p>Участники коллективов дома культуры принимают активное участие в различных фестивалях, конкурсах и являются украшением тематических концертов, которые проходят в стенах дома культуры.</p>', 'https://vk.link/club51727930', NULL, '[]', '{"url": "https://all.culture.ru/uploads/67754bd8798c85061b48107068cb4a61.jpg", "title": "IMG_20210406_114842 (2).jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Семёнковское клубное объединение»', 'Вологодский район', 'Europe/Moscow', 'ул Первомайская,д 17', NULL, 'обл Вологодская,р-н Вологодский,п Семенково (Семенковское МО),ул Первомайская,д 17', NULL, 3507303470, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14048, NULL, NULL, '{"to": "22:00:00", "from": "09:00:00"}', '{"to": "22:00:00", "from": "09:00:00"}', '{"to": "22:00:00", "from": "09:00:00"}', '{"to": "22:00:00", "from": "09:00:00"}', '{"to": "22:00:00", "from": "09:00:00"}', NULL, '{"to": "18:00:00", "from": "13:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 51291, '[{"url":"https://www.culture.ru/institutes/76436/semenkovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/75396pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2021-04-14 14:57:14+03', '2023-03-28 10:38:49+03', '0101000020E61000005A3163FFC7ED4340DEC3E701F1A34D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Спасский дом культуры', 'Вологодский район', 'Europe/Moscow', 'д 50', NULL, 'обл Вологодская,р-н Вологодский,п Непотягово,д 50', '{"type": "Point", "coordinates": [39.815516, 59.145429]}', '<p>Спасский дом культуры начал свою деятельность с ноября 1988 г. П<span>лощадь здания – 1 289,7 кв. м. В 2021 г. был произведен капитальный ремонт зрительного зала, в 2022 г. – ремонт хореографического класса. </span></p><p><span>На базе Дома культуры ведут работу 27 клубных формирований разных направлений: хореография, вокал, декоративно-прикладное творчество, спорт. Действуют клубы по интересам. Два вокальных коллектива имеют звание «народный»: «Сударыня» и «Подорожники» (руководитель – Кокина Галина Альбертовна, концертмейстер – Яблоков Сергей Алексеевич). Хореографическая студия «Кристалл» имеет звание образцового художественного коллектива (руководитель – Кожевина Мария Сергеевна, хореограф – Семенова Анастасия Павловна).</span><span></span></p><p><span>Ведется работа с людьми пенсионного возраста. Для них созданы клубы «Добро» и «Ветеран», работает кружок «Рукодельница», также ведутся занятия по хореографии и фитнесу. Вот уже 13 лет зрителей поселка радуют такие коллективы, как ансамбль ветеранов «Родники» и ансамбль «Лада» (руководитель – Сняткова Галина Семеновна).</span><span></span></p><p><span>Пять лет работает студия этнического танца «Радушка», в которой занимаются как взрослые, так и дети (руководитель – Соколова Раиса Николаевна). Студия восточного танца «Жасмин» также включает в себя две группы – детскую и взрослую (руководитель – Мелек Марина Валерьевна).</span></p> <p>Действует<span> вокальная студия «Веселые нотки», в которую входят четыре детских вокальных коллектива разных возрастных групп: «Капельки», «Непоседы», «Карамель», «Настроение» (руководитель – Потапова Наталья Николаевна).</span></p> <p><span>Кроме того, работает кружок по робототехнике и компьютерной грамотности, спортивная секция по тхэквондо. С удовольствием и взрослые, и дети посещают занятия по зумбе (танцевальный фитнес). Руководитель – Лугова Наталья Александровна.</span></p> <p><span>Члены клубных формирований Дома культуры активно принимают участие в различных конкурсах и фестивалях. </span></p><p></p>', NULL, 'spasskiydomcultura@mail.ru', '[{"value": "78172557080"}]', '{"url": "https://all.culture.ru/uploads/2af87f71e6bd59d3e8158e92f3d99be5.jpeg", "title": "Фасад Непотягово.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры Вологодского муниципального района «Центр культурного развития»', 'Вологодский район', 'Europe/Moscow', 'ул Ленина,д 50', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Ленина,д 50', NULL, 3525221703, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 26358, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "14:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 51283, '[{"url":"https://www.culture.ru/institutes/76408/spasskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/98263pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2021-04-14 14:44:12+03', '2023-04-06 13:03:16+03', '0101000020E6100000B0AE0AD462E84340EB71DF6A9D924D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Ермаковский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Строителей,д 17', NULL, 'обл Вологодская,р-н Вологодский,п Ермаково,ул Строителей,д 17', '{"type": "Point", "coordinates": [39.70628515938568, 59.19235281799372]}', '<p><span>Ермаковский дом культуры построен в<span> </span>1979 году. </span><span>Направление деятельности – культурно-досуговая. Общая площадь – 1 216,7 кв. м, зрительный зал рассчитан на 318 мест. В зоне обслуживания Дома культуры проживает около 2 000 человек. </span><span></span></p><p><span>На базе Дома культуры работают 25 клубных формирований различных направлений: взрослые – 4, детские – 16.<span> </span>Всего участников – 229. Для детей и взрослых действуют кружки изобразительного искусства, прикладного, вокального, хореографического и театрального творчества. В Доме культуры проводятся игровые и развлекательные программы, театрализованные представления и праздники, концерты, вечера отдыха. </span></p>', NULL, 'sosnovskoekdo@yandex.ru', '[{"value": "79535196254", "comment": ""}, {"value": "78172552794", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/94a9fe19bec4ebf02633ca59ce7b269a.jpeg", "title": "аис.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «КДО «Сосновское»', 'Вологодский район', 'Europe/Moscow', 'ул Молодежная,д 3', NULL, 'обл Вологодская,р-н Вологодский,п Сосновка,ул Молодежная,д 3', NULL, 3507313790, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 13824, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40583, '[{"url":"https://www.culture.ru/institutes/73105/ermakovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/98109pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2019-11-01 21:04:23+03', '2023-03-30 16:24:32+03', '0101000020E6100000179B568D67DA4340CA4963049F984D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Лесковский дом культуры', 'Вологодский район', 'Europe/Moscow', 'д 31', NULL, 'обл Вологодская,р-н Вологодский,п Лесково,д 31', '{"type": "Point", "coordinates": [39.637821, 59.201679]}', '<p><span>Дом культуры п. Лесково был открыт 10 января 1981 года. Здание 1980 года постройки, двухэтажное. Общая площадь – 826,8 кв. м, зрительный зал рассчитан на 250 мест.</span><span> В зоне обслуживания Дома культуры проживает около 1 000 человек.</span><span></span></p> <p><span>На базе учреждения ведут работу 23 клубных формирования разных направлений. Для детей и взрослых действуют кружки изобразительного искусства, прикладного, вокального, хореографического и театрального творчества. В Доме культуры проводятся игровые и<span> </span>развлекательные программы, театрализованные представления и праздники, концерты, вечера отдыха. </span></p><p><span></span><span><span>Лесковски</span>й дом культуры является площадкой для проведения районных и областных мероприятий и сходов.</span></p>', NULL, 'nick.anosov2016@yandex.ru', '[{"value": "79657450180", "comment": ""}, {"value": "78172770160", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/78e6b9ea03629bcf43ae8368abab87e5.jpg", "title": "yT-H-krsXes.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «КДО «Сосновское»', 'Вологодский район', 'Europe/Moscow', 'ул Молодежная,д 3', NULL, 'обл Вологодская,р-н Вологодский,п Сосновка,ул Молодежная,д 3', NULL, 3507313790, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 13824, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 178, "name": "Бесплатно", "sysName": "besplatno"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "20:00:00", "from": "16:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 36432, '[{"url":"https://www.culture.ru/institutes/70810/leskovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/98107pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2018-10-26 12:32:29+03', '2023-03-30 11:19:52+03', '0101000020E6100000DCD9571EA4D143401EA5129ED0994D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Сосновский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Молодежная,д 3', NULL, 'обл Вологодская,р-н Вологодский,п Сосновка,ул Молодежная,д 3', '{"type": "Point", "coordinates": [39.57370083397676, 59.19665774639815]}', '<p><span>Свои двери для жителей поселка Сосновка Дом культуры открыл в ноябре 1972 года. Общая площадь – 825 кв. м, зрительный зал рассчитан на 150 мест. В зоне обслуживания проживает более 2 500 человек.</span></p><p><span></span><span> Коллектив Дома культуры активно сотрудничает со школой, детским садом, библиотекой и учреждением спорта. </span><span>Дом культуры является источником развития и поддержки культурно-социальных инициатив населения, развития творческих способностей и организации активного отдыха. </span></p><p><span></span><span>На базе учреждения культуры работают 25 клубных объединений, из них 12 для детей.<span> </span></span>В клубных формированиях занимается более 300 человек. Для детей и взрослых действуют кружки изобразительного искусства, прикладного, вокального, хореографического и театрального творчества. В Доме культуры проводятся игровые и развлекательные программы, театрализованные представления и праздники, концерты, вечера отдыха.</p>', NULL, 'sosnovskoekdo@yandex.ru', '[{"value": "79657450180"}, {"value": "78172775837"}]', '{"url": "https://all.culture.ru/uploads/eb4ab35f1b9e1a51b87035b7dde193c2.jpg", "title": "e_S0BPpBoCU.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «КДО «Сосновское»', 'Вологодский район', 'Europe/Moscow', 'ул Молодежная,д 3', NULL, 'обл Вологодская,р-н Вологодский,п Сосновка,ул Молодежная,д 3', NULL, 3507313790, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 13824, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 36298, '[{"url":"https://www.culture.ru/institutes/70815/sosnovskii-dom-kultury","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2018-10-24 11:16:57+03', '2023-03-30 15:54:25+03', '0101000020E61000001ECF67076FC943407FA4BE142C994D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Межпоселенческий центр традиционной народной культуры', 'Череповецкий район', 'Europe/Moscow', 'ул Советская,д 31', 'маршр. такси «Череповец – Воскресенское» от автовокзала г. Череповца', 'обл Вологодская,р-н Череповецкий,с/мо Воскресенское сельское поселение,с Воскресенское,ул Советская,д 31', '{"type": "Point", "coordinates": [37.925235813907044, 59.43185416681388]}', '<p>В 1990 году в с. Воскресенское был создан Центр традиционной народной культуры <span>– первое учреждение культуры Вологодской области, нацеленное на комплексное, глубокое изучение народных традиций региона. </span><span> </span></p><p>Сотрудники занимаются формированием фольклорно-этнографического фонда, созданием копий экспедиционного материала, подготовкой методических пособий (в том числе видеофильмов и аудиоподборок), изданием научных сборников, проведением мастер-классов, воспитанием подрастающего поколения, популяризацией традиционной народной культуры, реконструкцией технологий народных ремесел и форм народного прикладного искусства, восстановлением местных праздников.</p><p>Детская фольклорно-этнографическая студия центра – это второй дом для многих ребятишек с. Воскресенское. Каждый может найти себе занятие по душе: поиграть в старинные игры на еженедельных вечерках; развить артистические способности, разыгрывая представления театров «Петрушка» и «Вертеп»; попробовать себя в роли экскурсовода; научиться основам исследовательской деятельности.</p><p>Одной из форм работы центра является народная самодеятельная студия «Ерга мастеровая». В студию приходят заниматься учащиеся Воскресенской школы. Благодаря комплексному подходу участники мастерской имеют возможность изучать традиционные ремесла западного региона Вологодской области (ткачество, вышивка, плетение, шитье, традиционная игрушка), а затем осваивать и повышать свое мастерство, изготавливая изделия.<br /></p>', 'http://ctnk-yorga.ru', 'voskresenskoe-mctnk@yandex.ru', '[{"value": "79217333863", "comment": ""}, {"value": "79517383978", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/a08f5556ff0a95630f33620176a13af2.jpg", "title": "am7hX0hu9do.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МУК «Межпоселенческий центр традиционной народной культуры» Череповецкого МР', 'Череповецкий район', 'Europe/Moscow', 'ул Советская,д 31', NULL, 'обл Вологодская,р-н Череповецкий,с/мо Воскресенское сельское поселение,с Воскресенское,ул Советская,д 31', NULL, 3523014483, 'mincult', 'Череповецкий район', 'Europe/Moscow', NULL, 20333, '[{"id": 321, "name": "Традиции", "sysName": "tradicii"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35178, '[{"url":"https://www.culture.ru/institutes/36174/mezhposelencheskii-centr-tradicionnoi-narodnoi-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/19213pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2018-06-06 18:09:30+03', '2023-03-28 09:58:39+03', '0101000020E6100000CBE88C206EF64240B08D51FF46B74D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Шулмский дом культуры', 'Череповецкий район', 'Europe/Moscow', 'ул Центральная,д 15', NULL, 'обл Вологодская,р-н Череповецкий,д Шулма,ул Центральная,д 15', '{"type": "Point", "coordinates": [37.547719221822845, 59.20595000772279]}', '<p>В октябре 1983 г. было построено здание Дома культуры д. Шулма. Торжественное открытие состоялось 23 февраля 1984г.<br /> Сейчас Дом культуры – это современный, красивый концертный зал, в котором проходят концерты, конкурсы и мероприятия, как местного, так и районного значения. <br />Современное оборудование позволяет принимать артистов разного уровня. Дом культуры с радостью встречает гостей. <br />Здание Дома культуры очень большое, также в нем размещается просторный, красивый и уютный банкетный зал.<br />В Дом культуры с радостью приходят заниматься, как дети, так и взрослые. Все кружки самодеятельных коллективов проводят квалифицированные специалисты, которые ежегодно повышают свою квалификацию на семинарах в областном центре. <br />Здесь можно найти занятие по душе – декоративно-прикладное искусство, танцы, вокал, театральное искусство.<br /><br /></p>', 'https://nelazskoe-sko.vlg.muzkult.ru/about', 'nelaskoesko@mail.ru', '[{"value": "78202669642", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/8a8057071657dc935aa8d51ee68f56ce.jpg", "title": "5xyK9V-jju4.jpg"}', '[{"url": "https://all.culture.ru/uploads/172009cfba2b27680224f2db61c1bfb7.jpeg", "title": "TT3aqPj7n_I.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МУК «Нелазское СКО»', 'Череповецкий район', 'Europe/Moscow', 'ул Центральная,д 15', NULL, 'обл Вологодская,р-н Череповецкий,с/мо Нелазское сельское поселение,д Шулма,ул Центральная,д 15', NULL, 3523014606, 'mincult', 'Череповецкий район', 'Europe/Moscow', NULL, 20385, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 177, "name": "Танцы", "sysName": "tancy"}, {"id": 191, "name": "Творчество", "sysName": "tvorchestvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 34935, '[{"url":"https://www.culture.ru/institutes/75905/shulmskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/73460pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2018-05-15 14:47:20+03', '2023-03-28 10:02:48+03', '0101000020E6100000528FD8A91BC64240E2E3E1915C9A4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Можайский дом культуры', 'Вологодский район', 'Europe/Moscow', 'д 5А', NULL, 'обл Вологодская,р-н Вологодский,п Можайское,д 5А', '{"type": "Point", "coordinates": [39.79447524917756, 59.1251265422345]}', '<p>Можайский дом культуры начал свою деятельность в 1980 году. Площадь з<span>дания – 1 379 кв. м. </span></p><p><span></span><span>На базе Дома культуры ведут деятельность 25 клубных объединений разных направлений и клубы по интересам.</span><span> Работает студия рисования песком «Ладошки», арт-студия «ТриЧетыре», развивающий кружок «Разговорчики». Занятия этих кружков ведет И. М. Шибаева.</span></p> <p><span></span><span>А. В. Шабанова – руководитель студии английского языка Welcome, вокальных студий «ФаСоль» и «Хорошие девчата». Д</span><span>ействуют группы «Зумбакидс», «Золотая молодежь», пилатеса. Руководитель – сертифицированный инструктор </span><span>LDFA</span><span> Н. А. </span><span>Лугова. </span><span>Также ведут работу «Морошка», </span>«Россиянка», «Капучино», «Лето», «Сударушка». <span>С огромным удовольствием дети ходят на занятия театральной студии «Сияние» (руководитель – Т. В. Катканова). </span></p> <p><span></span><span>Еженедельно проводятся занятия с логопедом и психологом (для людей любого возраста), занятия по подготовке детей к школе, по робототехнике. </span><span>Организуются тематические (образовательные, спортивные и другие) часы, выездные мастер-классы, фотосессии для населения.</span></p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/955166880e982271fa9e2e80ce094089.jpg", "title": "T333W1fijcA.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры Вологодского муниципального района «Центр культурного развития»', 'Вологодский район', 'Europe/Moscow', 'ул Ленина,д 50', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Ленина,д 50', NULL, 3525221703, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 26358, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "20:00:00", "from": "13:00:00"}', '{"to": "20:00:00", "from": "13:00:00"}', '{"to": "20:00:00", "from": "13:00:00"}', '{"to": "20:00:00", "from": "13:00:00"}', '{"to": "20:00:00", "from": "13:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 51286, '[{"url":"https://www.culture.ru/institutes/76414/mozhaiskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/98404pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2021-04-14 14:51:26+03', '2023-05-16 11:51:55+03', '0101000020E61000007B596E5DB1E543401E61832504904D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Дом традиций и ремесел «Морошка»', 'Тотьма', 'Europe/Moscow', 'ул Володарского,д 7', NULL, 'обл Вологодская,р-н Тотемский,г Тотьма,ул Володарского,д 7', '{"type": "Point", "coordinates": [42.764605, 59.970754]}', '<p>Дом традиций и ремесел «Морошка» открылся в августе 2021 года в рамках реализации проекта «Соль – в традициях!», поддержанного Фондом президентских грантов. Здесь проходят интерактивные и познавательные программы по народной культуре, традиционные праздники народного календаря, ремесленные, гастрономические мастер-классы, творческие встречи и др. </p><p>На базе Дома традиций и ремесел «Морошка» занимаются вокальные коллективы, детский фольклорный клуб «Потешка», работает народный самодеятельный коллектив декоративно-прикладного и изобразительного искусства клуб «Тотьма», клуб вологодского кружевоплетения «Плетея». Изюминкой Дома традиций является лавка ремесленников, где представлены изделия ручной работы более 70 мастеров и мастериц Тотемского округа.<br /></p><p>Дом традиций и ремесел «Морошка» – организатор ежегодного межокружного фестиваля народного творчества «Тотемский лапоть», участник городских и окружных мероприятий. Относится к объектам туристского показа. </p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/f677b3b840aa22b357ac48957518fb00.jpg", "title": "500HcgBQ_sc.jpg"}', '[{"url": "https://all.culture.ru/uploads/ca9173da575b0b86beeebc8bfbe727fe.jpg", "title": "5iU2B8CAT8c.jpg"}, {"url": "https://all.culture.ru/uploads/5c242441f59d96171c4250f32054d58d.jpg", "title": "OfM-pKqEJqQ.jpg"}]', NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Центр развития культуры «Тотьма»', 'Тотемский район', 'Europe/Moscow', 'Вологодская,11', NULL, 'обл Вологодская,р-н Тотемский,д Варницы,Вологодская,11', NULL, 3518003616, 'mincult', 'Тотемский район', 'Europe/Moscow', NULL, 25908, NULL, NULL, NULL, '{"to": "20:00:00", "from": "08:30:00"}', '{"to": "20:00:00", "from": "08:30:00"}', '{"to": "20:00:00", "from": "08:30:00"}', '{"to": "20:00:00", "from": "08:30:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 79999, NULL, NULL, NULL, NULL, NULL, '2023-06-21 11:54:17+03', '2023-06-22 11:25:48+03', '0101000020E6100000D6AD9E93DE614540083BC5AA41FC4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Явенгский сельский дом культуры', 'Вожегодский район', 'Europe/Moscow', 'ул Советская,д 12а', NULL, 'обл Вологодская,р-н Вожегодский,п База,ул Советская,д 12а', '{"type": "Point", "coordinates": [40.150309, 60.605379]}', '<p>Явенгский сельский дом культуры был построен в рамках национального проекта «Культура» и сдан в эксплуатацию 24 декабря 2020 года. В общей сложности он обслуживает около 1000 человек. В деятельности Дома культуры основным направлением является сохранение традиций местности, развитие народного исполнительства фольклорной и авторской песни. Большое внимание уделяется духовности, воспитанию патриотизма, сохранению исторической памяти. </p><p>В Доме культуры организована работа 26 кружковых объединений различного направления для детей, молодежи и взрослого населения, в которых занимается более 200 человек. Наиболее стабильно работают вокальные группы «Рябинушки», «Сударушка», «Девчата», имеющие большой опыт и стаж. Молодежные коллективы имеют свою специфику – танцевальное и театральное направления. Дети занимаются в кружках сольного пения, танцевальном кружке, клубе «Игровичок».</p>', NULL, 'ksk-1-61@mail.ru', '[{"value": "79218263757", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/02accf92f228f00af532d7020c2a7758.jpg", "title": "20210104_110938.jpg"}', '[{"url": "https://all.culture.ru/uploads/9229e8ea3bbc2b0aaaedb09db5991d28.jpg", "title": "20220718_160029.jpg"}, {"url": "https://all.culture.ru/uploads/4eae137d71440115b41da64eba13e5ab.jpg", "title": "20220718_180854.jpg"}, {"url": "https://all.culture.ru/uploads/fc26a959e75c07cb2b0ccf16431d406a.jpg", "title": "20220723_130700.jpg"}, {"url": "https://all.culture.ru/uploads/133b4b459211daf59d8ac2e3a719e6ec.jpg", "title": "1640526732049.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУ КСК Явенгское', 'Вожегодский район', 'Europe/Moscow', 'д 67', NULL, 'обл Вологодская,р-н Вожегодский,с Покровское,д 67', NULL, 3506005023, 'mincult', 'Вожегодский район', 'Europe/Moscow', NULL, 20173, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "22:00:00", "from": "13:00:00"}', '{"to": "19:00:00", "from": "13:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 72981, '[{"url":"https://www.culture.ru/institutes/85849/yavengskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vozhega/dvorcy-kultury-i-kluby/86576pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-11-18 23:06:00+03', '2023-06-21 11:00:01+03', '0101000020E6100000B1A547533D134440B4571F0F7D4D4E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Тимановский сельский дом культуры', 'Бабушкинский район', 'Europe/Moscow', 'д 3', NULL, 'обл Вологодская,р-н Бабушкинский,д Тиманова Гора,д 3', '{"type": "Point", "coordinates": [43.701601, 59.939627]}', '<p>Здание расположено на территории Тимановского сельского поселения. В 2020 году был проведен ремонт по программе губернатора «Сельский дом культуры».</p><p>Коллективы учреждения принимают активное участие не только в жизни своего клуба, но и посещают районные фестивали, такие как «Родники российских деревень», «Костры Леденьги», фестиваль танца «Свой стиль», фестиваль «Белый гриб» и другие.</p><p>Филиал посещают гости из области по программе губернатора «Культурный экспресс». Каждый год ДК становится площадкой районного спортивного соревнования «Тимановские игрища».</p><p>Ежегодно проводится мероприятие районного уровня, приуроченное ко Дню вывода советских войск из Афганистана (15 февраля). В учреждении собираются все воины-интернационалисты Бабушкинского района. Проводится торжественный митинг на могиле И. П. Филиппова.</p><p>Ежегодно работники совместно с участниками клубных формирований организуют День деревни Тиманова Гора и праздник Троицы в деревне Пожарище.</p>', NULL, 'timanovsdk@mail.ru', '[{"value": "78174534207", "comment": "Заведующий"}]', '{"url": "https://all.culture.ru/uploads/bb602adbeda8bd6b58c8625a8260bf51.jpg", "title": "iylG1oKdH10.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Центральный Дом культуры» Бабушкинского муниципального округа', 'Бабушкинский район', 'Europe/Moscow', 'ул. Бабушкина,63', NULL, 'обл Вологодская,р-н Бабушкинский,с им Бабушкина,ул. Бабушкина,63', NULL, 3502005590, 'mincult', 'Бабушкинский район', 'Europe/Moscow', NULL, 26248, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "16:00:00", "from": "12:00:00"}', '{"to": "16:00:00", "from": "12:00:00"}', '{"to": "16:00:00", "from": "12:00:00"}', '{"to": "16:00:00", "from": "12:00:00"}', '{"to": "16:00:00", "from": "12:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 72843, '[{"url":"https://www.culture.ru/institutes/85964/timanovskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/imeni-babushkina/dvorcy-kultury-i-kluby/86696pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-11-17 11:10:52+03', '2023-06-21 18:01:06+03', '0101000020E6100000A2EBC20FCED9454024B891B245F84D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Скоковский сельский дом культуры', 'Бабушкинский район', 'Europe/Moscow', 'д 1', NULL, 'обл Вологодская,р-н Бабушкинский,д Скоково,д 1', '{"type": "Point", "coordinates": [44.520514, 59.857924]}', '<p>Скоковский сельский дом культуры расположен на территории поселения Подболотное и р<span>азмещается в деревянном здании, которому более 100 лет. В нем имеется комната старины, танцевальный зал, зрительный зал (вместимость – 70 посадочных мест), комната для занятий кружковой деятельностью.</span></p><p><span>Сотрудники проводят для населения различные мероприятия: праздники, мастер-классы, посиделки. </span><span>Ежегодно организуются спортивные мероприятия как для молодежи, так и для взрослого населения. Гостеприимство и радушие коллектива всегда по достоинству оценивают гости Подболотной земли. </span></p><p><span>На территории разработан туристический маршрут Северных Увалов. Этому способствует уникальная местность, ее красота и своеобразие. Маршрут позволяет</span><span> познакомиться с великолепными памятниками природы – Исаковой горой, Селенской горой, карстовыми разломами, Северными Увалами. Геологический памятник природы «Исакова гора» был создан в 1989 году. Вершина холма – слабовыпуклая, неправильной формы. Абсолютная высота Исаковой горы – 293 м. Она расположена на территории поселения – между деревнями Исаково и Пестериха, в двух километрах к югу от деревень Муравьево, Подболотье, юго-восточнее деревни Кокшарка.</span></p>', NULL, 'konevaninel@yandex.ru', '[{"value": "78174532609", "comment": "Заведующий"}]', '{"url": "https://all.culture.ru/uploads/a3a667f7b173e6eb39022c3c38eabc6e.jpg", "title": "O5Rj6wGYqLU.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Центральный Дом культуры» Бабушкинского муниципального округа', 'Бабушкинский район', 'Europe/Moscow', 'ул. Бабушкина,63', NULL, 'обл Вологодская,р-н Бабушкинский,с им Бабушкина,ул. Бабушкина,63', NULL, 3502005590, 'mincult', 'Бабушкинский район', 'Europe/Moscow', NULL, 26248, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "22:00:00", "from": "19:00:00"}', '{"to": "14:00:00", "from": "12:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 72396, '[{"url":"https://staging-718506.culture.ru/institutes/85520/skokovskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/imeni-babushkina/dvorcy-kultury-i-kluby/86020pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-11-11 00:02:50+03', '2023-06-15 15:53:01+03', '0101000020E6100000198EE733A04246400C3A2174D0ED4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Нюксенский центр традиционной народной культуры', 'Нюксенский район', 'Europe/Moscow', 'ул Культуры,стр 26', NULL, 'обл Вологодская,р-н Нюксенский,с Нюксеница,ул Культуры,стр 26', '{"type": "Point", "coordinates": [44.244839, 60.416264]}', '<p>Центр традиционной народной культуры в селе Нюксеница Вологодской области создан в 1991 году. </p> <p>Сегодня центр ведет деятельность различных видов: научно-исследовательскую (экспедиции, работа в музеях), координационно-методическую (семинары), опытно-экспериментальную (восстановление праздников и обрядов), просветительскую (работа творческих формирований на базе ЦТНК, издательская и концертная деятельность). </p> <p>ЦНТК является автором различных творческих проектов, осуществленных в разные годы. Они направлены на популяризацию ценностей традиционной народной культуры. Это областные и районные фольклорные фестивали и праздники: «Традиционный костюм через века», «Нюкша – белая лебедь», «Покровская братчина», «Семейный уклад», «Родничок», «Завивайся, плетешок»; круглогодичные календарные и деревенские праздники: Святки, Крещение, Масленица, Пасха, Троица, Покров, Кузьминки. </p> <p>Специалисты центра владеют такими видами народного творчества, как гончарное дело, ткачество, лоскутное шитье, вышивка, роспись по дереву, плетение из бересты и лозы, традиционная кухня, традиционная игрушка. Значимым направлением работы учреждения является освоение песенных, хореографических и инструментальных традиций края. </p> <p>Общее количество участников 17 творческих объединений, действующих на базе Нюксенского ЦТНК, – 354 человека. Они охватывают все возрастные категории населения.</p> <p>Центр ежегодно привлекает около 12 тыс. человек для участия в интерактивных программах и экскурсиях.</p>', 'http://nuksctnk.ru', 'nuks.ctnk@mail.ru', '[{"value": "78174729159", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/828296e4f1d3c50ee73ed5c50e175bb1.JPG", "title": "1 здание.JPG"}', '[{"url": "https://all.culture.ru/uploads/b0152f981850357d0740b4efb0b6e6e6.jpg", "title": "g16_QChrel4.jpg"}, {"url": "https://all.culture.ru/uploads/31d02c32761f06d27e76e853828750c7.jpg", "title": "D5kZwSbwzJ8.jpg"}, {"url": "https://all.culture.ru/uploads/69665affb01a38ac140e8d8f78856d81.jpg", "title": "d08RN2gfN30.jpg"}, {"url": "https://all.culture.ru/uploads/f0acf777d0b2b897b446a78df2e47238.jpg", "title": "QzD9yxl1JiE.jpg"}, {"url": "https://all.culture.ru/uploads/397d6fe18845bb60959d6a758a6beabd.jpg", "title": "KlPa6siOHbc.jpg"}, {"url": "https://all.culture.ru/uploads/b8fe13165de12b686cb2ac5a0d46b898.jpg", "title": "ueac4f8ybq8.jpg"}, {"url": "https://all.culture.ru/uploads/f31ae83c468cf663d29abff7884d59c2.jpg", "title": "gZwC3oLHM2s.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУК «Нюксенский районный ЦТНК»', 'Нюксенский район', 'Europe/Moscow', 'ул Культуры,26', NULL, 'обл Вологодская,р-н Нюксенский,с Нюксеница,ул Культуры,26', NULL, 3515003174, 'mincult', 'Нюксенский район', 'Europe/Moscow', NULL, 28979, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 321, "name": "Традиции", "sysName": "tradicii"}, {"id": 324, "name": "Традиционное искусство", "sysName": "tradicionnoe-iskusstvo"}, {"id": 350, "name": "Народная культура", "sysName": "narodnaya-kultura"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', '{"to": "17:15:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 72011, '[{"url":"https://www.culture.ru/institutes/85126/nyuksenskii-centr-tradicionnoi-narodnoi-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/nyuksenica/dvorcy-kultury-i-kluby/85234pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-10-31 15:28:38+03', '2023-06-05 14:57:25+03', '0101000020E610000086E464E2561F46404640852348354E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Советский сельский клуб', 'Тотемский район', 'Europe/Moscow', 'ул Октябрьская,д 6', NULL, 'обл Вологодская,р-н Тотемский,п Советский,ул Октябрьская,д 6', '{"type": "Point", "coordinates": [42.71773, 59.921421]}', '<p>Год основания Советского сельского клуба – 1967-й. В настоящее время это филиал Центра развития культуры «Тотьма». </p><p>В филиале занимаются 29 клубных формирований разных направлений: патриотическое воспитание, сохранение народных традиций, спорт, танцы, театр, вокал. Их посещают 715 человек разных возрастных категорий. </p><p>Советский клуб – единственный филиал, где есть инклюзивные формирования: танцевальный коллектив и театральная студия «Будоражка». Для детей с ОВЗ работает программа «Радуга». Занимаются 45 детей. </p><p>Ежегодно в филиале проводятся отчетные концерты танцевальных, вокальных и театральных коллективов. Творческие коллективы регулярно принимают участие в организации и проведении выездных концертов в других филиалах Центра развития культуры.</p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/4a2048f4b7687412e02a747fb09bbcfb.jpg", "title": "l5wAhewwS0M.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Центр развития культуры «Тотьма»', 'Тотемский район', 'Europe/Moscow', 'Вологодская,11', NULL, 'обл Вологодская,р-н Тотемский,д Варницы,Вологодская,11', NULL, 3518003616, 'mincult', 'Тотемский район', 'Europe/Moscow', NULL, 25908, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 80065, '[{"url":"https://www.culture.ru/institutes/93050/sovetskii-selskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/totma/dvorcy-kultury-i-kluby/102363pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2023-06-29 10:45:29+03', '2023-06-29 11:00:05+03', '0101000020E6100000D6AD9E93DE5B45407F6C921FF1F54D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Никольский дом культуры', 'Тотемский район', 'Europe/Moscow', 'ул Н.Рубцова,д 30', NULL, 'обл Вологодская,р-н Тотемский,с Никольское,ул Н.Рубцова,д 30', '{"type": "Point", "coordinates": [42.531025, 59.488789]}', '<p> Никольский дом культуры является одним из центров культуры и досуга населения села. Расположен в типовом здании 1972 года постройки. В 2021–2022 годах по программам губернатора «Сельский дом культуры» и «Местный дом культуры» произведен капитальный ремонт здания и приобретено новое оборудование.</p><p>Село Никольское славится тем, что в нем жил и творил русский поэт Николай Михайлович Рубцов. Поэтому сюда часто приезжают поэты и писатели, вокальные коллективы, исполняющие песни на его стихи. Местом, где проходили и проходят встречи гостей с сельчанами, стал именно Дом культуры. Мероприятия, посвященные творчеству Николая Рубцова, такие как «Рубцовские чтения», «Рубцовский костер на Толшме», «Рубцовская осень», стали для села традиционными и собирают почитателей творчества поэта со всей России.</p><p> В настоящее время при Доме культуры осуществляют свою деятельность 16 клубных формирований разной направленности, в которых занимаются 116 участников. <br /></p>', NULL, NULL, NULL, '{"url": "https://all.culture.ru/uploads/f2599697f37585472858bd5f137ec70b.jpg", "title": "DiYmy8jmAyc.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Центр развития культуры «Тотьма»', 'Тотемский район', 'Europe/Moscow', 'Вологодская,11', NULL, 'обл Вологодская,р-н Тотемский,д Варницы,Вологодская,11', NULL, 3518003616, 'mincult', 'Тотемский район', 'Europe/Moscow', NULL, 25908, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "17:00:00", "from": "11:00:00"}', '{"to": "17:00:00", "from": "11:00:00"}', '{"to": "17:00:00", "from": "11:00:00"}', '{"to": "17:00:00", "from": "11:00:00"}', '{"to": "17:00:00", "from": "11:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 80030, '[{"url":"https://www.culture.ru/institutes/93042/nikolskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/totma/dvorcy-kultury-i-kluby/102271pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2023-06-26 11:26:26+03', '2023-06-26 13:34:06+03', '0101000020E6100000E02D90A0F843454080D250A390BE4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Зайчиковский сельский дом культуры', 'Бабушкинский район', 'Europe/Moscow', 'ул Школьная,д 15а', NULL, 'обл Вологодская,р-н Бабушкинский,п Зайчики,ул Школьная,д 15а', '{"type": "Point", "coordinates": [44.123603, 59.599276]}', '<p>Здание Зайчиковского сельского дома культуры было открыто в 1979 году. В 2021 году был проведен ремонт по программе губернатора «Сельский дом культуры».</p><p>Основными видами деятельности являются создание и организация работы кружков, любительских объединений, клубов по интересам различной направленности. Подготовка и проведение концертных программ, тематических вечеров, фольклорных посиделок.<br /></p><p>На базе филиала созданы следующие клубные формирования:</p><ul><li>клуб ветеранов «Добрые соседи»;</li><li>вокальный коллектив «Рябинушка»; </li><li>танцевальный коллектив «Товарочки» (ветераны); </li><li>творческий клуб для ветеранов «Посиделки»;</li><li> детский танцевальный коллектив «Солнышко»;</li><li>творческий коллектив «Мозаика»; </li><li>спортивный кружок «Здоровячок» для детей и «Жить здорово» для ветеранов; </li><li>юношеский клуб «Юность»; </li><li>семейный клуб выходного дня «Отдыхай-ка».</li></ul><p>Коллективы дома культуры принимают участие в районных фестивалях, таких как «Родники российских деревень», «Костры «Леденьги» и другие. Кроме того, филиал участвует в программе губернатора «Культурный экспресс».</p>', NULL, 'clubz35@yandex.ru', '[{"value": "79814454220", "comment": "Заведующий"}]', '{"url": "https://all.culture.ru/uploads/4a2add021c71222e0a0304acb68d7f22.jpg", "title": "xLEt7NWqK2k.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Центральный Дом культуры» Бабушкинского муниципального округа', 'Бабушкинский район', 'Europe/Moscow', 'ул. Бабушкина,63', NULL, 'обл Вологодская,р-н Бабушкинский,с им Бабушкина,ул. Бабушкина,63', NULL, 3502005590, 'mincult', 'Бабушкинский район', 'Europe/Moscow', NULL, 26248, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, NULL, '{"to": "16:00:00", "from": "11:00:00"}', '{"to": "16:00:00", "from": "11:00:00"}', '{"to": "16:00:00", "from": "11:00:00"}', '{"to": "16:00:00", "from": "11:00:00"}', '{"to": "21:00:00", "from": "18:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 73512, '[{"url":"https://www.culture.ru/institutes/86620/zaichikovskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/imeni-babushkina/dvorcy-kultury-i-kluby/87922pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-11-29 15:13:23+03', '2023-07-13 14:36:36+03', '0101000020E610000000581D39D20F46408CA37213B5CC4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Миньковский сельский дом культуры', 'Бабушкинский район', 'Europe/Moscow', 'ул Школьная,д 13', NULL, 'обл Вологодская,р-н Бабушкинский,с Миньково,ул Школьная,д 13', '{"type": "Point", "coordinates": [43.4864666659359, 59.698941644293676]}', '<p>Дом культуры расположен в самом центре села, что является удобным при проведении всех мероприятий. В филиале проведен ремонт по программе «Национальные проекты России». В 2022 году Дому культуры исполнилось 35 лет. В нем работает слаженный творческий коллектив.<span><br /></span></p><p><span>В филиале действуют 13 клубных формирований, в них занимается 197 человек. </span><span> Творческие коллективы являются постоянными участниками мероприятий и любимцами публики. Кроме того, они с удовольствием выезжают с концертными программами в малонаселенные пункты района.</span></p><p><span> Ежегодно Дом культуры принимает участие в районных фестивалях и конкурсах: «Родники российских деревень», «Свой стиль», «Костры Леденьги», фестиваль «Белого гриба» и т. д. </span><span> Изюминкой филиала являются его музеи: музей старины и музей СССР. Они пользуются большой популярностью не только у местных жителей, но и у гостей районного центра.</span></p><p><span> Во время пандемии работники Дома культуры создали 2 проекта: «Былое» и «Нюра и Матрена». Оба получили большую популярность. В настоящее время видеоролики про Нюру и Матрену известны не только в Вологодской области – проект вышел на всероссийский уровень, став победителем среди блогеров России.</span></p>', NULL, NULL, '[{"value": "79212350547", "comment": "Заведующий"}]', '{"url": "https://all.culture.ru/uploads/c43bebe30f69bbd985e7085afd0b1d0a.jpg", "title": "7UG2BfJDoVk.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Центральный Дом культуры» Бабушкинского муниципального округа', 'Бабушкинский район', 'Europe/Moscow', 'ул. Бабушкина,63', NULL, 'обл Вологодская,р-н Бабушкинский,с им Бабушкина,ул. Бабушкина,63', NULL, 3502005590, 'mincult', 'Бабушкинский район', 'Europe/Moscow', NULL, 26248, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 72835, '[{"url":"https://www.culture.ru/institutes/85948/minkovskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/imeni-babushkina/dvorcy-kultury-i-kluby/88760pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2022-11-17 10:36:03+03', '2023-07-27 09:40:49+03', '0101000020E6100000F9642A8A44BE4540E30678EB76D94D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Домозеровский сельский дом культуры', 'Череповецкий район', 'Europe/Moscow', 'д 30', NULL, 'обл Вологодская,р-н Череповецкий,д Новое Домозерово,д 30', '{"type": "Point", "coordinates": [38.137167, 59.043811]}', '<p>Домозеровский сельский дом культуры создан в 2010 году. Первым директором была Антонина Георгиевна Федорова. Изначально Дом культуры находился в деревне Бурцево, затем в помещении детского сада. И наконец, на сегодняшний день уже долгое время существует в нынешнем здании. </p><p>Некоторые коллективы с тех времен существуют и по сей день, например ансамбль русской песни «Веретенце». Большинство его членов принимали немалое участие в развитии Дома культуры. Работают кружки и секции, множество вокальных, инструментальных и других групп. Взрослые и дети поют, танцуют, рисуют, выжигают, делают поделки своими руками, играют на музыкальных инструментах, пробуют себя в актерском мастерстве, познают много нового.</p><p> Дом культуры проводит концерты, спектакли, развлекательные программы, мастер-классы, онлайн-акции на самые разные праздники: Рождество, 14 Февраля, 23 Февраля, 8 Марта, День защиты детей, День матери и другие. Также он чтит традиции деревни Домозерово и соседних сел, деревень и поселков, устраивает праздники для жителей других поселений, ездит к ним с концертами и развлекательными программами. </p>', NULL, 'dkdomozer35@yandex.ru', '[{"value": "78202669783", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/07eb5371247839d0d541f9cee41da525.jpg", "title": "FQrqiZp7yrE3.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МУК «Югское социально-культурное спортивное объединение»', 'Череповецкий район', 'Europe/Moscow', 'д 30', NULL, 'обл Вологодская,р-н Череповецкий,д Новое Домозерово,д 30', NULL, 3523017759, 'mincult', 'Череповецкий район', 'Europe/Moscow', '[{"network":"vk","name":"Дом Культуры Домозёрово","networkId":"108634251","updateDate":"2022-12-28T08:24:13Z","createDate":"2022-12-28T08:24:13Z","accountId":44500,"postingGroupId":38741},{"network":"vk","name":"Мусорский клуб","networkId":"40840413","updateDate":"2022-12-28T08:24:26Z","createDate":"2022-12-28T08:24:26Z","accountId":44500,"postingGroupId":38742}]', 20555, '[{"id": 25, "name": "Классическое искусство", "sysName": "klassicheskoe-iskusstvo"}, {"id": 26, "name": "Современное искусство", "sysName": "sovremennoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35992, '[{"url":"https://www.culture.ru/institutes/55243/domozerovskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/89523pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2018-10-04 13:47:34+03', '2023-08-22 11:22:39+03', '0101000020E6100000938B31B08E1143403F1A4E999B854D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Талицкая картинная галерея', 'Кирилловский район', 'Europe/Moscow', 'ул Юбилейная,д 9', NULL, 'обл Вологодская,р-н Кирилловский,с Талицы,ул Юбилейная,д 9', '{"type": "Point", "coordinates": [38.806466, 59.647938]}', '<p> Первая и единственная в области сельская картинная галерея открылась в 2000 году в Талицах, в здании бывшего детского сада. Ее создателем выступил Юрий Белков – ветеран Великой Отечественной войны, заслуженный художник РФ, уроженец Талицкого сельсовета. Он старался каждый год приезжать в Талицы из Йошкар-Олы. Художник не только вез картины с собой, но и работал на родной земле.</p><p>На протяжении более чем 20 лет галерея является для жителей Талиц настоящей гордостью. Здесь находятся выставочные залы и кабинеты, где проводятся занятия с детьми по обучению художественному мастерству. В картинной галерее создана постоянная экспозиция с полотнами Юрия Белкова, а также выставки местных самодеятельных мастеров. </p>', NULL, NULL, '[{"value": "79114436637", "comment": "Татьяна"}]', '{"url": "https://all.culture.ru/uploads/269880e9757d8881d4564fdeb3d53d54.jpg", "title": "PofiX4ex8Co.jpg"}', '[{"url": "https://all.culture.ru/uploads/d5b696dfd8533846079e25c8b6e6cf9a.jpg", "title": "w0-Pgj6mURU.jpg"}, {"url": "https://all.culture.ru/uploads/c78aaca847ad04ce89b6ded15326e746.jpg", "title": "uQK3zil0qWE.jpg"}]', NULL, 'Дворцы культуры и клубы', 'АУК КМР «ЦКР»', 'Кирилловский район', 'Europe/Moscow', 'ул Гагарина,д 98', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,ул Гагарина,д 98', NULL, 3511006791, 'mincult', 'Кирилловский район', 'Europe/Moscow', '[{"network":"vk","name":"Центр культурного развития","networkId":"17831631","updateDate":"2018-05-29T07:22:36Z","createDate":"2018-05-29T07:22:36Z","accountId":21387,"postingGroupId":18946}]', 20401, '[{"id": 21, "name": "Выставочные залы", "sysName": "vystavochnye-zaly"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 80530, '[{"url":"https://www.culture.ru/institutes/93501/talickaya-kartinnaya-galereya","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-08-15 15:03:35+03', '2023-10-09 14:20:08+03', '0101000020E610000000AB23473A674340F7EAE3A1EFD24D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Томашевский клуб', 'Великоустюгский район', 'Europe/Moscow', 'д 9', NULL, 'обл Вологодская,р-н Великоустюгский,д Томашево,д 9', '{"type": "Point", "coordinates": [46.815872, 60.505744]}', '<p>В Томашевском клубе проводятся массовые мероприятия – это концерты, праздники, выставки, вечера, посиделки, игровые и спортивные состязания, устные журналы. Учреждение ежегодно принимает участие в смотрах-фестивалях художественной самодеятельности.</p><p> Занятие найдется для всех: и для маленьких, и для больших. Для детей проводятся конкурсные и игровые программы, для молодежи – различные беседы, танцевальные и игровые вечера. На базе Томашевского клуба действуют кружки «Умелые ручки» и «Веселые ребята». Также работает самодеятельный ансамбль под названием «Ивушки» (в составе – девять человек), который выступает на концертах, посещает со своими выступлениями близлежащие деревни.</p>', 'https://кдцву.рф', 'svetaponi07@gmail.com', '[{"value": "79997918932", "comment": "Зорина Любовь Михайловна, начальник Орловского клуба"}, {"value": "78173821660", "comment": "Нечаева Елена Николаевна"}]', '{"url": "https://all.culture.ru/uploads/7f29d7ff7f5480ba21f4b84fabb2a904.jpg", "title": "рг гн.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Великоустюгский культурно-досуговый центр»', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 101', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пр-кт Советский,д 101', NULL, 3526015975, 'mincult', 'Великоустюгский район', 'Europe/Moscow', '[{"network":"vk","name":"\"Кузинский клуб\"","networkId":"170421267","updateDate":"2023-04-05T11:45:45Z","createDate":"2023-04-05T11:45:45Z","accountId":46589,"postingGroupId":41531},{"network":"vk","name":"\"Усть-Алексеевский клуб\"","networkId":"196143083","updateDate":"2023-04-05T13:11:25Z","createDate":"2023-04-05T13:11:25Z","accountId":46589,"postingGroupId":41534},{"network":"vk","name":"«Верхневарженский клуб»","networkId":"219499380","updateDate":"2023-04-05T11:45:28Z","createDate":"2023-04-05T11:45:28Z","accountId":46589,"postingGroupId":41530},{"network":"vk","name":"«Морозовский клуб»","networkId":"219948363","updateDate":"2023-07-05T08:23:07Z","createDate":"2023-07-05T08:23:07Z","accountId":46589,"postingGroupId":42638},{"network":"vk","name":"«Новаторский клуб»","networkId":"217628593","updateDate":"2023-03-17T08:05:55Z","createDate":"2023-03-17T08:05:55Z","accountId":46589,"postingGroupId":41030},{"network":"vk","name":"Анюта Красникова","networkId":"17613040","updateDate":"2023-03-17T10:43:29Z","createDate":"2023-03-17T10:43:29Z","accountId":46594,"postingGroupId":41037},{"network":"vk","name":"БУК \"Юдинский дом культуры\" п. Стрига 6а","networkId":"160210512","updateDate":"2023-04-11T12:03:48Z","createDate":"2023-04-11T12:03:48Z","accountId":46589,"postingGroupId":41660},{"network":"vk","name":"Великоустюгский культурно-досуговый центр","networkId":"117993849","updateDate":"2024-02-15T08:49:55Z","createDate":"2024-02-15T08:49:55Z","accountId":46589,"postingGroupId":44737},{"network":"vk","name":"Обособленное подразделение \"Аристовский клуб\"","networkId":"195948369","updateDate":"2023-03-17T08:06:12Z","createDate":"2023-03-17T08:06:12Z","accountId":46589,"postingGroupId":41031},{"network":"vk","name":"Обособленное подразделение \"Сусоловский клуб\"","networkId":"219106681","updateDate":"2023-04-07T11:43:09Z","createDate":"2023-04-07T11:43:09Z","accountId":46589,"postingGroupId":41581},{"network":"vk","name":"Обособленное подразделение \"Теплогорский клуб\"","networkId":"97047864","updateDate":"2023-04-07T11:43:26Z","createDate":"2023-04-07T11:43:26Z","accountId":46589,"postingGroupId":41582},{"network":"vk","name":"Окультурено молодежью","networkId":"199241624","updateDate":"2023-03-17T10:42:43Z","createDate":"2023-03-17T10:42:43Z","accountId":46594,"postingGroupId":41036},{"network":"vk","name":"Парк культуры и отдыха /Великий Устюг/","networkId":"153198570","updateDate":"2023-04-05T11:46:08Z","createDate":"2023-04-05T11:46:08Z","accountId":46589,"postingGroupId":41532},{"network":"vk","name":"Полдарский клуб","networkId":"206228726","updateDate":"2023-07-05T08:23:33Z","createDate":"2023-07-05T08:23:33Z","accountId":46589,"postingGroupId":42639},{"network":"vk","name":"Театр Деда Мороза","networkId":"199304892","updateDate":"2020-11-03T05:54:59Z","createDate":"2020-11-03T05:54:59Z","accountId":21245,"postingGroupId":30273}]', 20409, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "13:00:00", "from": "10:00:00"}', '{"to": "13:00:00", "from": "10:00:00"}', '{"to": "13:00:00", "from": "10:00:00"}', '{"to": "13:00:00", "from": "10:00:00"}', '{"to": "23:00:00", "from": "20:00:00"}', '{"to": "16:00:00", "from": "13:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 83485, '[{"url":"https://www.culture.ru/institutes/96429/tomashevskii-klub","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2024-03-05 14:29:35+03', '2024-03-06 11:36:06+03', '0101000020E61000006EDC627E6E684740F9122A38BC404E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Мазский сельский клуб', 'Кадуйский район', 'Europe/Moscow', 'ул Центральная,зд 68', NULL, 'обл Вологодская,р-н Кадуйский,д Маза,ул Центральная,зд 68', '{"type": "Point", "coordinates": [36.713355, 59.328558]}', '<p><span>В 1969 году в деревне Маза был открыт Дом культуры. В 2016 году его реорганизовали, он стал филиалом Рукавицкого дома культуры. С 2023 года является филиалом Кадуйского центра культурного развития. </span></p> <p><span>На базе сельского клуба создан вокальный ансамбль «Белые росы», который является участником местных, районных и межрайонных мероприятий. Ведут работу клубные формирования для детей, молодежи и старшего поколения. Действует театральный кружок, клуб «Оберег», мастерская художественного слова.</span></p> <p><span>Ежегодно во второе воскресенье июля работники клуба проводят праздник деревни с концертно-развлекательной программой и общим деревенским застольем. За год в Мазском клубе проходит порядка 300 мероприятий.</span></p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/28d604804cb4070a464f4cbd42e66366.jpg", "title": "маза дк.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУ «Кадуйский ЦКР»', 'Вологодская область', 'Europe/Moscow', 'ул Строителей,д 2', NULL, 'обл Вологодская,рп Кадуй,ул Строителей,д 2', NULL, 3510010837, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"ok","name":"Культура. Кадуй","networkId":"61103236120724","updateDate":"2024-02-16T11:35:59Z","createDate":"2024-02-16T11:35:59Z","accountId":49941,"postingGroupId":44748}]', 36609, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "22:00:00", "from": "18:00:00"}', '{"to": "23:00:00", "from": "19:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 83354, '[{"url":"https://www.culture.ru/institutes/96303/mazskii-selskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kaduy/dvorcy-kultury-i-kluby/110902pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2024-02-27 15:40:17+03', '2024-02-28 08:36:54+03', '0101000020E610000013B875374F5B42406A6B44300EAA4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Рукавицкий сельский дом культуры', 'Кадуйский район', 'Europe/Moscow', 'пер Рабочий,зд 11', NULL, 'обл Вологодская,р-н Кадуйский,д Малая Рукавицкая,пер Рабочий,зд 11', '{"type": "Point", "coordinates": [37.19134, 59.196274]}', '<p> Одноэтажное деревянное здание Дома культуры построено в 1982 году. Благодаря участию в региональных проектах «Сельский Дом культуры» и «Местный Дом культуры» в 2019 году в учреждении проведен капитальный ремонт внутренних помещений и приобретено современное звуковое и световое оборудование. В 2022 году Рукавицкий дом культуры стал одним из победителей областного конкурса на государственную поддержку лучших сельских учреждений культуры.</p><p>В учреждении функционируют 26 творческих объединений для детей и взрослых различных направлений: вокал, хореография, игровое, патриотическое, здоровый образ жизни, рукоделие. Наиболее полюбились зрителям вокальная студия «Семизерье» и вокально-инструментальный ансамбль «Верные друзья». </p><p>Ежегодно Дом культуры проводит более 500 мероприятий, которые посещает порядка 20 000 человек. На базе учреждения реализуется благотворительный проект «Волшебная комната» по прокату нарядной одежды для семей, попавших в трудную жизненную ситуацию.</p>', NULL, 'rukavitskiydomkultury2020@mail.ru', '[]', '{"url": "https://all.culture.ru/uploads/8c8eb723cc90e2e6da84940207184cef.jpg", "title": "рдк.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУ «Кадуйский ЦКР»', 'Вологодская область', 'Europe/Moscow', 'ул Строителей,д 2', NULL, 'обл Вологодская,рп Кадуй,ул Строителей,д 2', NULL, 3510010837, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"ok","name":"Культура. Кадуй","networkId":"61103236120724","updateDate":"2024-02-16T11:35:59Z","createDate":"2024-02-16T11:35:59Z","accountId":49941,"postingGroupId":44748}]', 36609, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "21:00:00", "from": "15:00:00"}', '{"to": "20:00:00", "from": "14:00:00"}', '{"to": "20:00:00", "from": "14:00:00"}', '{"to": "20:00:00", "from": "14:00:00"}', '{"to": "22:00:00", "from": "15:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 83333, '[{"url":"https://afisha7.ru/kaduy/dvorcy-kultury-i-kluby/110844pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/96281/rukavickii-selskii-dom-kultury","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2024-02-26 13:58:41+03', '2024-02-27 09:17:40+03', '0101000020E6100000543541D47D9842400E87A5811F994D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Сосновский сельский клуб', 'Кадуйский район', 'Europe/Moscow', 'ул Центральная,зд 5а', NULL, 'обл Вологодская,р-н Кадуйский,п Сосновка,ул Центральная,зд 5а', '{"type": "Point", "coordinates": [36.497867, 59.582464]}', '<p><span>Здание Сосновского сельского клуба построено в 1955 году. До 2016 года клуб был самостоятельным учреждением, юридическим лицом. Сейчас это филиал Кадуйского центра культурного развития. </span></p> <p><span>Клуб является центром культурной жизни села и его окрестностей. На базе учреждения создан замечательный вокальный ансамбль «Конфетки-бараночки», который по праву является украшением культурной жизни поселка</span><span>. Также работает клуб «Белая королева» для любителей шахмат, клуб «Охота на рыбалку» для рыболовов и охотников, музыкально-инструментальная студия, детское объединение «Детсовет» и спортивная секция «Не отстаем от Шараповой».</span></p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/b778a641eaa67d146d3f87991b27d40e.jpg", "title": "сосновка дк.jpg"}', '[{"url": "https://all.culture.ru/uploads/f6891ed0fddd237226ebb14359d740e6.jpg", "title": "сосновка дк 2.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУ «Кадуйский ЦКР»', 'Вологодская область', 'Europe/Moscow', 'ул Строителей,д 2', NULL, 'обл Вологодская,рп Кадуй,ул Строителей,д 2', NULL, 3510010837, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"ok","name":"Культура. Кадуй","networkId":"61103236120724","updateDate":"2024-02-16T11:35:59Z","createDate":"2024-02-16T11:35:59Z","accountId":49941,"postingGroupId":44748}]', 36609, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 83329, '[{"url":"https://www.culture.ru/institutes/96276/sosnovskii-selskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kaduy/dvorcy-kultury-i-kluby/110840pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2024-02-26 11:52:25+03', '2024-02-27 08:17:25+03', '0101000020E6100000FA60191BBA3F4240768C2B2E8ECA4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Хохловский дом культуры', 'Кадуйский район', 'Europe/Moscow', 'ул Торфяников,д 12', NULL, 'обл Вологодская,р-н Кадуйский,рп Хохлово,ул Торфяников,д 12', '{"type": "Point", "coordinates": [37.398078, 59.146555]}', '<p>Хохловский дом культуры был открыт в 1988 году. В нем работают 32 клубных формирования, в них занимается 741 человек. Ежегодно коллективом Хохловского дома культуры проводится более 3 000 мероприятий, которые посещает около 40 000 человек. </p><p>Коллективы художественной самодеятельности – постоянные участники областных и районных мероприятий, победители всероссийских, региональных и областных конкурсов. Народный самодеятельный коллектив ансамбль «Тальянка», являющийся лауреатом различных конкурсов, известен и за пределами региона. </p><p>В здании размещены 3 экспозиции Центра народной традиционной культуры и ремесел: «Улома железная», коллекции музыкальных инструментов и вышивки. Они пользуются популярностью у жителей и гостей поселка Хохлово и Кадуйского округа. </p>', NULL, 'dk.hohlovo@mail.ru', '[]', '{"url": "https://all.culture.ru/uploads/48a27f6f9cb4cd77114becce7a8b35a9.jpg", "title": "7f36ed9f03f201bf2c889c0984547fff.jpg"}', '[{"url": "https://all.culture.ru/uploads/cb94afd3a204ee667ce304ea5420f757.jpg", "title": "2a1b0e5dcee20a1bf8cba6931fe45f9e.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУ «Кадуйский ЦКР»', 'Вологодская область', 'Europe/Moscow', 'ул Строителей,д 2', NULL, 'обл Вологодская,рп Кадуй,ул Строителей,д 2', NULL, 3510010837, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"ok","name":"Культура. Кадуй","networkId":"61103236120724","updateDate":"2024-02-16T11:35:59Z","createDate":"2024-02-16T11:35:59Z","accountId":49941,"postingGroupId":44748}]', 36609, '[{"id": 25, "name": "Классическое искусство", "sysName": "klassicheskoe-iskusstvo"}, {"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:05:00", "from": "10:00:00"}', '{"to": "18:05:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "22:00:00", "from": "14:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 83328, '[{"url":"https://www.culture.ru/institutes/96275/khokhlovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kaduy/dvorcy-kultury-i-kluby/110839pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2024-02-26 11:49:51+03', '2024-02-27 08:14:31+03', '0101000020E6100000E8A04B38F4B242405B087250C2924D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Андроновский сельский дом культуры', 'Кадуйский район', 'Europe/Moscow', 'ул Надежды,д 11', NULL, 'обл Вологодская,р-н Кадуйский,д Андроново,ул Надежды,д 11', '{"type": "Point", "coordinates": [37.259306, 59.400625]}', '<p> Андроновский дом культуры был открыт в 1972 году. Более 50 лет он является центром культурной жизни деревни Андроново и близлежащих населенных пунктов. </p><p>На базе Дома культуры работают 11 клубных формирований. С особой любовью в селе относятся к участникам вокально-танцевальной детской группы «Овация». Дети учатся не только петь и танцевать, но и быть добрыми, раскованными, учатся общению. Для взрослых создан клуб «Рябинушка» и формирование «Юбиляр». Сельская молодежь активно участвует в клубе «Буги-вуги» и кружке «Зажигай». Вокальный ансамбль «Горлица» по праву является украшением Дома культуры.</p><p> </p><p>Среди детей и подростков проводится большая работа по формированию здорового образа жизни, для взрослых регулярно организуются познавательно-развлекательные программы. </p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/c71b4a803f8c0849fe3c0b83a4de4c2b.jpg", "title": "IMG_20220520_175250.jpg"}', '[{"url": "https://all.culture.ru/uploads/6f65bcd6cab501c3b79731e8d47869bc.jpg", "title": "Андроновский ДК (3).jpg"}, {"url": "https://all.culture.ru/uploads/1192179cb993810b5633f6ee6bf6ef7c.JPG", "title": "IMG_1537 (1).JPG"}]', NULL, 'Дворцы культуры и клубы', 'МБУ «Кадуйский ЦКР»', 'Вологодская область', 'Europe/Moscow', 'ул Строителей,д 2', NULL, 'обл Вологодская,рп Кадуй,ул Строителей,д 2', NULL, 3510010837, 'mincult', 'Вологодская область', 'Europe/Moscow', '[{"network":"ok","name":"Культура. Кадуй","networkId":"61103236120724","updateDate":"2024-02-16T11:35:59Z","createDate":"2024-02-16T11:35:59Z","accountId":49941,"postingGroupId":44748}]', 36609, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "14:00:00", "from": "11:00:00"}', '{"to": "14:00:00", "from": "11:00:00"}', '{"to": "14:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 83243, '[{"url":"https://www.culture.ru/institutes/96192/andronovskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kaduy/dvorcy-kultury-i-kluby/110615pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2024-02-19 15:56:07+03', '2024-02-20 08:10:01+03', '0101000020E61000000BD462F030A14240E17A14AE47B34D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Верхнешарденьгский клуб', 'Великоустюгский район', 'Europe/Moscow', 'д 79а', NULL, 'обл Вологодская,р-н Великоустюгский,с Верхняя Шарденьга,д 79а', '{"type": "Point", "coordinates": [46.318241, 60.395201]}', '<p>В здании бывшей школы расположен Верхнешарденьгский клуб, в котором проходят самые различные мероприятия. Для жителей и гостей поселения активно организуются и проводятся тематические праздники, концертные программы, народные гулянья, театрализованные представления, веселые игровые программы, вечера отдыха, занимательные конкурсы, интересные викторины, выставки, полезные мастер-классы. </p><p>Большее количество жителей села Верхняя Шарденьга – пенсионеры. Для них созданы два клубных формирования: клуб «Околица», в котором занимаются восемь человек, и театральный коллектив «Таланты», в составе которого десять человек. </p>', 'http://кдцву.рф', 'mukuadk@mail.ru', '[{"value": "78173868187", "comment": "специалист Забелинская Марина Сергеевна"}, {"value": "78173868187", "comment": "Бычихина Елена Евгеньевна начальник обособленного подразделения"}]', '{"url": "https://all.culture.ru/uploads/18970ec9978879835dea2b3ec1aaab50.jpg", "title": "2nJWgzZiVTw.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Великоустюгский культурно-досуговый центр»', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 101', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пр-кт Советский,д 101', NULL, 3526015975, 'mincult', 'Великоустюгский район', 'Europe/Moscow', '[{"network":"vk","name":"\"Кузинский клуб\"","networkId":"170421267","updateDate":"2023-04-05T11:45:45Z","createDate":"2023-04-05T11:45:45Z","accountId":46589,"postingGroupId":41531},{"network":"vk","name":"\"Усть-Алексеевский клуб\"","networkId":"196143083","updateDate":"2023-04-05T13:11:25Z","createDate":"2023-04-05T13:11:25Z","accountId":46589,"postingGroupId":41534},{"network":"vk","name":"«Верхневарженский клуб»","networkId":"219499380","updateDate":"2023-04-05T11:45:28Z","createDate":"2023-04-05T11:45:28Z","accountId":46589,"postingGroupId":41530},{"network":"vk","name":"«Морозовский клуб»","networkId":"219948363","updateDate":"2023-07-05T08:23:07Z","createDate":"2023-07-05T08:23:07Z","accountId":46589,"postingGroupId":42638},{"network":"vk","name":"«Новаторский клуб»","networkId":"217628593","updateDate":"2023-03-17T08:05:55Z","createDate":"2023-03-17T08:05:55Z","accountId":46589,"postingGroupId":41030},{"network":"vk","name":"Анюта Красникова","networkId":"17613040","updateDate":"2023-03-17T10:43:29Z","createDate":"2023-03-17T10:43:29Z","accountId":46594,"postingGroupId":41037},{"network":"vk","name":"БУК \"Юдинский дом культуры\" п. Стрига 6а","networkId":"160210512","updateDate":"2023-04-11T12:03:48Z","createDate":"2023-04-11T12:03:48Z","accountId":46589,"postingGroupId":41660},{"network":"vk","name":"Великоустюгский культурно-досуговый центр","networkId":"117993849","updateDate":"2024-02-15T08:49:55Z","createDate":"2024-02-15T08:49:55Z","accountId":46589,"postingGroupId":44737},{"network":"vk","name":"Обособленное подразделение \"Аристовский клуб\"","networkId":"195948369","updateDate":"2023-03-17T08:06:12Z","createDate":"2023-03-17T08:06:12Z","accountId":46589,"postingGroupId":41031},{"network":"vk","name":"Обособленное подразделение \"Сусоловский клуб\"","networkId":"219106681","updateDate":"2023-04-07T11:43:09Z","createDate":"2023-04-07T11:43:09Z","accountId":46589,"postingGroupId":41581},{"network":"vk","name":"Обособленное подразделение \"Теплогорский клуб\"","networkId":"97047864","updateDate":"2023-04-07T11:43:26Z","createDate":"2023-04-07T11:43:26Z","accountId":46589,"postingGroupId":41582},{"network":"vk","name":"Окультурено молодежью","networkId":"199241624","updateDate":"2023-03-17T10:42:43Z","createDate":"2023-03-17T10:42:43Z","accountId":46594,"postingGroupId":41036},{"network":"vk","name":"Парк культуры и отдыха /Великий Устюг/","networkId":"153198570","updateDate":"2023-04-05T11:46:08Z","createDate":"2023-04-05T11:46:08Z","accountId":46589,"postingGroupId":41532},{"network":"vk","name":"Полдарский клуб","networkId":"206228726","updateDate":"2023-07-05T08:23:33Z","createDate":"2023-07-05T08:23:33Z","accountId":46589,"postingGroupId":42639},{"network":"vk","name":"Театр Деда Мороза","networkId":"199304892","updateDate":"2020-11-03T05:54:59Z","createDate":"2020-11-03T05:54:59Z","accountId":21245,"postingGroupId":30273}]', 20409, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "14:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 83214, '[{"url":"https://afisha7.ru/velikiy-ustyug/dvorcy-kultury-i-kluby/110583pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/96164/verkhneshardengskii-klub","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2024-02-16 14:11:43+03', '2024-02-19 09:18:44+03', '0101000020E6100000889FFF1EBC2847405A2C45F295324E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Кадниковский дом культуры', 'Вожегодский район', 'Europe/Moscow', 'ул Первомайская,д 7', NULL, 'обл Вологодская,р-н Вожегодский,п Кадниковский,ул Первомайская,д 7', '{"type": "Point", "coordinates": [40.26798, 60.322771]}', '<p><span>Кадниковский дом культуры был открыт 7 марта 1975 года. </span><span>Он обслуживает жителей сельского поселения Кадниковское и является единственным культурно-досуговым учреждением на этой территории. В зону обслуживания входят поселки Яхренга и Бекетово.</span></p> <p><span></span><span>Для жителей созданы все условия для комфортного проведения досуга: уютный зрительный зал на 260 мест, танцевальный зал, комнаты для кружковых занятий. </span><span></span><span>Традиционно организуются мероприятия, посвященные праздничным календарным датам. </span></p><p><span></span><span>В работе с несовершеннолетними<span> </span>первостепенное место занимают патриотическое, духовно-нравственное и эстетическое воспитание, пропаганда здорового образа жизни, э</span><span>стетическое воспитание (игровые, праздничные, музыкальные программы, мастер-классы). Проводятся тематические программы, беседы, устные журналы, спортивные мероприятия.</span></p> <p><span>Творческие коллективы Дома культуры принимают участие в межпоселенческих и районных фестивалях и конкурсах. </span><span></span></p>', NULL, NULL, '[{"value": "78174422647", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/4912d3bcd752d90f261e44ba7e1199e0.jpg", "title": "Дом культуры.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Вожегодский ЦКР»', 'Вожегодский район', 'Europe/Moscow', 'ул Садовая,д 10', NULL, 'обл Вологодская,р-н Вожегодский,рп Вожега,ул Садовая,д 10', NULL, 3506005231, 'mincult', 'Вожегодский район', 'Europe/Moscow', NULL, 26662, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 83941, '[{"url":"https://afisha7.ru/vozhega/dvorcy-kultury-i-kluby/112023pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/96885/kadnikovskii-dom-kultury","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2024-04-02 14:58:38+03', '2024-04-03 16:41:41+03', '0101000020E6100000B5FD2B2B4D224440728C648F50294E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Тарногский центр традиционной народной культуры', 'Тарногский район', 'Europe/Moscow', 'ул Кирова,д 8', NULL, 'обл Вологодская,р-н Тарногский,с Тарногский Городок,ул Кирова,д 8', '{"type": "Point", "coordinates": [43.573151, 60.500893]}', '<p>Центр создан для сохранения, изучения, восстановления и развития традиционной народной культуры. Сотрудники учреждения занимаются развитием местного народного художественного творчества, самобытной национальной культуры, народного творчества и фольклорного наследия. </p><p>На базе центра осуществляют деятельность четыре ансамбля, два из которых имеют статус «народный»: народный фольклорный коллектив «Сударушка», народный семейный коллектив братьев Никулиных, семейный коллектив Череповецких, женский вокальный ансамбль «Росстань». Сотрудники учреждения организуют и проводят мероприятия по традиционной народной культуре для взрослых и детей.</p>', 'https://tarnogakultura.vlg.muzkult.ru', 'tarnogactnk@yandex.ru', '[{"value": "78174821247"}]', '{"url": "https://all.culture.ru/uploads/c0d42c1839d6e859d7d8dfc1769229c4.jpg", "title": "1_SfU8gss6c.jpg"}', '[{"url": "https://all.culture.ru/uploads/07e4bb2f5d7b7b6511243d52996b0ecf.jpg", "title": "b1bIFOey0v4.jpg"}, {"url": "https://all.culture.ru/uploads/4f1740031838dbd022fdbfd253cd52cc.jpg", "title": "tEcxFCxminE.jpg"}, {"url": "https://all.culture.ru/uploads/d7c840f3881136d52b722d9dbab23f68.jpg", "title": "FSgaeV4-buE.jpg"}, {"url": "https://all.culture.ru/uploads/be022ce0d8bfa1b68132818cb6b7593b.jpg", "title": "03.jpg"}]', NULL, 'Дворцы культуры и клубы', 'БУК «Тарногский ЦТНК»', 'Тарногский район', 'Europe/Moscow', 'ул Кирова,д 8', NULL, 'обл Вологодская,р-н Тарногский,с Тарногский Городок,ул Кирова,д 8', NULL, 3517003571, 'mincult', 'Тарногский район', 'Europe/Moscow', NULL, 37098, '[{"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 350, "name": "Народная культура", "sysName": "narodnaya-kultura"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 84620, '[{"url":"https://www.culture.ru/institutes/97542/tarnogskii-centr-tradicionnoi-narodnoi-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/tarnogskiy-gorodok/dvorcy-kultury-i-kluby/113131pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2024-05-20 09:59:54+03', '2024-05-20 10:32:51+03', '0101000020E6100000B95510035DC94540CDE506431D404E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Волокославинский сельский дом культуры', 'Кирилловский район', 'Europe/Moscow', 'ул Школьная,д 11', NULL, 'обл Вологодская,р-н Кирилловский,с Волокославинское,ул Школьная,д 11', '{"type": "Point", "coordinates": [38.782993, 59.916789]}', '<p><span><span> </span>Волокославинский<span> </span>сельский<span> </span>дом культуры<span> находится в одноэтажном здании</span>. Официально был открыт в 1972 году.</span><span> В здании расположены музейные<span> </span>экспозиции<span> </span>«Кирилловская гармонь» <span>и </span>«Жизнь и подвиг Героя Советского Союза Евгения Николаевича Преображенского» и зрительный зал на 96 мест. </span></p><p><span>В зоне обслуживания </span><span>517 человек. </span><span>Дом культуры работает в тесном контакте со всеми учреждениями, с населением<span> </span>с. Волокославинского<span> </span>и округа. Сотрудники стараются привлекать к подготовке и проведению мероприятий все категории населения, стремятся заинтересовать всех – от детей до пожилых людей. Самые активные и отзывчивые – это, конечно, дети и ветераны, сложнее с молодежью и семьями.</span></p> <p></p>', NULL, NULL, '[{"value": "79215322449"}]', '{"url": "https://all.culture.ru/uploads/9e46f2f3fb62fa803ad4888298a4d942.jpg", "title": "Волокославвино ДК.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'АУК КМР «ЦКР»', 'Кирилловский район', 'Europe/Moscow', 'ул Гагарина,д 98', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,ул Гагарина,д 98', NULL, 3511006791, 'mincult', 'Кирилловский район', 'Europe/Moscow', '[{"network":"vk","name":"Центр культурного развития","networkId":"17831631","updateDate":"2018-05-29T07:22:36Z","createDate":"2018-05-29T07:22:36Z","accountId":21387,"postingGroupId":18946}]', 20401, '[{"id": 24, "name": "История", "sysName": "istoriya"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}]', NULL, '{"to": "19:30:00", "from": "11:00:00"}', '{"to": "19:30:00", "from": "11:00:00"}', '{"to": "19:30:00", "from": "11:00:00"}', '{"to": "19:30:00", "from": "11:00:00"}', '{"to": "19:30:00", "from": "11:00:00"}', '{"to": "19:30:00", "from": "11:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77344, '[{"url":"https://afisha7.ru/kirillov/dvorcy-kultury-i-kluby/95941pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/90227/volokoslavinskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=af7ecc71-d397-4f09-acc4-fdade0405511&shareType=venue","serviceName":"ФанТам"}]', NULL, NULL, NULL, NULL, '2023-03-03 09:19:24+03', '2024-09-02 15:02:36+03', '0101000020E61000009BFF571D39644340912A8A5759F54D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Культурный центр «МаэстRо»', 'Череповец', 'Europe/Moscow', 'пр-кт Октябрьский,д 34', 'Авт. №7, 9, 13, 25, 31, ост. «Ул. Ленинградская».', 'обл Вологодская,г Череповец,пр-кт Октябрьский,д 34', '{"type": "Point", "coordinates": [37.911807, 59.099545]}', '<p>Культурный центр «МаэстRо» – многофункциональная площадка для проведения культурных мероприятий, занятий по творческим направлениям для детей и взрослых, проживающих на территории Зашекснинского района Череповца. Основан в 2019 году. Основной принцип работы – культурный максимум – предоставление услуг максимально разнообразных по жанрам, творческим и досуговым задачам. </p><p>В центре действуют коллективы вокальных, хореографических, цирковых и инструментальных жанров: ансамбль «Наша песня», цирк «Антре», хор мальчиков, хор ветеранов «Душа поет», танцевальный клуб «Академия танца», студия русского балета «Артклассик», вокальная студия CHarm Voice, группа «Имидж dance», ансамбль «Вдохновение», ансамбль гитаристов «Струны маэстро». </p><p>На сценической площадке проводятся мероприятия самых разнообразных форматов: концерты, спектакли, мастер-классы, выставки, презентации, конкурсы, праздники. Слоган центра – «Сообщество творческих и неравнодушных». Центр является точкой притяжения творческой молодежи, молодых авторов и исполнителей, специалистов различных сфер культуры. Уникальная особенность – сочетание культурно-досуговой и образовательной деятельности: в центре ведется обучение по образовательным программам художественной направленности (игра на музыкальных инструментах, вокал, хореография, школа ведущих и другие). </p>', 'https://vk.link/maestro_kc', NULL, '[{"value": "79115051073", "comment": "Администратор"}, {"value": "79211350050", "comment": "Руководитель"}]', '{"url": "https://all.culture.ru/uploads/198c3c7d0a4d0688da637a267075b9c3.jpg", "title": "IMG_20230205_094125.jpg"}', '[{"url": "https://all.culture.ru/uploads/7e8012aed8a9d6c34a1e51b7b197440e.JPG", "title": "DSCN0019.JPG"}, {"url": "https://all.culture.ru/uploads/e97b50bbf2b4f551772fac5f6071e971.JPG", "title": "DSCN0008.JPG"}, {"url": "https://all.culture.ru/uploads/4a0535413c4c4b84decf256a46022223.jpg", "title": "IMG_20221126_170316.jpg"}, {"url": "https://all.culture.ru/uploads/692919452acb5b7f181fcd123710b6f3.jpg", "title": "IMG_20221126_160451.jpg"}, {"url": "https://all.culture.ru/uploads/60a98b102cd58c3d5ae16e084555b0d0.jpg", "title": "IMG_20221210_175806.jpg"}, {"url": "https://all.culture.ru/uploads/9b6d7dc5139f7f2eb53ba65d71fff899.jpg", "title": "МК 17.12.jpg"}, {"url": "https://all.culture.ru/uploads/1fb220109f2ac3f8a9c70eb3e076c923.jpg", "title": "A3HCJmYu7Ao.jpg"}]', NULL, 'Дворцы культуры и клубы', 'Частное негосударственное образовательное учреждение дополнительного образования «Школа современного творчества «Мастер-класс»', 'Череповец', 'Europe/Moscow', 'пр-кт Октябрьский,д 34', NULL, 'обл Вологодская,г Череповец,пр-кт Октябрьский,д 34', NULL, 3528999989, 'commercial', 'Череповец', 'Europe/Moscow', NULL, 32520, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "22:00:00", "from": "08:00:00"}', '{"to": "22:00:00", "from": "08:00:00"}', '{"to": "22:00:00", "from": "08:00:00"}', '{"to": "22:00:00", "from": "08:00:00"}', '{"to": "22:00:00", "from": "08:00:00"}', '{"to": "22:00:00", "from": "08:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75817, '[{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/92365pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/88749/kulturnyi-centr-maestro","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-02-05 12:49:10+03', '2024-08-15 09:05:16+03', '0101000020E6100000C7A17E17B6F442407BBDFBE3BD8C4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Фетининский клуб', 'Вологодский район', 'Europe/Moscow', 'д 17', NULL, 'обл Вологодская,р-н Вологодский,п Фетинино,д 17', '{"type": "Point", "coordinates": [39.76575, 59.359787]}', '<p>Фетининский клуб был создан в 1986 году. Основное направление деятельности – культурно-досуговое. </p><p>Сегодня на базе учреждения работают шесть клубных формирований хореографического, вокального и театрального направлений. Проводятся различные мастер-классы для детей, молодежи и взрослой части населения. В стенах клуба ведет работу организация «Ветеран». </p><p>Работник клуба проводит культурно-массовые мероприятия, освещает важные даты. Деятельность клуба тесно связана с работой школы и библиотеки поселка. Недавно в клубе была создана театральная студия «Авокадо». Ребята принимают активное участие в концертных программах и конкурсах. </p>', 'https://vk.link/public198795633', NULL, '[]', '{"url": "https://all.culture.ru/uploads/cf99719fbbeebc85dbe1d7fc8469015d.jpg", "title": "5LE3cGsrKdw.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Семёнковское клубное объединение»', 'Вологодский район', 'Europe/Moscow', 'ул Первомайская,д 17', NULL, 'обл Вологодская,р-н Вологодский,п Семенково (Семенковское МО),ул Первомайская,д 17', NULL, 3507303470, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14048, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', NULL, '{"to": "17:30:00", "from": "10:00:00"}', NULL, '{"to": "17:30:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "12:00:00"}', '{"to": "18:00:00", "from": "12:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 51594, '[{"url":"https://www.culture.ru/institutes/77745/fetininskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/75400pl","serviceName":"Афиша7"}]', NULL, NULL, NULL, NULL, '2021-04-16 11:41:06+03', '2024-08-30 11:13:31+03', '0101000020E6100000BC74931804E2434052431B800DAE4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Ферапонтовский сельский дом культуры', 'Кирилловский район', 'Europe/Moscow', 'ул Слободская,д 4', NULL, 'обл Вологодская,р-н Кирилловский,с Ферапонтово,ул Слободская,д 4', '{"type": "Point", "coordinates": [38.568034287448256, 59.954636770676935]}', '<p><span>В здании имеется зрительный зал на 100 мест, кружковая комната, выставочный зал, зал для проведения вечеров отдыха.</span></p> <p><span>В зоне обслуживания находится 59 деревень, где проживает 891 человек. В Ферапонтовском доме культуры проводятся различные по форме и тематике культурно-массовые мероприятия: праздники, представления, концерты, спектакли. Дети с интересом<span> посещают</span> игровые программы и мастер-классы. Организована работа с любительскими творческими коллективами, работают кружки и клубы по интересам. Дом культуры работает в тесном контакте со всеми учреждениями и населением с. Ферапонтово. Для проведения мероприятия сотрудники учреждения стараются привлекать все категории населения, заинтересовать всех – от детей до пожилых людей.</span></p>', NULL, NULL, '[{"value": "79212374960"}]', '{"url": "https://all.culture.ru/uploads/db3a4a229210479677c8819b757aab94.jpg", "title": "20230306_082305.jpg"}', '[{"url": "https://all.culture.ru/uploads/77ba7b1427ea0ca3f8c7a855ce896fb0.jpg", "title": "20220508_152126.jpg"}]', NULL, 'Дворцы культуры и клубы', 'АУК КМР «ЦКР»', 'Кирилловский район', 'Europe/Moscow', 'ул Гагарина,д 98', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,ул Гагарина,д 98', NULL, 3511006791, 'mincult', 'Кирилловский район', 'Europe/Moscow', '[{"network":"vk","name":"Центр культурного развития","networkId":"17831631","updateDate":"2018-05-29T07:22:36Z","createDate":"2018-05-29T07:22:36Z","accountId":21387,"postingGroupId":18946}]', 20401, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77796, '[{"url":"https://afisha7.ru/kirillov/dvorcy-kultury-i-kluby/96894pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/90652/ferapontovskii-selskii-dom-kultury","serviceName":"Культура.рф"}]', NULL, NULL, NULL, NULL, '2023-03-16 15:44:33+03', '2024-09-03 15:05:34+03', '0101000020E610000068CCF758B5484340E9CEA68931FA4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Николоторжский сельский дом культуры', 'Кирилловский район', 'Europe/Moscow', 'ул Захарьинская,д 17', NULL, 'обл Вологодская,р-н Кирилловский,с Никольский Торжок,ул Захарьинская,д 17', '{"type": "Point", "coordinates": [38.768215, 59.872028]}', ' <p>Дом культуры был построен в 1970 на средства профсоюза колхоза «Николоторжский». Несколько лет назад был проведен капитальный ремонт здания. Теперь здесь привлекательный зрительный зал, оснащенный разнообразным музыкальным оборудованием, обновленной одеждой сцены, комфортными зрительскими местами. Есть большой танцевальный зал, который позволяет проводить не только танцевальные вечера, но и Вечера отдыха, игровые и спортивные программы.</p>  <p><span> </span>Большая прилегающая территория и уличная сцена позволяет проводить мероприятия не только в здании, но и на свежем воздухе.</p> <p><span> </span>На базе ДК работает 16 клубных формирований для всех категорий населения.</p> <p><span> </span>Большая работа ведется с ветеранами: Клубы«Ветеран», «Мастерица», «Здоровье»,<span> </span>ансамбль «Околица».</p> <p><span> </span>Детям также предложены различные кружки: вокальный кружок «Домисолька», театральный кружок «Радуга», танцевальный кружок «Флауэс», ИЗО-студия «Волшебная палитра», клубы «Родничок», «Возрождение» и семейный клуб «ТЫ+Я=СЕМЬЯ».</p> <p><span> </span>Молодежь и люди среднего возраста посещают вокальные студии «Я – солист» и «Созвучие сердец», вокальные кружки «Родники» и «Красна горка»</p>', NULL, NULL, '[{"value": "79626729469"}]', '{"url": "https://all.culture.ru/uploads/5f748f93bfbd744f48626100d807773c.jpg", "title": "НИКОЛА ДК.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'АУК КМР «ЦКР»', 'Кирилловский район', 'Europe/Moscow', 'ул Гагарина,д 98', NULL, 'обл Вологодская,р-н Кирилловский,г Кириллов,ул Гагарина,д 98', NULL, 3511006791, 'mincult', 'Кирилловский район', 'Europe/Moscow', '[{"network":"vk","name":"Центр культурного развития","networkId":"17831631","updateDate":"2018-05-29T07:22:36Z","createDate":"2018-05-29T07:22:36Z","accountId":21387,"postingGroupId":18946}]', 20401, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "21:00:00", "from": "11:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77363, '[{"url":"https://www.culture.ru/institutes/90281/nikolotorzhskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kirillov/dvorcy-kultury-i-kluby/96601pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=419d21d5-3792-4d77-b90c-08de37ac5ab4&shareType=venue","serviceName":"ФанТам"}]', NULL, NULL, NULL, NULL, '2023-03-03 12:51:11+03', '2024-09-03 11:11:30+03', '0101000020E6100000F8A57EDE5462434020990E9D9EEF4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Филиал центра «Забота» в мкр. Лукьяново', 'Вологда', 'Europe/Moscow', 'ул Михаила Поповича,д 18', NULL, 'обл Вологодская,г Вологда,ул Михаила Поповича,д 18', '{"type": "Point", "coordinates": [39.838747, 59.24685]}', '<p>Филиал культурно-досугового центра «Забота» в микрорайоне Лукьяново был открыт в 2012 году. Каждый вологжанин старшего возраста может найти здесь себе занятие по интересу. В филиале работают кружки по разным направлениям: музыкальное – ансамбль «Виктория»; спортивное – «Здоровая спина. Здоровые суставы»; художественное – изостудия для взрослых.</p><p>Проводятся различные мероприятия: концерты, литературные гостиные, конкурсы, выставки, мастер-классы. Ведется активное сотрудничество с другими филиалами центра «Забота». Филиал активно развивается, применяя в работе наиболее интересные формы творчества и досуга для старшего населения города.</p>', 'http://zabota.vlg.muzkult.ru', NULL, '[]', '{"url": "https://all.culture.ru/uploads/36ae25445bce067ca02d4f39d658333b.jpg", "title": "М. Поповича, 18.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Культурно-Досуговый Центр «Забота»', 'Вологда', 'Europe/Moscow', 'ул Мальцева,д 20', NULL, 'обл Вологодская,г Вологда,ул Мальцева,д 20', NULL, 3525266824, 'mincult', 'Вологда', 'Europe/Moscow', '[{"network":"vk","name":"Культурно-досуговый центр \"Забота\" г. Вологда","networkId":"62733448","updateDate":"2023-01-26T09:20:29Z","createDate":"2023-01-26T09:20:29Z","accountId":43357,"postingGroupId":39528}]', 20466, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "13:00:00", "from": "09:30:00"}', '{"to": "13:00:00", "from": "09:30:00"}', '{"to": "15:00:00", "from": "09:30:00"}', '{"to": "19:30:00", "from": "09:30:00"}', '{"to": "13:00:00", "from": "09:30:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 68151, '[{"url":"https://www.culture.ru/institutes/81519/filial-centra-zabota-v-mkr-lukyanovo","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/75216pl","serviceName":"Афиша7"}]', 68151, NULL, NULL, NULL, '2022-04-06 13:30:15+03', '2025-02-13 10:40:28+03', '0101000020E61000001E4FCB0F5CEB43404182E2C7989F4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Филиал центра «Забота» в мкр. Лоста', 'Вологда', 'Europe/Moscow', 'ул Пионерская,д 28', NULL, 'обл Вологодская,г Вологда,ул Пионерская,д 28', '{"type": "Point", "coordinates": [39.982091, 59.176692]}', '<p>Филиал Культурно-досугового центра «Забота» в микрорайоне Лоста на улице Пионерской, д. 28 был открыт в январе 2020 года.</p> <p>Каждый вологжанин старшего возраста может найти здесь себе занятие по интересу. В филиале работают кружки по направлениям: музыкальное – ансамбль «Лостовчаночка»; спортивное – скандинавская ходьба «Маршрут здоровья» и группа здоровья «Бодрость»; художественное – изостудии «Живая кисть» и «Семицветик».</p><p>Проводятся различные мероприятия – концерты, литературные гостиные, конкурсы, выставки, мастер-классы. Ведется активное сотрудничество с филиалами центра «Забота».</p><p>Филиал активно развивается, применяя в работе наиболее интересные формы творчества и досуга для старшего населения города.</p>', 'http://zabota.vlg.muzkult.ru', NULL, '[{"value": "78172749477"}]', '{"url": "https://all.culture.ru/uploads/9eb0f2854f1dff817f37ccf13d58d849.jpg", "title": "1 Пионерская, 28.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Культурно-Досуговый Центр «Забота»', 'Вологда', 'Europe/Moscow', 'ул Мальцева,д 20', NULL, 'обл Вологодская,г Вологда,ул Мальцева,д 20', NULL, 3525266824, 'mincult', 'Вологда', 'Europe/Moscow', '[{"network":"vk","name":"Культурно-досуговый центр \"Забота\" г. Вологда","networkId":"62733448","updateDate":"2023-01-26T09:20:29Z","createDate":"2023-01-26T09:20:29Z","accountId":43357,"postingGroupId":39528}]', 20466, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 68147, '[{"url":"https://www.culture.ru/institutes/81492/filial-centra-zabota-v-mkr-losta","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/75214pl","serviceName":"Афиша7"}]', 68147, NULL, NULL, NULL, '2022-04-06 13:13:57+03', '2025-02-13 10:38:15+03', '0101000020E610000014596B28B5FD434080BBECD79D964D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Филиал центра «Забота» на ул. Монастырской', 'Вологда', 'Europe/Moscow', 'ул Монастырская,д 16', NULL, 'обл Вологодская,г Вологда,ул Монастырская,д 16', '{"type": "Point", "coordinates": [39.885369, 59.264088]}', '<p>Филиал Культурно-досугового центра «Забота» на улице Монастырской, д. 16 был открыт в апреле 2021 года.</p><p>Каждый вологжанин старшего возраста может найти здесь себе занятие по интересу. В филиале работают кружки по направлениям: музыкальное – ансамбль мкр Прилуки; спортивное – «Китайская гимнастика байлун»; художественное – изостудии «Акварель», «Акварелька». Проводятся различные мероприятия – концерты, литературные гостиные, конкурсы, выставки, мастер-классы. Ведется активное сотрудничество с филиалами центра «Забота».</p><p>Филиал активно развивается, применяя в работе наиболее интересные формы творчества и досуга для старшего населения нашего города.</p>', 'http://zabota.vlg.muzkult.ru', NULL, '[{"value": "78172559202"}]', '{"url": "https://all.culture.ru/uploads/fe438e899de62a0e84927f5586621fef.jpg", "title": "1 Монастырская, 16.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Культурно-Досуговый Центр «Забота»', 'Вологда', 'Europe/Moscow', 'ул Мальцева,д 20', NULL, 'обл Вологодская,г Вологда,ул Мальцева,д 20', NULL, 3525266824, 'mincult', 'Вологда', 'Europe/Moscow', '[{"network":"vk","name":"Культурно-досуговый центр \"Забота\" г. Вологда","networkId":"62733448","updateDate":"2023-01-26T09:20:29Z","createDate":"2023-01-26T09:20:29Z","accountId":43357,"postingGroupId":39528}]', 20466, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "20:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, '{"to": "14:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 68140, '[{"url":"https://www.culture.ru/institutes/81500/filial-centra-zabota-na-ul-monastyrskoi","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/75210pl","serviceName":"Афиша7"}]', 68140, NULL, NULL, NULL, '2022-04-06 12:00:53+03', '2025-02-18 12:10:30+03', '0101000020E610000034F279C553F143400EA2B5A2CDA14D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Филиал центра «Забота» на ул. Преображенского', 'Вологда', 'Europe/Moscow', 'ул Преображенского,д 49', NULL, 'обл Вологодская,г Вологда,ул Преображенского,д 49', '{"type": "Point", "coordinates": [39.829916, 59.219529]}', '<p>Филиал центра «Забота» на улице Преображенского, 49 был открыт в феврале 2012 года.</p><p>Каждый вологжанин старшего возраста может найти здесь себе занятие по интересу. Работают кружки по направлениям: </p><ul><li>музыкальное – ансамбль «Преображение»; </li><li>спортивное – группа «Здоровье»; </li><li>декоративно-прикладное – «Волшебные петельки».</li></ul><p>Проводятся различные мероприятия – концерты, литературные гостиные, конкурсы, выставки, мастер-классы. Ведется активное сотрудничество с филиалами центра «Забота».</p><p>Филиал активно развивается, применяя в работе наиболее интересные формы творчества и досуга для старшего населения города.</p>', 'http://zabota.vlg.muzkult.ru', 'zabotapr@yandex.ru', '[{"value": "78172517635"}]', '{"url": "https://all.culture.ru/uploads/a614a361aabc9ef5cb0556e70892dec9.jpg", "title": "1 Преображенского, 49.jpg"}', '[{"url": "https://all.culture.ru/uploads/5805dded4ae5b7c5c4fa8596ee0e3f2b.jpeg", "title": "OHk_4cE2z70.jpg"}]', NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Культурно-Досуговый Центр «Забота»', 'Вологда', 'Europe/Moscow', 'ул Мальцева,д 20', NULL, 'обл Вологодская,г Вологда,ул Мальцева,д 20', NULL, 3525266824, 'mincult', 'Вологда', 'Europe/Moscow', '[{"network":"vk","name":"Культурно-досуговый центр \"Забота\" г. Вологда","networkId":"62733448","updateDate":"2023-01-26T09:20:29Z","createDate":"2023-01-26T09:20:29Z","accountId":43357,"postingGroupId":39528}]', 20466, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 206, "name": "Народное творчество", "sysName": "narodnoe-tvorchestvo"}]', NULL, '{"to": "16:00:00", "from": "09:00:00"}', '{"to": "16:00:00", "from": "09:00:00"}', '{"to": "16:00:00", "from": "09:00:00"}', '{"to": "16:00:00", "from": "09:00:00"}', '{"to": "16:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 54361, '[{"url":"https://www.culture.ru/institutes/78225/filial-centra-zabota-na-ul-preobrazhenskogo","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/75082pl","serviceName":"Афиша7"}]', 54361, NULL, NULL, NULL, '2021-06-11 09:49:52+03', '2025-02-13 10:39:09+03', '0101000020E6100000AC36FFAF3AEA434005C3B986199C4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Тороповский дом культуры', 'Бабаевский район', 'Europe/Moscow', 'ул Западная,д 1б', NULL, 'обл Вологодская,р-н Бабаевский,д Торопово,ул Западная,д 1б', '{"type": "Point", "coordinates": [35.666234, 59.497505]}', '<p>Новое кирпичное здание Тороповского дома культуры построено и введено в эксплуатацию в 1979 году.</p><p>На базе Дома культуры работает более 10 кружков и объединений для всех возрастных групп. Ансамбль ветеранов и танцевальный коллектив «Добрые соседи» занимаются концертной деятельностью, проводят тематические вечера и социально значимые мероприятия. Для ветеранов открыта физкультурно-оздоровительная группа, а дети посещают спортивный кружок. Кружок «Русская кукла» готовит поделки для конкурсов и выставок. </p><p>На базе Тороповского дома культуры действует музейная комната русского быта. <span><span> </span>В ней находятся предметы народного обихода XIX–ХХ веков. Всего 112 экземпляров. Проводятся экскурсии</span><span>, дающие </span><span>представление о жизни и быте русского народа.</span></p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/0036fc64c187203ab5d47eec46f1d684.jpeg", "title": "2AoRZQjhY6U.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МАУК «Бабаевский центр культурного развития»', 'Бабаевский район', 'Europe/Moscow', 'пл Привокзальная,1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,пл Привокзальная,1', NULL, 3501008870, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Володинский Дом культуры","networkId":"158838778","updateDate":"2018-10-12T11:09:38Z","createDate":"2018-10-12T11:09:38Z","accountId":22721,"postingGroupId":20087},{"network":"vk","name":"Кдц Бабаево","networkId":"275144982","isPersonal":true,"updateDate":"2018-10-12T11:09:46Z","createDate":"2018-10-12T11:09:46Z","accountId":22721,"postingGroupId":20088},{"network":"vk","name":"МБУК \"Бабаевский центр культурного развития\"","networkId":"23582611","updateDate":"2018-10-12T11:09:31Z","createDate":"2018-10-12T11:09:31Z","accountId":22721,"postingGroupId":20086}]', 20369, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 60224, '[{"url":"https://www.culture.ru/institutes/61425/toropovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/61316pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=33dfbc38-7823-4ebc-a7a0-813c3b479165&shareType=venue","serviceName":"ФанТам"}]', 60224, NULL, NULL, NULL, '2022-01-28 10:30:49+03', '2025-03-12 13:23:02+03', '0101000020E6100000DCBDDC2747D54140594C6C3EAEBF4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Володинский дом культуры', 'Вологодская область', 'Europe/Moscow', 'ул Набережная,д 7', NULL, 'обл Вологодская,д Володино,ул Набережная,д 7', '{"type": "Point", "coordinates": [35.827293, 59.407958]}', '<p>Володинский дом культуры был открыт летом 1989 года в очень живописном месте. Несмотря на все трудности, он остается центром культурной жизни и общения как для взрослых, так и для детей. Здесь организуют досуг для сельчан, развивают творческие способности и открывают новые таланты. </p><p>Энтузиасты-культработники придумывают праздничные сценарии и развлекательные программы, находят сценические костюмы. Сами шьют, клеят, рисуют. По-свойски, с теплотой и душевной простотой выступают самодеятельные артисты. Народный вокальный ансамбль «Рябинушка» и вокально-танцевальная группа «Задоринка» постоянно радуют зрителей своими выступлениями. <br /> </p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/7a1decd2cf304c8bb7417910384fb322.jpg", "title": "OhtZrTbBPlM.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МАУК «Бабаевский центр культурного развития»', 'Бабаевский район', 'Europe/Moscow', 'пл Привокзальная,1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,пл Привокзальная,1', NULL, 3501008870, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Володинский Дом культуры","networkId":"158838778","updateDate":"2018-10-12T11:09:38Z","createDate":"2018-10-12T11:09:38Z","accountId":22721,"postingGroupId":20087},{"network":"vk","name":"Кдц Бабаево","networkId":"275144982","isPersonal":true,"updateDate":"2018-10-12T11:09:46Z","createDate":"2018-10-12T11:09:46Z","accountId":22721,"postingGroupId":20088},{"network":"vk","name":"МБУК \"Бабаевский центр культурного развития\"","networkId":"23582611","updateDate":"2018-10-12T11:09:31Z","createDate":"2018-10-12T11:09:31Z","accountId":22721,"postingGroupId":20086}]', 20369, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 57453, '[{"url":"https://www.culture.ru/institutes/57158/volodinskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=6725bb65-65c0-4a7b-a41e-f8af2d2a2dd7&shareType=venue","serviceName":"ФанТам"}]', 57453, NULL, NULL, NULL, '2021-10-13 15:05:22+03', '2025-03-06 17:45:48+03', '0101000020E6100000D89AADBCE4E941401F12BEF737B44D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Ильинский клуб', 'Великоустюгский район', 'Europe/Moscow', 'д 51', 'в летний период – паром из г. Великий Устюг; в зимний период – по ледовой переправе', 'обл Вологодская,р-н Великоустюгский,с Ильинское,д 51', '{"type": "Point", "coordinates": [46.749351, 60.597636]}', '<p>Здание действующего клуба введено в эксплуатацию в конце лета 1989 года. Руководителем была Тамара Петровна Бестужева.</p> <p> В клубе работали кружки, проходили смотры художественной самодеятельности, весело и многолюдно проводились праздники: «Проводы зимы», Масленица, день деревни, 9 Мая, «Золотая осень», Новый год. В выходные и праздники проходили дискотеки для молодежи.</p> <p> До конца 1999 года вечерами показывали художественные кинофильмы. Все организации села и их работники в то время принимали активное участие в праздничных мероприятиях. С 2016 года заведующей работает Надежда Гавриловна Краева.</p> <p> На базе клуба занимается вокальный коллектив «Надежда», созданный в мае 2017 года, который не только организует праздничные мероприятия в своем клубе, но и активно участвует в муниципальных, межрегиональных, районных фестивалях и конкурсах. </p><p> Для жителей проводятся тематические вечера, праздничные вечера отдыха, торжественные митинги, молодежные дискотеки, юбилейные вечера отдыха и день деревни. Уютный зал всегда с радостью принимает зрителей, приходящих на организуемые в Доме культуры мероприятия.</p>', 'http://кдцву.рф', 'voroninausachyova@mail.ru', '[{"value": "78173861117", "comment": "Заведующая Краева Надежда Гавриловна"}, {"value": "78173865432", "comment": "Начальник Соболева Людмила Владимировна"}]', '{"url": "https://all.culture.ru/uploads/bf8e95a9a2130d10828927650a6dfa06.jpg", "title": "345.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Великоустюгский культурно-досуговый центр»', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 101', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пр-кт Советский,д 101', NULL, 3526015975, 'mincult', 'Великоустюгский район', 'Europe/Moscow', '[{"network":"vk","name":"\"Кузинский клуб\"","networkId":"170421267","updateDate":"2023-04-05T11:45:45Z","createDate":"2023-04-05T11:45:45Z","accountId":46589,"postingGroupId":41531},{"network":"vk","name":"\"Усть-Алексеевский клуб\"","networkId":"196143083","updateDate":"2023-04-05T13:11:25Z","createDate":"2023-04-05T13:11:25Z","accountId":46589,"postingGroupId":41534},{"network":"vk","name":"«Верхневарженский клуб»","networkId":"219499380","updateDate":"2023-04-05T11:45:28Z","createDate":"2023-04-05T11:45:28Z","accountId":46589,"postingGroupId":41530},{"network":"vk","name":"«Морозовский клуб»","networkId":"219948363","updateDate":"2023-07-05T08:23:07Z","createDate":"2023-07-05T08:23:07Z","accountId":46589,"postingGroupId":42638},{"network":"vk","name":"«Новаторский клуб»","networkId":"217628593","updateDate":"2023-03-17T08:05:55Z","createDate":"2023-03-17T08:05:55Z","accountId":46589,"postingGroupId":41030},{"network":"vk","name":"Анюта Красникова","networkId":"17613040","updateDate":"2023-03-17T10:43:29Z","createDate":"2023-03-17T10:43:29Z","accountId":46594,"postingGroupId":41037},{"network":"vk","name":"БУК \"Юдинский дом культуры\" п. Стрига 6а","networkId":"160210512","updateDate":"2023-04-11T12:03:48Z","createDate":"2023-04-11T12:03:48Z","accountId":46589,"postingGroupId":41660},{"network":"vk","name":"Великоустюгский культурно-досуговый центр","networkId":"117993849","updateDate":"2024-02-15T08:49:55Z","createDate":"2024-02-15T08:49:55Z","accountId":46589,"postingGroupId":44737},{"network":"vk","name":"Обособленное подразделение \"Аристовский клуб\"","networkId":"195948369","updateDate":"2023-03-17T08:06:12Z","createDate":"2023-03-17T08:06:12Z","accountId":46589,"postingGroupId":41031},{"network":"vk","name":"Обособленное подразделение \"Сусоловский клуб\"","networkId":"219106681","updateDate":"2023-04-07T11:43:09Z","createDate":"2023-04-07T11:43:09Z","accountId":46589,"postingGroupId":41581},{"network":"vk","name":"Обособленное подразделение \"Теплогорский клуб\"","networkId":"97047864","updateDate":"2023-04-07T11:43:26Z","createDate":"2023-04-07T11:43:26Z","accountId":46589,"postingGroupId":41582},{"network":"vk","name":"Окультурено молодежью","networkId":"199241624","updateDate":"2023-03-17T10:42:43Z","createDate":"2023-03-17T10:42:43Z","accountId":46594,"postingGroupId":41036},{"network":"vk","name":"Парк культуры и отдыха /Великий Устюг/","networkId":"153198570","updateDate":"2023-04-05T11:46:08Z","createDate":"2023-04-05T11:46:08Z","accountId":46589,"postingGroupId":41532},{"network":"vk","name":"Полдарский клуб","networkId":"206228726","updateDate":"2023-07-05T08:23:33Z","createDate":"2023-07-05T08:23:33Z","accountId":46589,"postingGroupId":42639},{"network":"vk","name":"Театр Деда Мороза","networkId":"199304892","updateDate":"2020-11-03T05:54:59Z","createDate":"2020-11-03T05:54:59Z","accountId":21245,"postingGroupId":30273}]', 20409, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "16:00:00", "from": "14:00:00"}', '{"to": "14:00:00", "from": "12:00:00"}', '{"to": "16:00:00", "from": "14:00:00"}', '{"to": "14:00:00", "from": "12:00:00"}', '{"to": "16:00:00", "from": "14:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 82080, '[{"url":"https://www.culture.ru/institutes/95059/ilinskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/dvorcy-kultury-i-kluby/108026pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=c6a7339d-1ce9-4abf-a6ab-b8691008aee8&shareType=venue","serviceName":"ФанТам"}]', 82080, NULL, NULL, NULL, '2023-12-07 11:19:38+03', '2025-04-25 16:17:26+03', '0101000020E6100000C91CCBBBEA5F4740C57421567F4C4E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Викторовский клуб', 'Великоустюгский район', 'Europe/Moscow', 'ул Полевая,д 15', 'в летний период – паром из г. Великий Устюг; в зимний период – по ледовой переправе на 680-м км р. Северная Двина', 'обл Вологодская,р-н Великоустюгский,д Первомайское,ул Полевая,д 15', '{"type": "Point", "coordinates": [46.86774, 60.609883]}', '<p>Викторовский клуб начал свою работу в 1953 году. </p><p>Здесь проводятся юбилеи жителей, концерты, праздники деревни, выставки цветов, рисунков, поделок, вязаных изделий, выпечных изделий, тематические вечера, устные журналы, викторины, игровые и танцевальные программы для детей и взрослых, вечера отдыха и др.<br /></p> <p> Коллектив артистов за 70 лет периодически обновлялся, с 2011 года он называется «Первомайские Любавушки». В Викторовском клубе также работают кружки «Художественная самодеятельность», «Давайте рисовать», любительское объединение «Поговорим о том о сем и про любовь споем».</p> <p>Направления деятельности Викторовского клуба:</p><ol><li>Развитие творческих способностей.</li><li>Популяризация знаний о Великой Отечественной войне.</li><li>Сбор и оформление материала о ветеранах Великой Отечественной войны, о людях хороших, о юбилярах.</li></ol>', 'http://кдцву.рф', 'meledina50@yandex.ru', '[{"value": "78173861184", "comment": "Заведующая Перминова Галина Витальевна"}, {"value": "78173865432", "comment": "Начальник Соболева Людмила Владимировна"}]', '{"url": "https://all.culture.ru/uploads/52892159fbc5b311a570c0c6516aa22a.JPG", "title": "DSCN2246[1].JPG"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Великоустюгский культурно-досуговый центр»', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 101', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пр-кт Советский,д 101', NULL, 3526015975, 'mincult', 'Великоустюгский район', 'Europe/Moscow', '[{"network":"vk","name":"\"Кузинский клуб\"","networkId":"170421267","updateDate":"2023-04-05T11:45:45Z","createDate":"2023-04-05T11:45:45Z","accountId":46589,"postingGroupId":41531},{"network":"vk","name":"\"Усть-Алексеевский клуб\"","networkId":"196143083","updateDate":"2023-04-05T13:11:25Z","createDate":"2023-04-05T13:11:25Z","accountId":46589,"postingGroupId":41534},{"network":"vk","name":"«Верхневарженский клуб»","networkId":"219499380","updateDate":"2023-04-05T11:45:28Z","createDate":"2023-04-05T11:45:28Z","accountId":46589,"postingGroupId":41530},{"network":"vk","name":"«Морозовский клуб»","networkId":"219948363","updateDate":"2023-07-05T08:23:07Z","createDate":"2023-07-05T08:23:07Z","accountId":46589,"postingGroupId":42638},{"network":"vk","name":"«Новаторский клуб»","networkId":"217628593","updateDate":"2023-03-17T08:05:55Z","createDate":"2023-03-17T08:05:55Z","accountId":46589,"postingGroupId":41030},{"network":"vk","name":"Анюта Красникова","networkId":"17613040","updateDate":"2023-03-17T10:43:29Z","createDate":"2023-03-17T10:43:29Z","accountId":46594,"postingGroupId":41037},{"network":"vk","name":"БУК \"Юдинский дом культуры\" п. Стрига 6а","networkId":"160210512","updateDate":"2023-04-11T12:03:48Z","createDate":"2023-04-11T12:03:48Z","accountId":46589,"postingGroupId":41660},{"network":"vk","name":"Великоустюгский культурно-досуговый центр","networkId":"117993849","updateDate":"2024-02-15T08:49:55Z","createDate":"2024-02-15T08:49:55Z","accountId":46589,"postingGroupId":44737},{"network":"vk","name":"Обособленное подразделение \"Аристовский клуб\"","networkId":"195948369","updateDate":"2023-03-17T08:06:12Z","createDate":"2023-03-17T08:06:12Z","accountId":46589,"postingGroupId":41031},{"network":"vk","name":"Обособленное подразделение \"Сусоловский клуб\"","networkId":"219106681","updateDate":"2023-04-07T11:43:09Z","createDate":"2023-04-07T11:43:09Z","accountId":46589,"postingGroupId":41581},{"network":"vk","name":"Обособленное подразделение \"Теплогорский клуб\"","networkId":"97047864","updateDate":"2023-04-07T11:43:26Z","createDate":"2023-04-07T11:43:26Z","accountId":46589,"postingGroupId":41582},{"network":"vk","name":"Окультурено молодежью","networkId":"199241624","updateDate":"2023-03-17T10:42:43Z","createDate":"2023-03-17T10:42:43Z","accountId":46594,"postingGroupId":41036},{"network":"vk","name":"Парк культуры и отдыха /Великий Устюг/","networkId":"153198570","updateDate":"2023-04-05T11:46:08Z","createDate":"2023-04-05T11:46:08Z","accountId":46589,"postingGroupId":41532},{"network":"vk","name":"Полдарский клуб","networkId":"206228726","updateDate":"2023-07-05T08:23:33Z","createDate":"2023-07-05T08:23:33Z","accountId":46589,"postingGroupId":42639},{"network":"vk","name":"Театр Деда Мороза","networkId":"199304892","updateDate":"2020-11-03T05:54:59Z","createDate":"2020-11-03T05:54:59Z","accountId":21245,"postingGroupId":30273}]', 20409, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "12:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 82076, '[{"url":"https://www.culture.ru/institutes/95043/viktorovskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/dvorcy-kultury-i-kluby/108013pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=4b3ffec6-b3d6-4217-89b4-145ee22102d6&shareType=venue","serviceName":"ФанТам"}]', 82076, NULL, NULL, NULL, '2023-12-07 11:14:32+03', '2025-04-25 16:18:30+03', '0101000020E61000002CB7B41A126F474075B169A5104E4E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Марденгский клуб', 'Великоустюгский район', 'Europe/Moscow', 'ул Школьная,д 8', 'проезд от Великого Устюга до деревни Благовещенье', 'обл Вологодская,р-н Великоустюгский,д Благовещенье,ул Школьная,д 8', '{"type": "Point", "coordinates": [46.099465, 60.728613]}', '<p><span> Марденгский дом культуры начал свою деятельность в 2000 году. Деятельность учреждения направлена на предоставление населению услуг просветительского, социокультурного и развлекательного характера; поддержку любительского художественного творчества; сохранение народной традиционной культуры; создание условий для развития и реализации потенциальных способностей личности.</span></p> <p><span> В настоящее время культурное обслуживание населения представлено двумя сферами деятельности: организация культурно-массовых мероприятий и организация работы клубных формирований.</span></p><p><span> <span>Ансамбли и солисты учреждения проводят 2–3 концерта в месяц как в зрительном здании, так и на открытом воздухе. </span></span></p> <p><span><span> </span>Функционируют 8 клубных формирований: декоративно-прикладной кружок «Умелые ручки»; спортивно-оздоровительный кружок «Фитнес»; кружки «Шахматы», «Гитара», «Вокал»; вокальные ансамбли «Сударушка» и «Надежда»; литературно-музыкальная гостиная «Творческие люди».</span><span> </span></p>', 'https://кдцву.рф', 'mard.dk@mail.ru', '[{"value": "79211261977", "comment": "начальник Михаил Васильевич Кудряшов"}, {"value": "78173865837", "comment": "менеджер Наталья Викторовна Жирохова"}]', '{"url": "https://all.culture.ru/uploads/573aa479b77b9b78724f3a6f2b8285ae.jpg", "title": "4tmaZ7G5CbQ.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Великоустюгский культурно-досуговый центр»', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 101', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пр-кт Советский,д 101', NULL, 3526015975, 'mincult', 'Великоустюгский район', 'Europe/Moscow', '[{"network":"vk","name":"\"Кузинский клуб\"","networkId":"170421267","updateDate":"2023-04-05T11:45:45Z","createDate":"2023-04-05T11:45:45Z","accountId":46589,"postingGroupId":41531},{"network":"vk","name":"\"Усть-Алексеевский клуб\"","networkId":"196143083","updateDate":"2023-04-05T13:11:25Z","createDate":"2023-04-05T13:11:25Z","accountId":46589,"postingGroupId":41534},{"network":"vk","name":"«Верхневарженский клуб»","networkId":"219499380","updateDate":"2023-04-05T11:45:28Z","createDate":"2023-04-05T11:45:28Z","accountId":46589,"postingGroupId":41530},{"network":"vk","name":"«Морозовский клуб»","networkId":"219948363","updateDate":"2023-07-05T08:23:07Z","createDate":"2023-07-05T08:23:07Z","accountId":46589,"postingGroupId":42638},{"network":"vk","name":"«Новаторский клуб»","networkId":"217628593","updateDate":"2023-03-17T08:05:55Z","createDate":"2023-03-17T08:05:55Z","accountId":46589,"postingGroupId":41030},{"network":"vk","name":"Анюта Красникова","networkId":"17613040","updateDate":"2023-03-17T10:43:29Z","createDate":"2023-03-17T10:43:29Z","accountId":46594,"postingGroupId":41037},{"network":"vk","name":"БУК \"Юдинский дом культуры\" п. Стрига 6а","networkId":"160210512","updateDate":"2023-04-11T12:03:48Z","createDate":"2023-04-11T12:03:48Z","accountId":46589,"postingGroupId":41660},{"network":"vk","name":"Великоустюгский культурно-досуговый центр","networkId":"117993849","updateDate":"2024-02-15T08:49:55Z","createDate":"2024-02-15T08:49:55Z","accountId":46589,"postingGroupId":44737},{"network":"vk","name":"Обособленное подразделение \"Аристовский клуб\"","networkId":"195948369","updateDate":"2023-03-17T08:06:12Z","createDate":"2023-03-17T08:06:12Z","accountId":46589,"postingGroupId":41031},{"network":"vk","name":"Обособленное подразделение \"Сусоловский клуб\"","networkId":"219106681","updateDate":"2023-04-07T11:43:09Z","createDate":"2023-04-07T11:43:09Z","accountId":46589,"postingGroupId":41581},{"network":"vk","name":"Обособленное подразделение \"Теплогорский клуб\"","networkId":"97047864","updateDate":"2023-04-07T11:43:26Z","createDate":"2023-04-07T11:43:26Z","accountId":46589,"postingGroupId":41582},{"network":"vk","name":"Окультурено молодежью","networkId":"199241624","updateDate":"2023-03-17T10:42:43Z","createDate":"2023-03-17T10:42:43Z","accountId":46594,"postingGroupId":41036},{"network":"vk","name":"Парк культуры и отдыха /Великий Устюг/","networkId":"153198570","updateDate":"2023-04-05T11:46:08Z","createDate":"2023-04-05T11:46:08Z","accountId":46589,"postingGroupId":41532},{"network":"vk","name":"Полдарский клуб","networkId":"206228726","updateDate":"2023-07-05T08:23:33Z","createDate":"2023-07-05T08:23:33Z","accountId":46589,"postingGroupId":42639},{"network":"vk","name":"Театр Деда Мороза","networkId":"199304892","updateDate":"2020-11-03T05:54:59Z","createDate":"2020-11-03T05:54:59Z","accountId":21245,"postingGroupId":30273}]', 20409, '[{"id": 28, "name": "Литература", "sysName": "literatura"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 325, "name": "Творческий коллектив", "sysName": "tvorcheskiy-kollektiv"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}]', '[{"hosting":"vk","id":"<iframe src=\"https://vk.com/video_ext.php?oid=-187436350&id=456239091&hash=c1baccb6d20615d7&hd=2\" width=\"853\" height=\"480\"></iframe>"},{"hosting":"vk","id":"<iframe src=\"https://vk.com/video_ext.php?oid=-187436350&id=456239087&hash=56e9598106ac348f&hd=2\" width=\"853\" height=\"480\"></iframe>"},{"hosting":"vk","id":"<iframe src=\"https://vk.com/video_ext.php?oid=-187436350&id=456239084&hash=fa13006d2c7a7135&hd=1\" width=\"640\" height=\"360\"></iframe>"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78781, '[{"url":"https://afisha7.ru/velikiy-ustyug/dvorcy-kultury-i-kluby/99117pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/91653/mardengskii-klub","serviceName":"Культура.рф"}]', 78781, NULL, NULL, NULL, '2023-04-07 16:35:19+03', '2025-04-25 16:17:55+03', '0101000020E61000005F0CE544BB0C47406138D730435D4E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Лежский сельский дом культуры', 'Грязовецкий район', 'Europe/Moscow', 'д 32', NULL, 'обл Вологодская,р-н Грязовецкий,д Спасское,д 32', '{"type": "Point", "coordinates": [40.746387, 58.923426]}', '<p>Лежский сельский дом культуры всегда был центром притяжения жителей села Спасского. Он располагается в одноэтажном здании 1975 года постройки. Несмотря на небольшую площадь, в Лежском сельском доме культуры имеются два оборудованных досуговых помещения и просторный зрительный зал, который ежедневно распахивает своих двери для жителей села.</p><p>Культурно-досуговая деятельность поддерживается на высоком уровне, обеспечивая односельчан интересным времяпровождением и досугом: кружковыми занятиями, концертами и фестивалями различного уровня. Сотрудники Лежского сельского дома культуры регулярно проходят профессиональные курсы переподготовки, что позволяет учреждению оставаться современным.</p>', NULL, 'natalyahlusova@yandex.ru', '[{"value": "79517477194"}]', '{"url": "https://all.culture.ru/uploads/ebbbdcc54d04dff0d4854bcdce1437b5.JPG", "title": "SAM_2029.JPG"}', NULL, NULL, 'Дворцы культуры и клубы', 'БУК Грязовецкого муниципального округа Вологодской области «Культурно-досуговый центр»', 'Грязовецкий район', 'Europe/Moscow', 'ул Карла Маркса,д 46', NULL, 'обл Вологодская,р-н Грязовецкий,г Грязовец,ул Карла Маркса,д 46', NULL, 3509010367, 'mincult', 'Грязовецкий район', 'Europe/Moscow', '[{"network":"vk","name":"БУК \"Культурно-досуговый центр\"","networkId":"86530729","updateDate":"2021-06-24T12:11:18Z","createDate":"2021-06-24T12:11:18Z","accountId":38444,"postingGroupId":34915},{"network":"vk","name":"КиноГрязовец","networkId":"176595226","updateDate":"2023-05-03T08:03:55Z","createDate":"2023-05-03T08:03:55Z","accountId":38444,"postingGroupId":42088}]', 17441, NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 73710, '[{"url":"https://www.culture.ru/institutes/86793/lezhskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/gryazovec/dvorcy-kultury-i-kluby/89264pl","serviceName":"Афиша7"}]', 73710, NULL, NULL, NULL, '2022-12-02 16:07:10+03', '2025-04-25 17:52:48+03', '0101000020E61000006C94F59B895F44405723BBD232764D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Анохинский сельский дом культуры', 'Грязовецкий район', 'Europe/Moscow', 'ул Центральная,д 42', NULL, 'обл Вологодская,р-н Грязовецкий,д Анохино,ул Центральная,д 42', '{"type": "Point", "coordinates": [40.790673, 58.795178]}', '<p><span>Здание было построено в 1991 году и с тех пор ежедневно притягивает к себе местное население. Для сельчан созданы все условия для приятного времяпрепровождения: для досуговой деятельности есть два больших зала, отличающихся комфортом.</span><br /></p><p>В филиале осуществляют свою деятельность кружки для посетителей всех возрастов. На сегодняшний день здесь ведут работу 13 клубных формирований различной жанровой направленности, в которых занимаются 160 человек. Вокал, декоративно-прикладное творчество, хореография – самые востребованные среди местных жителей направления.</p><p>Все коллективы Анохинского сельского дома культуры успешно и результативно принимают участие во многих фестивалях и конкурсах.</p>', NULL, 'balashova.i2017@yandex.ru', '[{"value": "78175549212"}]', '{"url": "https://all.culture.ru/uploads/8103193a4a6909acc73fd760ae3f55ab.jpg", "title": "D_V4T9snV2Q (1).jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'БУК Грязовецкого муниципального округа Вологодской области «Культурно-досуговый центр»', 'Грязовецкий район', 'Europe/Moscow', 'ул Карла Маркса,д 46', NULL, 'обл Вологодская,р-н Грязовецкий,г Грязовец,ул Карла Маркса,д 46', NULL, 3509010367, 'mincult', 'Грязовецкий район', 'Europe/Moscow', '[{"network":"vk","name":"БУК \"Культурно-досуговый центр\"","networkId":"86530729","updateDate":"2021-06-24T12:11:18Z","createDate":"2021-06-24T12:11:18Z","accountId":38444,"postingGroupId":34915},{"network":"vk","name":"КиноГрязовец","networkId":"176595226","updateDate":"2023-05-03T08:03:55Z","createDate":"2023-05-03T08:03:55Z","accountId":38444,"postingGroupId":42088}]', 17441, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 73709, '[{"url":"https://www.culture.ru/institutes/86791/anokhinskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/gryazovec/dvorcy-kultury-i-kluby/89002pl","serviceName":"Афиша7"}]', 73709, NULL, NULL, NULL, '2022-12-02 15:55:32+03', '2025-04-25 17:52:42+03', '0101000020E6100000446ADAC534654440D53F8864C8654D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Плосковский сельский дом культуры', 'Грязовецкий район', 'Europe/Moscow', 'ул Школьная,д 1', NULL, 'обл Вологодская,р-н Грязовецкий,п Плоское,ул Школьная,д 1', '{"type": "Point", "coordinates": [40.28000977909849, 58.64341485828253]}', '<p>Структурное подразделение филиал Плосковский сельский Дом культуры является одним из филиалов бюджетного учреждения культуры Грязовецкого муниципального района Вологодской области «Культурно-досуговый центр», территориально расположен в Ростиловском муниципальном образовании.</p><p>Дом культуры впервые распахнул свои двери для посетителей 1 января 1979 года. С того момента и по сей день он является центром культурной жизни поселка. Сегодня здесь ведут творческую деятельность 11 клубных формирований. Еженедельно для населения проводятся разнообразные торжественные мероприятия, праздничные концерты, развлекательные программы и акции.</p><p><br /></p>', NULL, 't.sushkova2018@yandex.ru', '[{"value": "79115465285"}]', '{"url": "https://all.culture.ru/uploads/ec335b2f9362499a5051b29aed5bcacb.jpg", "title": "rzGLnQ29aAk.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'БУК Грязовецкого муниципального округа Вологодской области «Культурно-досуговый центр»', 'Грязовецкий район', 'Europe/Moscow', 'ул Карла Маркса,д 46', NULL, 'обл Вологодская,р-н Грязовецкий,г Грязовец,ул Карла Маркса,д 46', NULL, 3509010367, 'mincult', 'Грязовецкий район', 'Europe/Moscow', '[{"network":"vk","name":"БУК \"Культурно-досуговый центр\"","networkId":"86530729","updateDate":"2021-06-24T12:11:18Z","createDate":"2021-06-24T12:11:18Z","accountId":38444,"postingGroupId":34915},{"network":"vk","name":"КиноГрязовец","networkId":"176595226","updateDate":"2023-05-03T08:03:55Z","createDate":"2023-05-03T08:03:55Z","accountId":38444,"postingGroupId":42088}]', 17441, '[{"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', '{"to": "19:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 73589, '[{"url":"https://www.culture.ru/institutes/86688/ploskovskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/gryazovec/dvorcy-kultury-i-kluby/88062pl","serviceName":"Афиша7"}]', 73589, NULL, NULL, NULL, '2022-11-30 17:20:59+03', '2025-04-25 17:52:31+03', '0101000020E6100000E4E4455CD7234440BF0A076B5B524D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Центральный дом культуры с. им. Бабушкина', 'Бабушкинский район', 'Europe/Moscow', 'ул Бабушкина,д 63', NULL, 'обл Вологодская,р-н Бабушкинский,с им Бабушкина,ул Бабушкина,д 63', '{"type": "Point", "coordinates": [43.126176, 59.753999]}', '<p> История Дома культуры началась в 1975 году. Для всех жителей села он стал центром культурной и общественной жизни. </p><p> Учреждение осуществляет следующие виды деятельности:</p><ul><li>проведение различных культурно-массовых мероприятий: праздников, фестивалей, концертов, спектаклей, игровых развлекательных программ и др.;</li><li>создание и организация работы любительских творческих коллективов, кружков, студий, клубов;</li><li>изучение, обобщение и распространение опыта культурно-массовой, культурно-воспитательной, культурно-зрелищной работы учреждения.<br /></li></ul><p> В зоне обслуживания проживает порядка 4 000 человек. Дом культуры является главной сценической площадкой района, на которой проводятся значимые районные мероприятия, межрайонные фестивали и конкурсы. </p><p> В учреждении функционируют 30 клубных формирований, 2 коллектива имеют звание «народный самодеятельный коллектив» (вокальный ансамбль «Леденжаночка», народный хор ветеранов). Творческие коллективы принимают участие в муниципальных, районных и областных конкурсах, фестивалях, выездных концертах, активно участвуют в культурной жизни района. <br /></p><p> Уютный зрительный зал на 225 мест с радостью принимает зрителей, приходящих на концерты и спектакли. Современная звуковая аппаратура и профессиональный свет позволяют проводить различные мероприятия на высоком уровне. Также в здании оборудована имитация русской избы, куда с удовольствием приходят на фольклорные мероприятия жители села. <br /></p>', 'http://babushmbukrdk.ru', 'mbukrdk@bk.ru', '[{"value": "78174521312", "comment": "Директор"}, {"value": "79535139895", "comment": "Художник декоратор"}]', '{"url": "https://all.culture.ru/uploads/323fceafbdf0fc44e1bf2b0c5de29892.jpg", "title": "poUEs_WoEXU.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Центральный Дом культуры» Бабушкинского муниципального округа', 'Бабушкинский район', 'Europe/Moscow', 'ул. Бабушкина,63', NULL, 'обл Вологодская,р-н Бабушкинский,с им Бабушкина,ул. Бабушкина,63', NULL, 3502005590, 'mincult', 'Бабушкинский район', 'Europe/Moscow', NULL, 26248, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "20:00:00", "from": "09:00:00"}', '{"to": "20:00:00", "from": "09:00:00"}', '{"to": "20:00:00", "from": "09:00:00"}', '{"to": "20:00:00", "from": "09:00:00"}', '{"to": "22:00:00", "from": "09:00:00"}', '{"to": "22:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 72256, '[{"url":"https://www.culture.ru/institutes/85373/centralnyi-dom-kultury-s-im-babushkina","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/imeni-babushkina/dvorcy-kultury-i-kluby/86165pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=235aa378-b314-40ee-b24e-59826f86f19f&shareType=venue","serviceName":"ФанТам"}]', 72256, NULL, NULL, NULL, '2022-11-09 17:07:25+03', '2025-04-28 16:37:22+03', '0101000020E610000022C5008926904540BD1B0B0A83E04D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Колошомский сельский клуб', 'Бабаевский район', 'Europe/Moscow', 'д 62', NULL, 'обл Вологодская,р-н Бабаевский,п Колошма,д 62', '{"type": "Point", "coordinates": [35.420967, 60.170795]}', '<p>Колошомский клуб с 2013 года располагается в бывшем здании Колошомского лесопункта.<br /></p><p>В учреждении осуществляют творческую деятельность 3 клубных формирования:</p><ol><li>Вокальная группа «Молодушки», в которой занимаются концертной деятельностью, проводят тематические вечера и социально значимые мероприятия, создают сценические костюмы.<br /></li><li>Клуб ветеранов «Наши годы молодые» объединяет людей старшего поколения. Клуб занимается организацией досуга пожилых людей, проведением праздников, визитами-поздравлениями ветеранов на дому, познавательными и развлекательными мероприятиями, посиделками.<br /></li><li>Кружок «Хозяюшка» готовит поделки из подручных материалов. Участники в нем вяжут и шьют.<br /></li></ol><p>Жители и гости поселка с удовольствием проводят здесь время, участвуют в различных мероприятиях, торжественных митингах, творческих объединениях.</p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/2f840bccf4a862bcaaf611e013613576.jpg", "title": "qRlCDnDkGIk.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МАУК «Бабаевский центр культурного развития»', 'Бабаевский район', 'Europe/Moscow', 'пл Привокзальная,1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,пл Привокзальная,1', NULL, 3501008870, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Володинский Дом культуры","networkId":"158838778","updateDate":"2018-10-12T11:09:38Z","createDate":"2018-10-12T11:09:38Z","accountId":22721,"postingGroupId":20087},{"network":"vk","name":"Кдц Бабаево","networkId":"275144982","isPersonal":true,"updateDate":"2018-10-12T11:09:46Z","createDate":"2018-10-12T11:09:46Z","accountId":22721,"postingGroupId":20088},{"network":"vk","name":"МБУК \"Бабаевский центр культурного развития\"","networkId":"23582611","updateDate":"2018-10-12T11:09:31Z","createDate":"2018-10-12T11:09:31Z","accountId":22721,"postingGroupId":20086}]', 20369, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}]', NULL, '{"to": "14:00:00", "from": "10:00:00"}', '{"to": "14:00:00", "from": "10:00:00"}', '{"to": "14:00:00", "from": "10:00:00"}', '{"to": "14:00:00", "from": "10:00:00"}', '{"to": "14:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 70443, '[{"url":"https://www.culture.ru/institutes/83611/koloshomskii-selskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/81874pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=163dd372-b538-40f8-bade-be384d1f8362&shareType=venue","serviceName":"ФанТам"}]', 70443, NULL, NULL, NULL, '2022-08-12 15:51:40+03', '2025-04-07 15:00:33+03', '0101000020E6100000FDD8243FE2B5414000A94D9CDC154E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Комоневский дом культуры', 'Бабаевский район', 'Europe/Moscow', 'д 67', NULL, 'обл Вологодская,р-н Бабаевский,д Горка,д 67', '{"type": "Point", "coordinates": [36.316318, 60.096682]}', '<p> Комоневский дом культуры проводит различные мероприятия (концерты, вечера отдыха, спортивные программы и др.) для жителей д. Горка. С января 2022 года относится к Этнокультурному центру Бабаевского района.</p><p> Особое внимание уделяется сохранению вепсской культуры. В ДК вот уже десять лет культорганизатором работает коренная вепсянка, под ее руководством были созданы вокальный коллектив «Реченька», вепсский коллектив «Гегут», клуб ветеранов «Дубравушка», кружок «Мастерицы», клуб выходного дня «Завалинка». Коллективы выступают не только в своем ДК, но и на площадках других деревень. </p><p>Дом культуры – участник многих фестивалей: «Древо жизни», «Земля родная», «Язык родной, дружи со мной» и др.</p> <p><span> </span></p>', NULL, NULL, '[]', '{"url": "https://all.culture.ru/uploads/be3dcc0293e0b932749e7f03f03c2656.jpeg", "title": "ApamkJQ-z78.jpg"}', '[{"url": "https://all.culture.ru/uploads/44ff14396f6616fb12427c8af79603fc.jpeg", "title": "11.jpg"}, {"url": "https://all.culture.ru/uploads/740b05df91f688734a6bf7b4b0584f9b.jpeg", "title": "12.jpg"}, {"url": "https://all.culture.ru/uploads/03ba3daafc03b286ef8f3a8648ae66a7.jpeg", "title": "13.jpg"}]', NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Бабаевский этнокультурный центр»', 'Бабаевский район', 'Europe/Moscow', 'ул Советская,д.23 пом.1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,ул Советская,д.23 пом.1', NULL, 3501009049, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Вепсская кухня","networkId":"208862479","updateDate":"2023-02-08T13:11:25Z","createDate":"2023-02-08T13:11:25Z","accountId":45664,"postingGroupId":40011},{"network":"vk","name":"Комоневский ДК","networkId":"176344109","updateDate":"2023-04-11T13:23:12Z","createDate":"2023-04-11T13:23:12Z","accountId":45056,"postingGroupId":41671},{"network":"vk","name":"Тимошинский Дом культуры.","networkId":"140436219","updateDate":"2023-04-11T13:23:04Z","createDate":"2023-04-11T13:23:04Z","accountId":45056,"postingGroupId":41670},{"network":"vk","name":"Туризм Бабаевского района","networkId":"128647289","updateDate":"2023-04-11T13:22:56Z","createDate":"2023-01-22T04:16:35Z","accountId":45056,"postingGroupId":39284},{"network":"vk","name":"Фестиваль  вепсских игр \"Lapsiden v?ndod\"","networkId":"218337418","updateDate":"2023-02-08T13:11:35Z","createDate":"2023-02-08T13:11:35Z","accountId":45664,"postingGroupId":40012},{"network":"vk","name":"Этнокультурный центр Бабаевского района","networkId":"99489293","updateDate":"2023-04-11T13:22:45Z","createDate":"2023-01-22T04:16:17Z","accountId":45056,"postingGroupId":39283}]', 29145, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', NULL, '{"to": "18:00:00", "from": "10:00:00"}', NULL, '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 61867, '[{"url":"https://www.culture.ru/institutes/62558/komonevskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/65814pl","serviceName":"Афиша7"}]', 61867, NULL, NULL, NULL, '2022-02-12 13:13:36+03', '2025-04-18 10:58:24+03', '0101000020E61000006D91B41B7D284240520E6613600C4E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Тимошинский дом культуры', 'Бабаевский район', 'Europe/Moscow', 'ул Солнечная,д 1А', NULL, 'обл Вологодская,р-н Бабаевский,д Тимошино,ул Солнечная,д 1А', '{"type": "Point", "coordinates": [36.187176, 60.101396]}', '<p>В центре внимания Тимошинского дома культуры – сохранение, развитие и популяризация традиционной культуры малочисленного коренного народа – вепсов. На базе учреждения ведут работу несколько фольклорных вепсских коллективов, самые известные из них «Пяйвейне» и «Гегут». Коллективы были основаны в 2010 году и совсем недавно справили юбилей.</p><p> Здание Дома культуры было построено в 1976 году. В 2021 году в рамках одной областной программы «Сельский дом культуры» был осуществлен капитальный ремонт Тимошинского ДК. После окончания ремонта на базе учреждения начала свою работу музейная комната «Вепсская кухня», созданная для ознакомления жителей деревни и гостей с традиционной кухней вепсского народа и национальными блюдами.</p><p>В здании Дома культуры проводятся мероприятия для разных категорий граждан, также ежегодно проходит фестиваль вепсской национальной культуры «Древо жизни».</p>', NULL, 'ctnk_babaevo@mail.ru', '[{"value": "79211344231", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/9aa09dbae874a92e46e432fd80a89a83.jpeg", "title": "Тимошино 1.jpg"}', '[{"url": "https://all.culture.ru/uploads/ace70c81984758e8c61553d21143dfc0.jpeg", "title": "Вепсская кухня.jpg"}]', NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Бабаевский этнокультурный центр»', 'Бабаевский район', 'Europe/Moscow', 'ул Советская,д.23 пом.1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,ул Советская,д.23 пом.1', NULL, 3501009049, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Вепсская кухня","networkId":"208862479","updateDate":"2023-02-08T13:11:25Z","createDate":"2023-02-08T13:11:25Z","accountId":45664,"postingGroupId":40011},{"network":"vk","name":"Комоневский ДК","networkId":"176344109","updateDate":"2023-04-11T13:23:12Z","createDate":"2023-04-11T13:23:12Z","accountId":45056,"postingGroupId":41671},{"network":"vk","name":"Тимошинский Дом культуры.","networkId":"140436219","updateDate":"2023-04-11T13:23:04Z","createDate":"2023-04-11T13:23:04Z","accountId":45056,"postingGroupId":41670},{"network":"vk","name":"Туризм Бабаевского района","networkId":"128647289","updateDate":"2023-04-11T13:22:56Z","createDate":"2023-01-22T04:16:35Z","accountId":45056,"postingGroupId":39284},{"network":"vk","name":"Фестиваль  вепсских игр \"Lapsiden v?ndod\"","networkId":"218337418","updateDate":"2023-02-08T13:11:35Z","createDate":"2023-02-08T13:11:35Z","accountId":45664,"postingGroupId":40012},{"network":"vk","name":"Этнокультурный центр Бабаевского района","networkId":"99489293","updateDate":"2023-04-11T13:22:45Z","createDate":"2023-01-22T04:16:17Z","accountId":45056,"postingGroupId":39283}]', 29145, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 122, "name": "Искусство", "sysName": "iskusstvo"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 59704, '[{"url":"https://www.culture.ru/institutes/60573/timoshinskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/63296pl","serviceName":"Афиша7"}]', 59704, NULL, NULL, NULL, '2022-01-22 17:22:40+03', '2025-04-17 10:36:15+03', '0101000020E61000004D4C1762F5174240FDF84B8BFA0C4E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Судский сельский Дом культуры', 'Череповецкий район', 'Europe/Moscow', 'ул Заводская,д 4', NULL, 'обл Вологодская,р-н Череповецкий,п Суда,ул Заводская,д 4', '{"type": "Point", "coordinates": [37.5986, 59.138699]}', '<p>Судский сельский Дом культуры был основан в 1970 году и принадлежал Судскому домостроительному комбинату. С ноября 1993 года и по сей день он входит в состав Судского социально-культурного объединения. </p><p>В учреждении действуют 20 клубных формирований для детей и взрослых, участниками которых являются 540 человек. Коллективы «Задоринка», «Ритм», «Сударушка» и «Резонанс» носят звание «Народный» и являются лауреатами и дипломантами областных и международных конкурсов. </p><p>Посещаемость мероприятий составляет 11 000 человек в год. Будучи открытым и общедоступным, Судский Дом культуры оказывает услуги максимально широкой аудитории, стремится соответствовать ожиданиям населения и является центром культурной и спортивной жизни поселка.</p>', 'https://sydskoesko.wixsite.com/mysite', 'sydskoesko@mail.ru', '[{"value": "78202652777", "comment": "тел./факс"}, {"value": "78202652715", "comment": "методический кабинет"}]', '{"url": "https://all.culture.ru/uploads/cd81e0bba331aec30be3e87afb8621c9.jpeg", "title": "y_8717fc86.jpg"}', '[{"url": "https://all.culture.ru/uploads/7eb3a6f0d6de585278cfad7673af7fce.jpeg", "title": "Zy3_dEEnH7E.jpg"}, {"url": "https://all.culture.ru/uploads/17095e9f238622b19d1a1bf389026e6a.jpeg", "title": "y_14798908.jpg"}, {"url": "https://all.culture.ru/uploads/36988fd9eacd6e0822ae7f7558876d8e.jpeg", "title": "y_df9cafe6.jpg"}, {"url": "https://all.culture.ru/uploads/6703c262c660052ef1ba34b105cabe79.jpeg", "title": "y_cb283ddb.jpg"}, {"url": "https://all.culture.ru/uploads/5a8672f7e2d326fd4b05e659c05059b6.jpeg", "title": "Изображение 153.jpg"}, {"url": "https://all.culture.ru/uploads/e96134ed8da0eb09722c34366187a5d8.jpeg", "title": "6w0zj0gpejI.jpg"}, {"url": "https://all.culture.ru/uploads/da4f0ee272dc375218757f0d1585dcf8.jpeg", "title": "deATiADsXf8.jpg"}]', NULL, 'Дворцы культуры и клубы', 'Муниципальное учреждение культуры Судское социально-культурное объединение', 'Череповецкий район', 'Europe/Moscow', 'Заводская,4', NULL, 'обл Вологодская,р-н Череповецкий,с/мо Судское сельское поселение,Заводская,4', NULL, 3523000089, 'mincult', 'Череповецкий район', 'Europe/Moscow', '[{"network":"vk","name":"МУК Судское СКО","networkId":"224672313","updateDate":"2024-09-12T14:49:36Z","createDate":"2024-09-12T14:49:36Z","accountId":51303,"postingGroupId":46146}]', 20223, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, NULL, '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "11:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 36488, '[{"url":"https://www.culture.ru/institutes/38327/sudskii-selskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/19911pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=d92632df-7200-4394-b69a-eeda7a8d8f08&shareType=venue","serviceName":"ФанТам"}]', 36488, NULL, NULL, NULL, '2018-10-29 15:25:05+03', '2025-04-30 13:34:54+03', '0101000020E61000005BB1BFEC9ECC4240747E8AE3C0914D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Кадуйский центр народной традиционной культуры и ремесел', 'Кадуйский район', 'Europe/Moscow', 'ул Строителей,д 5', NULL, 'обл Вологодская,р-н Кадуйский,п Хохлово,ул Строителей,д 5', '{"type": "Point", "coordinates": [37.40572214126587, 59.150057058887406]}', '<p>Кадуйский центр народной традиционной культуры и ремесел создан в сентябре 1994 года. Он занимается изучением и содействием восстановлению традиционной народной культуры. Располагается в Доме культуры поселка Хохлово, где занимает 6 помещений, и в отдельном здании Дома народных ремесел. В нем работают 13 человек. </p><p>При центре постоянно занимаются фольклорные коллективы «Сударушка» и «Веретенце», коллектив муниципального  клуба гармонистов. Образцовый детский фольклорный коллектив «Веретенце» является лауреатом всероссийских и международных фольклорных фестивалей. Для всех желающих открыты художественная студия «Гончарики», студия традиционных ремесел. Центр участвует в фольклорных праздниках и фестивалях на территории Кадуйского округа, огранизует праздники и фестивали. Ежегодно проводит фольклорно-этнографические экспедиции в западных районах Вологодской области.</p>', 'https://sites.google.com/site/kcntcr/about', 'kcntcr@gmail.com', '[{"value": "78174242559", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/fcd7652c9cef484832405b1193cf2271.jpg", "title": "3.jpg"}', '[{"url": "https://all.culture.ru/uploads/ff6518222fe6c2d137d344d2030ae0ac.jpg", "title": "80.jpg"}, {"url": "https://all.culture.ru/uploads/54ce5d1bab32947215f66631b0db2d3a.jpg", "title": "Rq7JlFO6JiU.jpg"}, {"url": "https://all.culture.ru/uploads/eb84a3c78b97b30e7aa4cb5311ad39c2.jpg", "title": "DSC_0914_2.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУК «Кадуйский центр народной традиционной культуры и ремесел»', 'Кадуйский район', 'Europe/Moscow', 'ул Строителей,д 5', NULL, 'обл Вологодская,р-н Кадуйский,п Хохлово,ул Строителей,д 5', NULL, 3510006870, 'mincult', 'Кадуйский район', 'Europe/Moscow', '[{"network":"vk","name":"Кадуйский районный фестиваль юных сказителей","networkId":"215277785","updateDate":"2022-12-14T11:48:22Z","createDate":"2022-12-14T11:48:22Z","accountId":10507,"postingGroupId":38305},{"network":"vk","name":"Кадуйский центр народной традиционной культуры","networkId":"73205523","updateDate":"2021-05-21T10:06:03Z","createDate":"2021-05-21T10:06:03Z","accountId":10507,"postingGroupId":34536},{"network":"ok","name":"Культура.Кадуй","networkId":"61103236120724","updateDate":"2022-04-29T08:50:22Z","createDate":"2022-04-29T08:50:22Z","accountId":41664,"postingGroupId":36735}]', 16749, '[{"id": 39, "name": "Для детей", "sysName": "dlya-detey"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "19:00:00", "from": "08:00:00"}', '{"to": "19:00:00", "from": "08:00:00"}', '{"to": "19:00:00", "from": "08:00:00"}', '{"to": "19:00:00", "from": "08:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35982, '[{"url":"https://www.culture.ru/institutes/36541/kaduiskii-centr-narodnoi-tradicionnoi-kultury-i-remesel","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kaduy/dvorcy-kultury-i-kluby/19649pl","serviceName":"Афиша7"}]', 35982, NULL, NULL, NULL, '2018-10-03 11:18:22+03', '2025-04-22 10:09:55+03', '0101000020E6100000000000B4EEB34240493AD81135934D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Центр культуры «Вытегра»', 'Вытегорский район', 'Europe/Moscow', 'пр-кт Ленина,д 5а', NULL, 'обл Вологодская,р-н Вытегорский,г Вытегра,пр-кт Ленина,д 5а', '{"type": "Point", "coordinates": [36.448307, 61.006411]}', '<p>Дата основания Центра культуры «Вытегра» – 22 декабря 2005 года. Учреждение предоставляет населению разнообразные услуги социально-культурного, просветительского и развлекательного характера. </p><p> В концертном зале проводятся различные мероприятия: концерты, спектакли, вокальные, танцевальные и театральные конкурсы, фестивали, торжественная часть последних звонков и выпускных, подростковые дискотеки, вечера отдыха для людей пожилого возраста, игровые программы для детей, общественные собрания для обсуждения социальных вопросов. Также в зале проходят репетиции танцевальных, вокальных и театральных взрослых и детских коллективов.</p><p>В мастерской проходят занятия детских клубных формирований по аппликации и рисованию, лепке из теста и глины. Также проводятся мастер-классы по лепке из глины и росписи готовых глиняных поделок.</p>', 'http://ckvytegra.vlg.muzkult.ru', 'gdkvytegra@mail.ru', '[{"value": "78174621195", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/9414d1152612969156adc774bdab6b09.jpg", "title": "z2U-Ho5VPdA.jpg"}', '[{"url": "https://all.culture.ru/uploads/efca44ba4a751b538536090b2641fdc8.jpg", "title": "skyVVqpFeG8.jpg"}, {"url": "https://all.culture.ru/uploads/6ce6a0c7f62c250e04718a8f01ef7131.jpg", "title": "HohjXmLkmj8.jpg"}, {"url": "https://all.culture.ru/uploads/bd990f2e7bbe8d0887221f96c8d4f864.jpg", "title": "M1fSgkxh68M.jpg"}]', NULL, 'Дворцы культуры и клубы', 'БУК «ЦК «Вытегра»', 'Вытегорский район', 'Europe/Moscow', 'пр-кт Ленина,5а', NULL, 'обл Вологодская,р-н Вытегорский,г Вытегра,пр-кт Ленина,5а', NULL, 3508006255, 'mincult', 'Вытегорский район', 'Europe/Moscow', '[{"network":"vk","name":"БУК \"Центр Культуры \"Вытегра\"","networkId":"105546668","updateDate":"2023-04-17T12:25:18Z","createDate":"2023-04-17T12:25:18Z","accountId":47211,"postingGroupId":41806}]', 20279, '[{"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "21:00:00", "from": "08:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "20:00:00", "from": "17:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78646, '[{"url":"https://afisha7.ru/vytegra/dvorcy-kultury-i-kluby/99245pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/91518/centr-kultury-vytegra","serviceName":"Культура.рф"}]', 78646, NULL, NULL, NULL, '2023-04-05 10:02:51+03', '2025-05-07 12:38:19+03', '0101000020E6100000B0C8AF1F62394240D6AA5D13D2804E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Марковский дом культуры', 'Сокольский район', 'Europe/Moscow', 'д 9', NULL, 'обл Вологодская,р-н Сокольский,д Марковское,д 9', '{"type": "Point", "coordinates": [40.45592277350226, 59.430196976403586]}', '<p>Марковский дом культуры начал свою работу в 1988 году, а в 2018 году вошел в состав Центра народной культуры и художественных ремесел «Сокольский».</p><p> Здесь проводятся поселенческие мероприятия организационного, информационного, спортивного и культурного характера. Кроме того, ведется работа с пожилыми людьми, ветеранами труда и Великой Отечественной войны, тружениками тыла, с детьми и молодыми семьями. </p><p>Проводятся календарные праздники, выпускные, вечера отдыха, концертные программы, торжественные и юбилейные вечера, ярмарки. На базе учреждения работают 13 клубных формирований, из них 2 – на платной основе. Клубные формирования посещают 244 участника. </p>  <p><span></span></p>', NULL, 'mr.ksc@yandex.ru', '[{"value": "78173351167"}]', '{"url": "https://all.culture.ru/uploads/b248668cf46b62ab00383cf67146634f.jpg", "title": "марк.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'БУК СМО ЦНКИХР «Сокольский»', 'Сокольский район', 'Europe/Moscow', 'ул Советская,д 16', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,ул Советская,д 16', NULL, 3527011797, 'mincult', 'Сокольский район', 'Europe/Moscow', NULL, 15137, NULL, NULL, NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77654, '[{"url":"https://afisha7.ru/sokol/dvorcy-kultury-i-kluby/96873pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/90509/markovskii-dom-kultury","serviceName":"Культура.рф"}]', 77654, NULL, NULL, NULL, '2023-03-13 12:01:47+03', '2025-05-15 16:05:27+03', '0101000020E6100000CFD86CAD5B3A4440E93ECCB110B74D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Воробьевский дом культуры', 'Сокольский район', 'Europe/Moscow', 'ул Центральная,д 2', NULL, 'обл Вологодская,р-н Сокольский,д Воробьево,ул Центральная,д 2', '{"type": "Point", "coordinates": [40.884745, 59.625609]}', '<p>Воробьевский дом культуры начал свою работу в 1972 году, а в 2018 году вошел в состав Центра народной культуры и художественных ремесел «Сокольский». </p><p><span>Приоритетными<span> </span>направлениями деятельности являются сохранение традиционной народной культуры на основе местного фольклорного материала; работа с пожилыми людьми, ветеранами труда и Великой Отечественной войны, тружениками тыла; работа с детьми, молодыми<span> </span>семьями. </span></p><p><span>Проводятся календарные праздники, выпускные, вечера отдыха, концертные программы, торжественные и юбилейные вечера, ярмарки. </span><span>Н</span>а базе учреждения работают 14 клубных формирований, из них 2 – на платной основе. Клубные формирования посещают 263 участника. </p> ', NULL, 'dk.vorobevo@mail.ru', '[{"value": "78173342140"}]', '{"url": "https://all.culture.ru/uploads/7b9118d5a18d26a47eb8b189379557c8.jpg", "title": "воробьево.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'БУК СМО ЦНКИХР «Сокольский»', 'Сокольский район', 'Europe/Moscow', 'ул Советская,д 16', NULL, 'обл Вологодская,р-н Сокольский,г Сокол,ул Советская,д 16', NULL, 3527011797, 'mincult', 'Сокольский район', 'Europe/Moscow', NULL, 15137, NULL, NULL, NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 77653, '[{"url":"https://www.culture.ru/institutes/90511/vorobevskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/sokol/dvorcy-kultury-i-kluby/96872pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=15c8d258-6aa1-4dcc-9768-6f57b13ef2b9&shareType=venue","serviceName":"ФанТам"}]', 77653, NULL, NULL, NULL, '2023-03-13 11:52:33+03', '2025-05-15 16:05:05+03', '0101000020E61000005726FC523F714440A88AA9F413D04D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Полутовский клуб', 'Великоустюгский район', 'Europe/Moscow', 'ул Луговая,д 1', NULL, 'обл Вологодская,р-н Великоустюгский,д Полутово,ул Луговая,д 1', '{"type": "Point", "coordinates": [46.431294, 60.864607]}', '<p>На базе Дома культуры д. Полутово работают три клубных формирования: вокальный ансамбль «Сударушка», вокальный коллектив «Притяжение», танцевальный коллектив «Затмение». </p><p>В клубных формированиях занимается 24 человека в возрасте от 7 до 75 лет (на бесплатной основе).</p><p> </p><p>Услуги, оказываемые в учреждении: концертные, конкурсные, развлекательные, познавательные программы.</p><p>Предоставление платных услуг: аренда помещения, концерты, молодежные дискотеки.</p><p> Работа клуба направлена на сохранение и развитие разнообразных форм самодеятельного художественного творчества, в том числе посредством организации деятельности самодеятельных коллективов, организации досуга населения с учетом различных категорий и возрастов.</p>', 'http://www.dciskrasavino.ru', 'dia06091999@gmail.com', '[{"value": "79991681029"}]', '{"url": "https://all.culture.ru/uploads/9363827bc0e2431c3772b4d687730f5f.jpg", "title": "8Vtgy4XSYFY.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Центр культурного развития г. Красавино»', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 152', NULL, 'обл Вологодская,р-н Великоустюгский,г Красавино,пр-кт Советский,д 152', NULL, 3526008640, 'mincult', 'Великоустюгский район', 'Europe/Moscow', '[{"network":"vk","name":"Дом культуры и спорта г.Красавино","networkId":"33505837","updateDate":"2018-09-03T11:42:38Z","createDate":"2018-09-03T11:42:38Z","accountId":22303,"postingGroupId":19717},{"network":"vk","name":"Народная хореографическая студия \"Улыбка\"(г.Крас","networkId":"5759262","updateDate":"2018-09-03T11:43:10Z","createDate":"2018-09-03T11:43:10Z","accountId":22303,"postingGroupId":19718},{"network":"vk","name":"Просветительский центр \"Светоч\" ДКиС г.Красавино","networkId":"115057099","updateDate":"2018-09-03T11:44:09Z","createDate":"2018-09-03T11:44:09Z","accountId":22303,"postingGroupId":19720}]', 20579, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, NULL, '{"to": "20:00:00", "from": "17:00:00"}', NULL, '{"to": "20:00:00", "from": "17:00:00"}', NULL, '{"to": "18:00:00", "from": "15:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 75350, '[{"url":"https://afisha7.ru/velikiy-ustyug/dvorcy-kultury-i-kluby/91583pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/88304/polutovskii-klub","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=e8f655f0-95f0-4d1e-a701-6273656c70b5&shareType=venue","serviceName":"ФанТам"}]', 75350, NULL, NULL, NULL, '2023-01-25 12:06:09+03', '2025-05-06 10:20:29+03', '0101000020E6100000037B4CA43437474043723271AB6E4E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Межпоселенческий центральный дом культуры п. Тоншалово', 'Череповецкий район', 'Europe/Moscow', 'пл Труда,д 3', 'авт. № 122', 'обл Вологодская,р-н Череповецкий,п Тоншалово,пл Труда,д 3', '{"type": "Point", "coordinates": [37.947964, 59.189462]}', '<p><span>В Межпоселенческом центральном доме культуры работают 24 клубных формирования. Ведущими творческими коллективами являются образцовый художественный коллектив цирковая студия «Карабас Барабас, образцовый художественный коллектив вокальный ансамбль «Веснушки», народный хор ветеранов «Любава», театральный кружок «Крыжовник», вокально-эстрадный ансамбль «Забияки», вокальный ансамбль «Юность», студия танца «Манго», секция карате, фитнес для детей и фитнес для взрослых.<br /> </span></p><p><span>Коллектив учреждения является организатором районных и областных мероприятий, конкурсов и фестивалей детского и юношеского творчества. В учреждении реализуются проекты для детей и взрослых, самые известные среди них – «Песня детям», «Даешь молодежь!», «Взрослые и дети», «Не стареют душой ветераны», «Я здесь живу, и край мне этот дорог», «Победа деда – моя победа», открытый районный праздник «Играй, гармонь череповецкая».</span><span> </span></p>', 'http://dkcher.ru', 'mtsdkcherrayon@yandex.ru', '[{"value": "78202694030", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/f705fca59d1be17d7e5f7e3cf2e84302.jpg", "title": "VMylwWBiSKA.jpg"}', '[{"url": "https://all.culture.ru/uploads/7430e452c472fa16bb92b40cc56e3d11.jpg", "title": "0Zz0xbgBIAJiXS1D8hDrGZ-nJ50m445RGF2J-3Bj4Ul8lyKz_HVeQUPDealMXx5aZgmGtR_RXb48tvllMBmJQhg4.jpg"}, {"url": "https://all.culture.ru/uploads/c75f8c7415f01604851d2465f1c32f26.jpg", "title": "1.jpg"}, {"url": "https://all.culture.ru/uploads/4c4666ab57911dd001ce762b62dec51d.jpg", "title": "AT13jmY1SzrDq-i65Bx1qtuYTqBbqDOXXJWzRJ4yXr7TYEZ_vcbubKtLQ6aiNs8sjh6aBxHXd7Q1MMZ5ykzYFdNK.jpg"}, {"url": "https://all.culture.ru/uploads/56f6e2e0c13038fa930566cc444e5ada.jpg", "title": "_n2Tp0eFj6A.jpg"}, {"url": "https://all.culture.ru/uploads/01b7f52a43e8119fbd219fa63a34b041.jpg", "title": "_cjndvjNZe4.jpg"}, {"url": "https://all.culture.ru/uploads/c58b3eeb4b8e72768c04019df9e58eef.jpg", "title": "9urZhW6ZDHs.jpg"}, {"url": "https://all.culture.ru/uploads/dac344fa238fc352c998d8c723d70e8c.jpg", "title": "F-Or0XrxfZ_J-Lewi1InPx8zrtdKa1V9beCxOUPW6HiG3ePsVaehryMldVe0dnFLkRVRO1dOOOg3Ku2Hf_h32mhh.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МУК «Межпоселенческий центральный дом культуры»', 'Череповецкий район', 'Europe/Moscow', 'Труда,3', NULL, 'обл Вологодская,р-н Череповецкий,с/мо Тоншаловское сельское поселение,Труда,3', NULL, 3523014490, 'mincult', 'Череповецкий район', 'Europe/Moscow', '[{"network":"vk","name":"Дом Культуры Тоншалово","networkId":"35492903","updateDate":"2018-10-03T07:26:57Z","createDate":"2018-10-03T07:26:57Z","accountId":22557,"postingGroupId":19948},{"network":"vk","name":"Культура Череповецкого района","networkId":"206861193","updateDate":"2022-11-24T11:37:01Z","createDate":"2022-11-24T11:37:01Z","accountId":22557,"postingGroupId":37541}]', 20217, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', '{"to": "21:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 73626, '[{"url":"https://www.culture.ru/institutes/86711/mezhposelencheskii-centralnyi-dom-kultury-p-tonshalovo","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/cherepovec/dvorcy-kultury-i-kluby/88649pl","serviceName":"Афиша7"}]', 73626, NULL, NULL, NULL, '2022-12-01 12:11:23+03', '2025-05-29 16:00:19+03', '0101000020E610000086E464E256F94240D9EA724A40984D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Васильевский клуб', 'Великоустюгский район', 'Europe/Moscow', 'ул Парковая,д 33', NULL, 'обл Вологодская,р-н Великоустюгский,с Васильевское,ул Парковая,д 33', '{"type": "Point", "coordinates": [46.46353010144745, 60.93159346223962]}', '<p> Васильевский клуб открылся в 1968 году. Основная деятельность направлена на сохранение и развитие разнообразных форм самодеятельного художественного творчества, в том числе посредством организации деятельности самодеятельных коллективов, организации досуга населения. Дом культуры проводит концертные, конкурсные, развлекательные, игровые, познавательные программы, литературно-музыкальные вечера, выставки. </p><p>На базе учреждения работают 8 клубных формирований: женский вокальный ансамбль «Нежность», вокальный ансамбль «Рябинушка», детский вокальный коллектив «Капельки», танцевальный коллектив для детей «Солнышко», танцевальный коллектив для подростков «Люкс», драматический кружок, кружок творческой деятельности «Самоделкин», спортивный кружок. В клубных формированиях занимаются 107 человек от 5 до 75 лет (на бесплатной основе).</p>', NULL, 'natasha35region@yandex.ru', '[{"value": "78173862477", "comment": ""}, {"value": "79211445721", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/fc73ba04052b1c9a55269eec43a4e932.jpeg", "title": "yXGeV_gUBvc.jpg"}', '[{"url": "https://all.culture.ru/uploads/0cf251b9434d215f1cd5b15361f5588b.jpeg", "title": "ek7YJ_9i40E.jpg"}, {"url": "https://all.culture.ru/uploads/ae0c3fabe4cebc88dbb0e07e72d24903.jpeg", "title": "bWPv5IjtfN4.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУК «Центр культурного развития г. Красавино»', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 152', NULL, 'обл Вологодская,р-н Великоустюгский,г Красавино,пр-кт Советский,д 152', NULL, 3526008640, 'mincult', 'Великоустюгский район', 'Europe/Moscow', '[{"network":"vk","name":"Дом культуры и спорта г.Красавино","networkId":"33505837","updateDate":"2018-09-03T11:42:38Z","createDate":"2018-09-03T11:42:38Z","accountId":22303,"postingGroupId":19717},{"network":"vk","name":"Народная хореографическая студия \"Улыбка\"(г.Крас","networkId":"5759262","updateDate":"2018-09-03T11:43:10Z","createDate":"2018-09-03T11:43:10Z","accountId":22303,"postingGroupId":19718},{"network":"vk","name":"Просветительский центр \"Светоч\" ДКиС г.Красавино","networkId":"115057099","updateDate":"2018-09-03T11:44:09Z","createDate":"2018-09-03T11:44:09Z","accountId":22303,"postingGroupId":19720}]', 20579, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "18:00:00", "from": "15:00:00"}', '{"to": "23:00:00", "from": "20:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 48224, '[{"url":"https://www.culture.ru/institutes/47753/vasilevskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/dvorcy-kultury-i-kluby/28256pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=9d8b936a-d9ea-4336-900b-f299f882f731&shareType=venue","serviceName":"ФанТам"}]', 48224, NULL, NULL, NULL, '2020-11-23 11:05:59+03', '2025-05-06 10:20:50+03', '0101000020E6100000D53651F4543B474048BE5E743E774E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Ломоватский клуб', 'Великоустюгский район', 'Europe/Moscow', 'ул Культуры,д 15', NULL, 'обл Вологодская,р-н Великоустюгский,п Ломоватка,ул Культуры,д 15', '{"type": "Point", "coordinates": [45.529754162734974, 61.124822760826625]}', '<p>Дом культуры был построен в 1960 году.</p><p>Его работа направлена на сохранение и развитие разнообразных форм самодеятельного художественного творчества, в том числе посредством организации деятельности самодеятельных коллективов, организации досуга населения с учетом различных категорий и возрастов.<br /></p><p><a></a>Дом культуры предоставляет широкий спектр услуг: концертные, конкурсные, развлекательные, игровые, познавательные программы, вечера отдыха, литературно-музыкальные вечера, выставки, спортивно-развлекательные программы, дискотеки, детские программы.</p><p>На базе учреждения работают 8 клубных формирований: спортивные клуб, две танцевальные детские группы, театральный кружок, вокальная группа «Околица», кружок вокального пения, детская группа «Затейники», вокально-инструментальный ансамбль. В клубных формированиях занимается 63 человек в возрасте от 5 до 76 лет (на бесплатной основе).</p>', 'http://www.dciskrasavino.ru', 'club_lomovatka@mail.ru', '[{"value": "79114473737"}]', '{"url": "https://all.culture.ru/uploads/fb6507e946258d09f3dc344b872257d8.jpeg", "title": "QcSyYcB-AWc.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Центр культурного развития г. Красавино»', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 152', NULL, 'обл Вологодская,р-н Великоустюгский,г Красавино,пр-кт Советский,д 152', NULL, 3526008640, 'mincult', 'Великоустюгский район', 'Europe/Moscow', '[{"network":"vk","name":"Дом культуры и спорта г.Красавино","networkId":"33505837","updateDate":"2018-09-03T11:42:38Z","createDate":"2018-09-03T11:42:38Z","accountId":22303,"postingGroupId":19717},{"network":"vk","name":"Народная хореографическая студия \"Улыбка\"(г.Крас","networkId":"5759262","updateDate":"2018-09-03T11:43:10Z","createDate":"2018-09-03T11:43:10Z","accountId":22303,"postingGroupId":19718},{"network":"vk","name":"Просветительский центр \"Светоч\" ДКиС г.Красавино","networkId":"115057099","updateDate":"2018-09-03T11:44:09Z","createDate":"2018-09-03T11:44:09Z","accountId":22303,"postingGroupId":19720}]', 20579, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 206, "name": "Народное творчество", "sysName": "narodnoe-tvorchestvo"}, {"id": 323, "name": "Исполнительское искусство", "sysName": "ispolnitelskoe-iskusstvo"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, NULL, NULL, NULL, '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "16:00:00", "from": "11:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 46841, '[{"url":"https://www.culture.ru/institutes/45626/lomovatskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/dvorcy-kultury-i-kluby/27152pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=fb191bdc-e094-495d-8237-adf307f5129c&shareType=venue","serviceName":"ФанТам"}]', 46841, NULL, NULL, NULL, '2020-09-28 11:10:19+03', '2025-05-06 09:58:50+03', '0101000020E6100000ECEE01FCCEC34640FDC53531FA8F4E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Культурно-досуговый центр «Забота»', 'Вологда', 'Europe/Moscow', 'ул Мальцева,д 20', NULL, 'обл Вологодская,г Вологда,ул Мальцева,д 20', '{"type": "Point", "coordinates": [39.878407, 59.220464]}', '<p>Культурно-досуговый центр «Забота» был создан 1 октября 2011 года. Здесь проводятся различные мероприятия: фестивали, конкурсы, выставки, концернтые программы и др.</p><p>В центре «Забота» работают более 70 кружков по различным направлениям:</p><ul><li>«Оздоровительный цигун», «Плейстик», «Скандинавская ходьба» – спортивное; </li><li>изостудии «Палитра», «Мир в красках», «Юный художник» – художественное; </li><li>ансамбли «Цыганочки», «Мы из джаза», «Менуэт» – хореографическое; </li><li>ансамбли «Хорошее настроение», «Поющие сердца», «Северяночка», «Вологодские напевы», «Букет», мужские вокальные ансамбли, народный самодеятельный коллектив хор «Гармония», народный самодеятельный коллектив хор ветеранов педагогического труда – вокальное;</li><li>театральная студия «Вдохновение», театральный клуб «КЛАД» – театральное;</li><li>«Сама себе кутюрье», театр игрушек «Веселые клубочки», мастерская «Кудесницы», «Вологодская коклюшка», «Вязание крючком», «Лоскутная мозаика», «Гильоширование» – декоративно-прикладное; </li><li>«Сластена», «Ландшафтный дизайн» – клубы по интересам;</li><li>«Компьютерная грамотность», «Современные гаджеты» – образовательное.</li></ul>', 'http://zabota.vlg.muzkult.ru', 'center_zabota@mail.ru', '[{"value": "78172762413", "comment": ""}, {"value": "78172723082", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/f05afa5ea74a99ad74b11d011e0e76ea.jpg", "title": "1 Мальцева, 20.jpg"}', '[{"url": "https://all.culture.ru/uploads/a8df9564345b7979658e35eb6a29f7f0.JPG", "title": "IMG_2137.JPG"}, {"url": "https://all.culture.ru/uploads/43b764eeead69d98b7e454b25ad99e1c.JPG", "title": "IMG_1845.JPG"}, {"url": "https://all.culture.ru/uploads/b33869cb288d2a09ee71480e3d84bc2e.JPG", "title": "IMG_1896.JPG"}]', NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Культурно-Досуговый Центр «Забота»', 'Вологда', 'Europe/Moscow', 'ул Мальцева,д 20', NULL, 'обл Вологодская,г Вологда,ул Мальцева,д 20', NULL, 3525266824, 'mincult', 'Вологда', 'Europe/Moscow', '[{"network":"vk","name":"Культурно-досуговый центр \"Забота\" г. Вологда","networkId":"62733448","updateDate":"2023-01-26T09:20:29Z","createDate":"2023-01-26T09:20:29Z","accountId":43357,"postingGroupId":39528}]', 20466, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 120, "name": "Общество", "sysName": "obshchestvo"}, {"id": 206, "name": "Народное творчество", "sysName": "narodnoe-tvorchestvo"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}]', '[{"hosting":"vk","id":"<iframe src=\"//vk.com/video_ext.php?oid=-62733448&id=456239040&hash=fc92b97af4a84958&hd=2\" width=\"853\" height=\"480\" frameborder=\"0\" allowfullscreen></iframe>"},{"hosting":"vk","id":"<iframe src=\"//vk.com/video_ext.php?oid=-62733448&id=456239068&hash=9ba37895f8f9d6c3&hd=2\" width=\"853\" height=\"480\" frameborder=\"0\" allowfullscreen></iframe>"},{"hosting":"vk","id":"<iframe src=\"//vk.com/video_ext.php?oid=-62733448&id=456239071&hash=cc2806e8da4d2184&hd=2\" width=\"853\" height=\"480\" frameborder=\"0\" allowfullscreen></iframe>"}]', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "08:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35397, '[{"url":"https://www.culture.ru/institutes/36284/kulturno-dosugovyi-centr-zabota","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/19347pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=1abdcc85-f73e-4129-851d-ba3cd88c6611&shareType=venue","serviceName":"ФанТам"}]', 35397, NULL, NULL, NULL, '2018-07-05 11:12:49+03', '2025-05-06 09:56:11+03', '0101000020E6100000EBC9FCA36FF0434001F9122A389C4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Филиал центра «Забота» на ул. Марии Ульяновой', 'Вологда', 'Europe/Moscow', 'ул Марии Ульяновой,д 6', 'маршрут № 19 – ост. «Библиотека им. Бабушкина»', 'обл Вологодская,г Вологда,ул Марии Ульяновой,д 6', '{"type": "Point", "coordinates": [39.890436, 59.220027]}', '<p>Филиал центра «Забота» открыл свои двери в 2012 году. Здесь проходят различные мероприятия центра «Забота». </p><p>Работают кружки спортивного, музыкального, хореографического направлений для людей старшего возраста:</p><ol><li>Спортивное направление – пилатес, общеоздоровительная дыхательная гимнастика, гимнастика по методике Ю. Попова «Живой позвоночник», настольный теннис, занятия на тренажерах, «Спорт в удовольствие», «Здоровая спина. Здоровые суставы», «Разумное тело».</li><li>Хореографическое направление – ансамбль бального танца «Серебряная стрекоза», ансамбли «Мы из джаза», «В вихре танца», «Задоринки» и «Забавушки», студия народного танца «Сударушка», бальные танцы.</li><li>Другие направления – восточная астрология.</li></ol>', 'http://zabota.vlg.muzkult.ru', NULL, '[{"value": "78172721163", "comment": ""}, {"value": "78172721044"}]', '{"url": "https://all.culture.ru/uploads/b2238369c69536e03708a1264eef7494.jpg", "title": "1 М. Ульяновой, 6.jpg.jpg"}', '[{"url": "https://all.culture.ru/uploads/554f531a29635886b35c242f0bc2c9ae.JPG", "title": "IMG_4972.JPG"}, {"url": "https://all.culture.ru/uploads/43c7be57e14bd9f8edef1e0f4832b3ad.JPG", "title": "P1070246.JPG"}, {"url": "https://all.culture.ru/uploads/99c7468e52c8d8651ebd70a5eda80e3b.JPG", "title": "IMG_3123.JPG"}, {"url": "https://all.culture.ru/uploads/378ff65a9e6baaad50763ce5866171f9.JPG", "title": "IMG_3129.JPG"}]', NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Культурно-Досуговый Центр «Забота»', 'Вологда', 'Europe/Moscow', 'ул Мальцева,д 20', NULL, 'обл Вологодская,г Вологда,ул Мальцева,д 20', NULL, 3525266824, 'mincult', 'Вологда', 'Europe/Moscow', '[{