eborder=\"0\" allowfullscreen></iframe>"},{"hosting":"vk","id":"<iframe src=\"//vk.com/video_ext.php?oid=-62733448&id=456239027&hash=85869a0cac5a1ec9&hd=2\" width=\"853\" height=\"480\" frameborder=\"0\" allowfullscreen></iframe>"}]', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', '{"to": "18:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 35160, '[{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/19202pl","serviceName":"Афиша7"},{"url":"https://www.culture.ru/institutes/36163/filial-centra-zabota-na-ul-marii-ulyanovoi","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=01d39b07-3e75-4be8-895a-c4ad04c07cd7&shareType=venue","serviceName":"ФанТам"}]', 35160, NULL, NULL, NULL, '2018-06-05 12:10:05+03', '2025-05-06 09:57:50+03', '0101000020E61000002D978DCEF9F14340569E40D8299C4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Куйский дом культуры', 'Бабаевский район', 'Europe/Moscow', 'д 3', NULL, 'обл Вологодская,р-н Бабаевский,д Кийно,д 3', '{"type": "Point", "coordinates": [36.294138, 60.28279]}', '<p>Куйский дом культуры организует разнообразные мероприятия для жителей окрестных деревень: концерты, вечера отдыха, спортивные программы и другие культурные события. С сентября 2024 года учреждение вошло в состав Этнокультурного центра Бабаевского района. Особое внимание уделяется сохранению и популяризации вепсской культуры.</p><p>В доме культуры действуют две музейные комнаты, посвященные культуре малочисленного коренного народа – вепсов. Один из музеев посвящен образу жизни вепсского рыбака, второй воссоздает традиционный быт вепсской избы.</p><p>Ежегодно на базе Куйского дома культуры проходит межшкольный фестиваль знатокам вепсского языка «Живой родник». Он активно участвует в региональном этнокультурном движении, представляя свои проекты на таких фестивалях, как «Древо жизни», «Земля родная», «Язык родной, дружи со мной» и других.</p>', NULL, NULL, '[{"value": "79211344231", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/3f234ba2b3bc2400aca4f0c459a2a600.jpg", "title": "tBBz2l1uwBI.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Бабаевский этнокультурный центр»', 'Бабаевский район', 'Europe/Moscow', 'ул Советская,д.23 пом.1', NULL, 'обл Вологодская,р-н Бабаевский,г Бабаево,ул Советская,д.23 пом.1', NULL, 3501009049, 'mincult', 'Бабаевский район', 'Europe/Moscow', '[{"network":"vk","name":"Вепсская кухня","networkId":"208862479","updateDate":"2023-02-08T13:11:25Z","createDate":"2023-02-08T13:11:25Z","accountId":45664,"postingGroupId":40011},{"network":"vk","name":"Комоневский ДК","networkId":"176344109","updateDate":"2023-04-11T13:23:12Z","createDate":"2023-04-11T13:23:12Z","accountId":45056,"postingGroupId":41671},{"network":"vk","name":"Тимошинский Дом культуры.","networkId":"140436219","updateDate":"2023-04-11T13:23:04Z","createDate":"2023-04-11T13:23:04Z","accountId":45056,"postingGroupId":41670},{"network":"vk","name":"Туризм Бабаевского района","networkId":"128647289","updateDate":"2023-04-11T13:22:56Z","createDate":"2023-01-22T04:16:35Z","accountId":45056,"postingGroupId":39284},{"network":"vk","name":"Фестиваль  вепсских игр \"Lapsiden v?ndod\"","networkId":"218337418","updateDate":"2023-02-08T13:11:35Z","createDate":"2023-02-08T13:11:35Z","accountId":45664,"postingGroupId":40012},{"network":"vk","name":"Этнокультурный центр Бабаевского района","networkId":"99489293","updateDate":"2023-04-11T13:22:45Z","createDate":"2023-01-22T04:16:17Z","accountId":45056,"postingGroupId":39283}]', 29145, '[{"id": 350, "name": "Народная культура", "sysName": "narodnaya-kultura"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "18:00:00", "from": "10:00:00"}', NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 88538, '[{"url":"https://www.culture.ru/institutes/101573/kuiskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/babaevo/dvorcy-kultury-i-kluby/132715pl","serviceName":"Афиша7"}]', 88538, NULL, NULL, NULL, '2025-04-14 10:13:41+03', '2025-07-11 15:58:22+03', '0101000020E610000063416150A625424063D1747632244E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Вотчинский клуб', 'Вологодский район', 'Europe/Moscow', 'д 44', NULL, 'обл Вологодская,р-н Вологодский,д Севастьяново,д 44', '{"type": "Point", "coordinates": [39.161606, 59.55932]}', '<p>Дом культуры был построен в 1969 году в деревне Вотча, где находилась школа, почта, библиотека, сельсовет. Но в 2007 году здание закрыли, и 1 декабря 2011 года клуб был переведен в здание бывшей администрации Вотчинского сельсовета в деревню Севастьяново.<br /></p> <p><span><span> Сейчас в клубе </span>функционируют десять клубных формирований для взрослых и детей, направления различные – вокал, театральное творчество, танцы, спорт, рукоделие. Итогом<span> </span>кружковой работы являются <span> </span>концерты к каждому значимому празднику. Творческие работы детского кружка «Умелые ручки» являются украшением всех мероприятий. </span></p> <p><span>Коллектив Дома культуры участвует во всех поселенческих фестивалях для детей и взрослых, народном празднике «Заговенье», совместных с другими учреждениями культуры концертах. Наиболее значимыми мероприятиями для населения являются: День деревни Севастьяново, музыкальные спектакли, концертные программы к различным праздникам, таким как День пожилого человека, 8 Марта, День защитников Отечества, День Победы, День семьи, любви и верности. </span></p> <p><span> </span></p> <p><span> </span></p> <p><span> </span></p>', NULL, NULL, '[{"value": "78172555041"}]', '{"url": "https://all.culture.ru/uploads/680eda7bc1fb6a5f9c2be68f8092e0ef.jpg", "title": "sCPlKsB5Qwc.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение культуры «Новленский Дом культуры»', 'Вологодский район', 'Europe/Moscow', 'ул Советская,д 30', NULL, 'обл Вологодская,р-н Вологодский,с Новленское,ул Советская,д 30', NULL, 3507303368, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14125, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 59, "name": "Ансамбли", "sysName": "ansambli"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', '{"to": "18:00:00", "from": "14:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78236, '[{"url":"https://www.culture.ru/institutes/91132/votchinskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/135662pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=f9eba7c5-078e-4b90-aca6-0e9d9bc5a268&shareType=venue","serviceName":"ФанТам"}]', 78236, NULL, NULL, NULL, '2023-03-27 14:14:42+03', '2025-07-11 14:12:50+03', '0101000020E61000002F6B6281AF944340D6FF39CC97C74D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Кипеловский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Железнодорожная,д 14', NULL, 'обл Вологодская,р-н Вологодский,п Кипелово,ул Железнодорожная,д 14', '{"type": "Point", "coordinates": [39.1431, 59.235552]}', '<p><span>Свою историю Кипеловский дом культуры ведет с 2000 года.<span> Десять </span>лет поселок был вынужден обходиться без ДК, так как старый был закрыт из-за аварийного состояния. Силами общественности и администрации Кипеловского сельского совета было выкуплено здание старого универмага и переоборудовано в ДК. Общая площадь помещения составляет </span><span>402,5 кв. м. Зрительный зал рассчитан на 100 посадочных мест.</span><span></span></p> <p><span>В ДК успешно ведут работу 17 клубных формирований для детей и взрослых: ансамбль «Надежда», детский театральный кружок, драматический<span> </span>кружок для взрослых, вокальный ансамбль «Смайлики», творческий кружок «Чудо-ручки» и другие.<span> </span>Благодаря их деятельности здесь проводятся интересные и содержательные концертные программы, вечера отдыха, тематические конкурсы,<span> </span>развлекательно-игровые, спортивно-игровые программы<span> </span>как для детей, так и для взрослых, выставки и викторины. </span><span>Большой популярностью у зрителей пользуются театрализованные представления на Масленицу, мероприятия ко Дню защиты детей, Дню пожилого человека и Дню поселка.</span></p>', NULL, NULL, '[{"value": "78172552057"}]', '{"url": "https://all.culture.ru/uploads/ba7855b85e6551f505c1408b2dc5acd4.jpg", "title": "Кипеловский ДК здание.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение «Старосельский дом культуры»', 'Вологодский район', 'Europe/Moscow', 'д 12', NULL, 'обл Вологодская,р-н Вологодский,д Стризнево,д 12', NULL, 3507303248, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14112, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78233, '[{"url":"https://www.culture.ru/institutes/91106/kipelovskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=b6901788-b1ee-4316-9823-4c2d0da5a5d0&shareType=venue","serviceName":"ФанТам"}]', 78233, NULL, NULL, NULL, '2023-03-27 13:57:26+03', '2025-07-10 12:19:22+03', '0101000020E61000005F07CE1951924340F2406491269E4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Старосельский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Зеленая,д 12', NULL, 'обл Вологодская,р-н Вологодский,д Стризнево,ул Зеленая,д 12', '{"type": "Point", "coordinates": [39.293074, 59.195325]}', '<p>Дом культуры расположен в деревне Стризнево Вологодской области. Здание построено в 1990 году, состоит из двух этажей и имеет спортивный зал. Общая площадь сооружения – 1 750 кв. м, зрительный зал рассчитан на 300 зрителей. В зоне его обслуживания проживает около 950 человек, охватывая территорию 43 населенных пунктов. </p><p>На базе учреждения организовано функционирование 22 клубных формирований различного профиля. Для детей открыты кружки изобразительного искусства, прикладного и вокального творчества, патриотической и спортивной направленности. Люди старшего поколения уже более 15 лет посещают клуб ветеранов «Родничок», а также занимаются в кружке прикладного творчества «Рукодельница». </p><p>Регулярно проходят развлекательные и игровые программы, театрализованные праздники, концерты, вечера отдыха. Старосельский дом культуры служит площадкой для проведения мероприятий районного и областного значения, включая сходы граждан. С 2013 года здесь ежегодно проходит фестиваль духовно-патриотической музыки «Крещенский сочельник», постепенно приобретший статус межрайонного фестиваля православной культуры и традиций. Участниками фестиваля становятся творческие коллективы из Вологодской области, Вологды, Череповца, Великого Устюга и соседних районов.</p>', NULL, 'staroselskiy_dk@mail.ru', '[]', '{"url": "https://all.culture.ru/uploads/70446c7d69a3a5fd622e0bbb9d464790.jpg", "title": "6vUxnyTf4sI.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'Муниципальное бюджетное учреждение «Старосельский дом культуры»', 'Вологодский район', 'Europe/Moscow', 'д 12', NULL, 'обл Вологодская,р-н Вологодский,д Стризнево,д 12', NULL, 3507303248, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 14112, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "16:00:00", "from": "09:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "10:00:00"}', '{"to": "16:00:00", "from": "09:00:00"}', '{"to": "19:00:00", "from": "11:00:00"}', '{"to": "19:00:00", "from": "11:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78192, '[{"url":"https://www.culture.ru/institutes/91085/staroselskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/97914pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=3d661705-4bac-43ab-b455-00ecfa41ef67&shareType=venue","serviceName":"ФанТам"}]', 78192, NULL, NULL, NULL, '2023-03-24 11:55:06+03', '2025-07-11 11:29:02+03', '0101000020E610000069A7E67283A54340AC8BDB6800994D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Аристовский клуб', 'Великоустюгский район', 'Europe/Moscow', 'ул Виноградова,д 8', NULL, 'обл Вологодская,р-н Великоустюгский,д Аристово,ул Виноградова,д 8', '{"type": "Point", "coordinates": [46.401515, 60.76726]}', '<p>Клуб был построен в 1968 году в с/с Шемогодское. Поселение в те времена насчитывало более 2 тысяч человек, Дом культуры для многих был вторым домом. Проводились мероприятия по старым обычаям и традициям, масленичные и рождественские гулянья, колядки. Люди старшего поколения организовывали различные встречи, танцы, уделяли особое внимание кинопоказам по вечерам. Со временем стали проводить еще больше мероприятий для молодежи: КВН, танцы для различных возрастных групп, песенные конкурсы; открывались кружки.</p><p>Сейчас свою работу продолжают клубные формирования, проводятся разные мероприятия для людей всех возрастов. На сегодняшний день в клубе работают 4 клуба по интересам, количество участников – 37 человек. Возрастная категория – от 7 лет. Жители активно посещают проводимые в клубе встречи, концерты, праздники, а также занятия в клубных объединениях.</p><p> </p>', 'http://кдцву.рф', 'aristovodk@mail.ru', '[{"value": "78173865432", "comment": "Заведущая Соболева Людмила Владимировна"}, {"value": "78173865837", "comment": "Менеджер Жирохова Наталья Викторовна"}]', '{"url": "https://all.culture.ru/uploads/911d28dada3cacafa901d7ae74145271.jpg", "title": "raBRol-4VUw.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «Великоустюгский культурно-досуговый центр»', 'Великоустюгский район', 'Europe/Moscow', 'пр-кт Советский,д 101', NULL, 'обл Вологодская,р-н Великоустюгский,г Великий Устюг,пр-кт Советский,д 101', NULL, 3526015975, 'mincult', 'Великоустюгский район', 'Europe/Moscow', '[{"network":"vk","name":"\"Кузинский клуб\"","networkId":"170421267","updateDate":"2023-04-05T11:45:45Z","createDate":"2023-04-05T11:45:45Z","accountId":46589,"postingGroupId":41531},{"network":"vk","name":"\"Усть-Алек