network":"vk","name":"Парк культуры и отдыха /Великий Устюг/","networkId":"153198570","updateDate":"2023-04-05T11:46:08Z","createDate":"2023-04-05T11:46:08Z","accountId":46589,"postingGroupId":41532},{"network":"vk","name":"Полдарский клуб","networkId":"206228726","updateDate":"2023-07-05T08:23:33Z","createDate":"2023-07-05T08:23:33Z","accountId":46589,"postingGroupId":42639},{"network":"vk","name":"Театр Деда Мороза","networkId":"199304892","updateDate":"2020-11-03T05:54:59Z","createDate":"2020-11-03T05:54:59Z","accountId":21245,"postingGroupId":30273}]', 20409, '[{"id": 24, "name": "История", "sysName": "istoriya"}, {"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 28, "name": "Литература", "sysName": "literatura"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 392, "name": "Книги", "sysName": "knigi"}, {"id": 751, "name": "Культура для школьников", "sysName": "kultura-dlya-shkolnikov"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', '[{"hosting":"vk","id":"<iframe src=\"https://vk.com/video_ext.php?oid=-97047864&id=456239061&hash=ed29c845a0e885e8&hd=2\" width=\"853\" height=\"480\"></iframe>"},{"hosting":"vk","id":"<iframe src=\"https://vk.com/video_ext.php?oid=-97047864&id=456239056&hash=3d9e8bf124fcfb81&hd=2\" width=\"853\" height=\"480\"></iframe>"},{"hosting":"vk","id":"<iframe width=\"607\" height=\"360\" src=\"https://www.youtube.com/embed/AjFU-fx8htE\"></iframe>"},{"hosting":"vk","id":"<iframe src=\"https://vk.com/video_ext.php?oid=-53437447&id=456242161&hash=eea4ad7fb6b0eb28&hd=2\" width=\"853\" height=\"480\"></iframe>"}]', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "15:00:00", "from": "10:00:00"}', '{"to": "23:00:00", "from": "20:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 73510, '[{"url":"https://www.culture.ru/institutes/86614/teplogorskii-klub","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/velikiy-ustyug/dvorcy-kultury-i-kluby/96574pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=52cfae86-2798-4211-aafa-b3fabea31316&shareType=venue","serviceName":"ФанТам"}]', 73510, NULL, NULL, NULL, '2022-11-29 15:12:03+03', '2026-05-12 10:54:52+03', '0101000020E6100000F17EDC7EF9564740C784984BAA3A4E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Нюксенский центр культурного развития', 'Нюксенский район', 'Europe/Moscow', 'ул Советская,стр 14', 'строение 1', 'обл Вологодская,р-н Нюксенский,с Нюксеница,ул Советская,стр 14', '{"type": "Point", "coordinates": [44.243142, 60.409515]}', '<p>  Строительство Дома культуры в Нюксенице велось с 2019 года и было сдано в эксплуатацию в 2025 году. В этом же здании так же находится библиотека, музей и даже ЗАГС. </p><p>В настоящее время на базе учреждения работают 28 клубных формирований, количество участников – 513 человек. Три коллектива имеют звание народного: народный хор ветеранов «Вдохновение», народный танцевальный коллектив «Рябиновые бусы», народный вокальный ансамбль «Россияночка». В 2022 году студия современного и народного танца «Артданс» получила звание образцового коллектива, в студии 111 участников. </p><p>За 2024 год в Центре культурного развития проведено 420 мероприятий, количество зрителей – 33 477 человек. Это концерты, спектакли, игровые программы, вечера отдыха, дискотеки, театрализованные представления.</p> <p></p>', 'http://нюкскульт.рф/', 'nksinfo@yandex.ru', '[{"value": "78174728048", "comment": ""}, {"value": "79215361084", "comment": ""}]', '{"url": "https://all.culture.ru/uploads/2892121c628b9ebfb7a44296aff92532.jpg", "title": "P08SfER2gp2qqKLALIs3SYBllWHJZrFFLy_GJTQ3ted7DRlNLcfpv7pDX_DqyudUj1gvcqeQ3--nUjmiQyaY30bH.jpg"}', '[{"url": "https://all.culture.ru/uploads/4d7afc6c3de335b05f42166b3bd80f44.jpg", "title": "LiWBvTO_W90.jpg"}, {"url": "https://all.culture.ru/uploads/5fc4ace4aa8d0ccf54821911651298f4.jpg", "title": "20210803_160355.jpg"}, {"url": "https://all.culture.ru/uploads/3d53d02a47da3eeded8f25f8bcd11a4f.jpg", "title": "jQ0ri3_qw0m5OrAyor_BqNZk76DWdZXlDvlb8XEdaQYe02udnj1erV37Gmdj4EaFAMGO1iNpMXz1LhcABGAp_x3U.jpg"}, {"url": "https://all.culture.ru/uploads/3c107bf2e6b58d3cf002449228c26038.jpg", "title": "drsqb2erGmM.jpg"}, {"url": "https://all.culture.ru/uploads/db22b4e81747ad944d17b9feca8032e4.jpg", "title": "0o3_4YEOQcU.jpg"}, {"url": "https://all.culture.ru/uploads/18d6af56a53a928545d2e5e7a1017615.jpg", "title": "3czMzBOrfAI.jpg"}, {"url": "https://all.culture.ru/uploads/d911b8d31e6d21bc46a298c8f52bc853.jpg", "title": "YNX-FcBO9NoYFOSpFJ3BAZhacfw83kosVB-C1I_ydt7-_hPHnRFshiFAzEbHbIqukjwqxxoDYrSacFEjRY7h1qT3.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУК «Нюксенский районный Центр культурного развития»', 'Нюксенский район', 'Europe/Moscow', 'ул Советская,д 14', NULL, 'обл Вологодская,р-н Нюксенский,с Нюксеница,ул Советская,д 14', NULL, 3515004523, 'mincult', 'Нюксенский район', 'Europe/Moscow', '[{"network":"vk","name":"Нюксенский Центр культурного развития","networkId":"50897708","updateDate":"2025-12-25T06:44:01Z","createDate":"2025-12-25T06:44:01Z","accountId":54377,"postingGroupId":49033}]', 17261, '[{"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "17:00:00", "from": "08:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 34787, '[{"url":"https://www.culture.ru/institutes/69770/nyuksenskii-centr-kulturnogo-razvitiya","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/nyuksenica/dvorcy-kultury-i-kluby/99783pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=51750f42-0523-472b-9f2a-2fc328424cdd&shareType=venue","serviceName":"ФанТам"}]', 34787, NULL, NULL, NULL, '2018-04-27 17:19:49+03', '2026-05-28 11:28:30+03', '0101000020E61000005B24ED461F1F4640581CCEFC6A344E40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Заречный дом культуры', 'Кичменгско-Городецкий район', 'Europe/Moscow', 'ул Заречная,д 50', NULL, 'обл Вологодская,р-н Кичменгско-Городецкий,с Кичменгский Городок,ул Заречная,д 50', '{"type": "Point", "coordinates": [45.78227, 59.977256]}', '<p>Заречный дом культуры начал работу в феврале 1986 года. С 1 января 2020 года является филиалом ЦДК.<br></p><p>Заречный дом культуры является единственным учреждением культурно-досугового типа, расположенным в заречной части села Кичменгский Городок. В зоне обслуживания расположены Первомайская средняя школа и два дошкольных учреждения – детский сад комбинированного вида «Аленушка», детский сад «Солнышко». В здании ДК также размещается Заречная общедоступная библиотека.</p><p> На базе Заречного дома культуры располагается Дом военно-патриотического общественного движения «Юнармия». Дети-юнармейцы активно участвуют в патриотических акциях, в юнармейских конкурсах районного, областного и регионального масштаба.</p><p> С 2019 года Заречный дом культуры является опорным представительством по развитию добровольчества и волонтерства на территории района.</p> <p> </p>', NULL, 'kichmenzdk@mail.ru', '[{"value": "78174021739", "comment": "заведующая Копосова Татьяна Николаевна"}]', '{"url": "https://all.culture.ru/uploads/2641c348875dd430ea402796ecfd6c1c.jpg", "title": "JKpwDIcKPMY.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'БУК «Районный дом культуры»', 'Кичменгско-Городецкий район', 'Europe/Moscow', 'ул Центральная', NULL, 'обл Вологодская,р-н Кичменгско-Городецкий,с Кичменгский Городок,ул Центральная', NULL, 3512005007, 'mincult', 'Кичменгско-Городецкий район', 'Europe/Moscow', NULL, 20268, '[{"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', '{"to": "17:00:00", "from": "09:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 34755, '[{"url":"https://www.culture.ru/institutes/35943/zarechnyi-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/kichmengskiy-gorodok/dvorcy-kultury-i-kluby/19053pl","serviceName":"Афиша7"}]', 34755, NULL, NULL, NULL, '2018-04-25 14:16:14+03', '2026-06-08 16:15:25+03', '0101000020E61000002A52616C21E44640EEE87FB916FD4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Перьевский дом культуры', 'Вологодский район', 'Europe/Moscow', 'ул Пошехонская,д 1', NULL, 'обл Вологодская,р-н Вологодский,п Перьево,ул Пошехонская,д 1', '{"type": "Point", "coordinates": [39.77836898408408, 59.04308979242355]}', '<p style="">Дом культуры начал деятельность в августе 2022 года. </p> <p style=""> </p> <p style="">Сегодня на базе учреждения ведут деятельность клубные формирования для детей, молодежи и взрослых по различным направлениям (хореография, вокал, рисование, театральное искусство, нейробика, каллиграфия, робототехника, изучение языков). Это народный театр эстрады «Талантино», танцевальные коллективы «Веселые косички», «Созвездие», «Краса», «Ассорти», вокально-инструментальный дуэт «Утренний рассвет», вокальные коллективы «Алые паруса», «РОКовые», «Перьевчаночки» изостудия «Волшебная кисть», творческая мастерская «Рукодельница», студия творчества «Каллиграфия», группа «Нейробика» (аэробика для мозга).</p> <p style="">В Доме культуры проводятся мероприятия, посвященные праздничным и памятным датам, игровые и танцевальные программы. Творческие коллективы ДК неоднократно становились победителями и лауреатами различных областных и районных фестивалей и конкурсов.</p>', NULL, 'cultura35@mail.ru', '[{"value": "79005021577", "comment": "Марина Владимировна"}]', '{"url": "https://all.culture.ru/uploads/c07ec88768ed9d5cbadb010896b43044.jpg", "title": "Перьевский ДК здание август 2026г.jpg"}', '[{"url": "https://all.culture.ru/uploads/7996f2868866d5c20267993c828698d3.jpg", "title": "концерт 10 ноябрь 2025.jpg"}, {"url": "https://all.culture.ru/uploads/47bfdf1af4c9c6245e47506472fe00cd.jpg", "title": "концерт 8 ноябрь 2025.jpg"}, {"url": "https://all.culture.ru/uploads/539cba0c05f175b45506e2b99d3a6e40.jpg", "title": "концерт 5 ноябрь 2025.jpg"}, {"url": "https://all.culture.ru/uploads/4f9cc6a841489101e9fa7a88f3458738.jpg", "title": "концерт 4 ноябрь 2025.jpg"}, {"url": "https://all.culture.ru/uploads/97979ad3688c73c6c58e5bd971edb266.jpg", "title": "концерт 9 ноябрь 2025.jpg"}, {"url": "https://all.culture.ru/uploads/b00641fb77aec201848abe388919f7e7.jpg", "title": "концерт 6 ноябрь 2025.jpg"}, {"url": "https://all.culture.ru/uploads/e75949012b3c4e63a8937db453007368.jpg", "title": "концерт 11 ноябрь 2025.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУК ВМО «Центр культурного развития»', 'Вологодский район', 'Europe/Moscow', 'ул Ленина,д 50', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Ленина,д 50', NULL, 3525221703, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 26358, '[{"id": 27, "name": "Декоративно-прикладное искусство", "sysName": "dekorativno-prikladnoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 792, "name": "Участникам СВО", "sysName": "uchastnikam-svo"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 317, "name": "Для молодежи", "sysName": "dlya-molodezhi"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, '{"to": "20:00:00", "from": "14:00:00"}', '{"to": "20:00:00", "from": "14:00:00"}', '{"to": "20:00:00", "from": "14:00:00"}', '{"to": "20:00:00", "from": "14:00:00"}', '{"to": "20:00:00", "from": "14:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 78670, '[{"url":"https://www.culture.ru/institutes/91542/perevskii-dom-kultury","serviceName":"Культура.рф"},{"url":"https://afisha7.ru/vologda/dvorcy-kultury-i-kluby/99104pl","serviceName":"Афиша7"},{"url":"https://map.funtam.ru/offer/poi?showMainEvent=false&shareId=dd559acd-b81a-4c8d-b05f-702be0830eed&shareType=venue","serviceName":"ФанТам"}]', 78670, NULL, NULL, NULL, '2023-04-05 14:08:17+03', '2026-08-17 11:27:39+03', '0101000020E6100000526E4998A1E3434013A060F783854D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Дом культуры «Феникс» п. Федотово', 'Вологодский район', 'Europe/Moscow', 'д 36', NULL, 'обл Вологодская,р-н Вологодский,п Федотово,д 36', '{"type": "Point", "coordinates": [39.182276, 59.2059]}', '<p>Дом культуры «Феникс» был основан 26 декабря 2019 года. На сегодняшний день «Феникс» – это более 30 тысяч проведенных мероприятий: концертов, конкурсов, праздников, мастер-классов. В учреждении работают 28 клубных формирований, 5 танцевальных коллективов, вокальное отделение, театральная студия и кружки прикладного творчества.</p><p>Также в Доме культуры проходят гастрольные туры. В «Фениксе» выступали братья Пономаренко, ансамбль «Голубые береты», Геннадий Ветров, Ансамбль Русского Севера, Всероссийский фестиваль Гармонь России и фестиваль-марафон «Песни России» под руководством Надежды Бабкиной. <br /></p><p>Проект «Я русский. Наследие А. С. Попова» был реализован учреждением культуры «Феникс» в 2023 году. В 2024 году он занял 3-е место в номинации «Культура и туризм» в областном конкурсе проектов в сфере культуры «Звездное кружево Севера» и 2-е место в номинации «Проект, реализованный сельским культурно-досуговым учреждением клубного типа» во всероссийском конкурсе «Дом культуры. Новый формат»! </p><p> </p> <p></p>', NULL, 'Lera.fill.filatova@mail.ru', '[{"value": "78172551022"}, {"value": "78172551035"}]', '{"url": "https://all.culture.ru/uploads/daa9882e3f4225b51fe24bc5cfe08b9d.jpg", "title": "S6NYE-uNsUDswvy8ITqXDgk8pfT1AOgZoA55Cf7A9QF0jEQRjVq6oMDZer-Lou7iq7-2jvNGPmKCWT2HuQOsMPwC.jpg"}', '[{"url": "https://all.culture.ru/uploads/ddb7f636c4261c258fee2918054137c6.jpg", "title": "CYopGCS8KXmiSfxDkLVsL3p__7ZBlgJLau-yAS0Pet8ZSBdUuNE7BDZM4OCZfNnZyNk898dI9TLHHkp8CEhizAJB.jpg"}, {"url": "https://all.culture.ru/uploads/6d36b426d80340bc9955489350509ed4.jpg", "title": "Q6l0lcvPEnMcRXerTd_tQP3K-DQo8jCTVXhEmMIxR4yT22EOzJddsOsDoazYTIJUsXYcKeimzjNi0YxR-9OCkI3-.jpg"}, {"url": "https://all.culture.ru/uploads/39e761327a721b2083898becb88fcf19.jpg", "title": "SU9TfnQem8DH8HIxh-kv47nTQlD9THp6yyHnkPVwJAiyag2tpXKZbtv9tfh4tVpPd44YuTNKBA3HWBVvui9_nhrA.jpg"}, {"url": "https://all.culture.ru/uploads/f10cb32893f8b790c7ec821919b40ea3.jpg", "title": "BBSrOz-iXmXnD71ABv5Jdj00fhguorJf8NAd_PE_FbK7JfjOmq4x9EeHtIAAITvlFsWmEddt_j2CSJ73wr8BDaQs.jpg"}, {"url": "https://all.culture.ru/uploads/6665aa69f9a897566b1cca21df2c9a15.jpg", "title": "KGUbI9aoVuquINAjczB8m40yO49QmiGBU3iWA7od--M_P7mHZW3JAgzBoUD1eD0TNFZHVVjO2pdG3YimWQ0Y5Sd8.jpg"}]', NULL, 'Дворцы культуры и клубы', 'МБУК ВМО «Центр культурного развития»', 'Вологодский район', 'Europe/Moscow', 'ул Ленина,д 50', NULL, 'обл Вологодская,р-н Вологодский,с Кубенское,ул Ленина,д 50', NULL, 3525221703, 'mincult', 'Вологодский район', 'Europe/Moscow', NULL, 26358, '[{"id": 42, "name": "Культурные центры", "sysName": "kulturnye-centry"}, {"id": 26, "name": "Современное искусство", "sysName": "sovremennoe-iskusstvo"}, {"id": 29, "name": "Музыка", "sysName": "muzyka"}, {"id": 596, "name": "Доступная среда", "sysName": "dostupnaya-sreda"}, {"id": 25, "name": "Классическое искусство", "sysName": "klassicheskoe-iskusstvo"}, {"id": 39, "name": "Для детей", "sysName": "dlya-detey"}]', NULL, NULL, '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', '{"to": "18:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 94830, NULL, 94830, NULL, NULL, NULL, '2026-10-02 17:25:35+03', '2026-10-12 17:39:57+03', '0101000020E6100000406CE9D1549743408A1F63EE5A9A4D40');
INSERT INTO culture_data.culture_palaces_clubs VALUES ('Центр традиционной народной культуры г. Харовска', 'Харовский район', 'Europe/Moscow', 'ул Клубная,д 18', NULL, 'обл Вологодская,р-н Харовский,г Харовск,ул Клубная,д 18', '{"type": "Point", "coordinates": [40.185128, 59.970871]}', '<p>Центр традиционной народной культуры был образован в 1994 году. Главное – экспедиционная работа, изучение, восстановление и сохранение традиционных изделий, сбор этнографических образцов.</p><p>В Центре работают различные студии детского творчества, 20 клубных формирований по интересам для детей, молодежи и взрослых. Проводятся экскурсии по мастерским и мастер-классы. Здесь можно научиться таким ремеслам: ткачество на старинных напольных ткацких станках, плести вологодское кружево, шить народные костюмы, изготавливать традиционные народные куклы, резьбе по дереву, рисованию и росписи по дереву. Участники принимают участие в областных и всероссийских конкурсах и выставках творчества, где занимают высокие места.</p><p>Ведутся занятия по фольклору. Проходят различные выставки творчества, проводятся традиционные народные мероприятия и концерты. </p><p>Хор ветеранов, народный фольклорный ансамбль «Тальяночка», народный вокальный ансамбль «Сударушки», детская вокальная студия «Гармония» выступают не только на сцене ЦТНК, но и участвуют в городских, окружных, областных мероприятиях и конкурсах.</p>', 'http://cnk-harovsk.vlg.muzkult.ru', 'zaharova.ev@haradm.gov35.ru', '[{"value": "78173232155"}]', '{"url": "https://all.culture.ru/uploads/2c2084146c47738af22fae02dd644b70.jpg", "title": "здание ЦТНК.jpg"}', NULL, NULL, 'Дворцы культуры и клубы', 'МБУК «ЦТНК»', 'Харовский район', 'Europe/Moscow', 'ул Клубная,д 18', NULL, 'обл Вологодская,р-н Харовский,г Харовск,ул Клубная,д 18', NULL, 3521004810, 'mincult', 'Харовский район', 'Europe/Moscow', NULL, 40818, NULL, NULL, NULL, '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', '{"to": "17:00:00", "from": "10:00:00"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 95360, NULL, 95360, NULL, NULL, NULL, '2026-11-05 16:26:38+03', '2026-11-11 15:59:49+03', '0101000020E610000075C93846B217444042D13C8045FC4D40');


